del.selWareType'').setReadonly(true);\n\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').removeValue();\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').removeValue();\n        ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').removeValue();\n        // 设置是否必填样式\n        ReactAPI.getComponentAPI().Label.APIs(''factoryModel.wareId.code'').setNullableStyle(false);\n        // 取消必填\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setRequired(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(false);\n        \n        ReactAPI.getComponentAPI().Label.APIs(''factoryModel.storeId.code'').setNullableStyle(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(false)\n\n    } else {\n        let code = nodeTypes[0].code;\n        if (code == ''006'' || code == ''005''){\n            // ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(false);\n            // ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(false);\n            \n            ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').setReadonly(false);\n        } else {\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(true);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(true);\n            \n            ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').setReadonly(true);\n\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').removeValue();\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').removeValue();\n            ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').removeValue();\n            // 设置是否必填样式\n            ReactAPI.getComponentAPI().Label.APIs(''factoryModel.wareId.code'').setNullableStyle(false);\n            // 取消必填\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setRequired(false);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(false);\n            \n            ReactAPI.getComponentAPI().Label.APIs(''factoryModel.storeId.code'').setNullableStyle(false);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(false);\n        }\n    }\n    //节点类型为生产线/过程组元/生产单元时，“是否包装线”可以编辑、装置可编辑\n    if(nodeTypes.length && nodeTypes[0].code == \"004\") {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(false);\n    }else {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setValue(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(true);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').removeValue();\n    } \n\n    if(nodeTypes.length && (nodeTypes[0].code == \"005\" || nodeTypes[0].code == \"006\")) {\n        //配料系统值可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(false);\n    }else {\n        //配料系统值不可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setValue(null);\n    }\n    \n}","sourcepropertyname":"factoryModel.nodeTypeId","funcname":"onchange=''onTypeChange()''","regionType":"EDIT","topAssName":"id","rowspan":1,"cellCo