'Reference'').APIs(''factoryModel.equipName.name'').setReadonly(false);\n    } else {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setValue(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(true);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').removeValue();\n    }\n\n    if (nodeTypes.length && (nodeTypes[0].code == \"005\" || nodeTypes[0].code == \"006\")) {\n        //配料系统值可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(false);\n    } else {\n        //配料系统值不可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setValue(null);\n    }\n}","type":"layoutCell","element":{"showTypeHasChanged":true,"couple":true,"onlyLeaf":false,"iscontrol":false,"nullable":true,"isOfficeHandSign":false,"showFormatHasChanged":true,"isRevision":false,"defaultValueHasChanged":false,"dbColumnType":"TEXT","referenceview":{"code":"HierarchicalMod_1.0.0_factoryNodeType_nodeTypeRef","iscrosscompany":"false","name":"nodeTypeRef","title":"HierarchicalMod.viewtitle.randon1573200288643","mneType":"other","url":"/msService/HierarchicalMod/factoryNodeType/facNodeType/nodeTypeRef","openType":"frame"},"propertyCode":"HierarchicalMod_1.0.0_factoryModel_FactoryModel_nodeTypeId||HierarchicalMod_1.0.0_factoryNodeType_FacNodeType_name","readonly":false,"elalign":"left","convertPdfOnLine":true,"modelCode":"HierarchicalMod_1.0.0_factoryNodeType_FacNodeType","complex":false,"showType":"SELECTCOMP","isgroup":false,"isCreateNew":false,"officeNotNull":false,"mneenable":false,"isOfficeSign":false,"columnType":"TEXT","isTitle":true,"isrefselect":false,"modelcode":"HierarchicalMod_1.0.0_factoryNodeType_