Is(''factoryModel.nodeTypeId.name'').getValue();\nif(nodeType.length) {\n    // 如果不从顶级节点创建，需要获取上一级节点\n    let parentId = ReactAPI.getParamsInRequestUrl().parentId ? ReactAPI.getParamsInRequestUrl().parentId : ReactAPI.getFormData().parentId;\n    if (parentId && parentId > 0) {\n        // 获取父节点\n        let parent = null;\n        ReactAPI.request(\n            {\n                type: \"get\",\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + parentId,\n                async: false\n            },\n            res => {\n                parent = res.data;\n            }\n        );\n        // 如果选择类型的id小于父节点类型的id\n        if (parent.nodeTypeId){\n            if (nodeType[0].id <= parent.nodeTypeId.id) {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t  \n                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1573436074669'', parent.nodeTypeId.name));\n                ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').setValidateStyle(''error'');\n                return false;\n            }\n        } \n    }\n    //检查当前节点是否是生产线、工作单元组、工作单元，如是，则判断上层节点否有工作区域\n    // let nodeTypeID = nodeType[0].id; \n    // if(nodeTypeID>=1003){\n    //     let IsWorkArea=false;\n    //     ReactAPI.request(\n    //         {\n    //             type: \"get\",\n    //             url: \"/msService/HierarchicalMod/factoryModel/factoryModel/getWorkShopIsEnable/\" + parentId,\n    //             async: false\n    //         },\n    //         res=>{\n    //             IsWorkArea = res.data.workArea;\n    //         });\n    //     if(!IsWorkArea){ \n    //         // 上级节点必须有生产区域类型的节点\n    //         ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1591840508749'', parent.nodeTypeId.name));\n    //         return false;\n    //     }\n    // }\n}\n\n// 设备页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'']) {\n\tlet equipDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'');\n    for (let item of equipDataGrid.getDatagridData()) {\n        // 设备位号和设备名称至少保证一个中有内容\n        if (item.isFixed) {\n            // 当固定位号勾选 时，设备位号和设备名称至少添加一项\n            if ((item.equipmentNum === null || !item.equipmentNum.trim()) && (item.objEqu === null || !item.objEqu.id)) {\n                let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585097165367'', ReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), item.rowIndex + 1);\n                ReactAPI.showMessage(\"f\", message);\n                return false;\n            }\n        } else {\n            // 当固定位号没有勾选时，设备名称需有内容 <b>页签【{0}】</b><br>“{1}” 第{2}行不允许为空！\n            if (item.name === null || !item.name) {\n                let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585105550077'', \n\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), ReactAPI.international.getText(''HierarchicalMod.equip.AccessoryDev.name''), item.rowIndex + 1);\n                ReactAPI.showMessage(\"f\", message);\n                return false;\n            }\n\t\t}\n\t\t\n\t\t// if (item.selWareType.value == \"指定\") {\n\t\t// \tif (!item.wareId.id) {\n\t\t// \t\t// <b>页签【{0}】</b><br> 第{1}行，仓库指定方式为【指定】，仓库不允许为空！\n\t\t// \t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1597389653474'', ''设备'', item.rowIndex + 1));\n\t\t// \t\treturn false;\n\t\t// \t}\n\t\t// }\n\n    }\n}\n// 仓库页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'']) {\n    let wareDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'');\n    for (let item of wareDataGrid.getDatagridData()) {\n        // 启用货位时，货位必填\n        if (item.objWareId && item.objWareId.warehouseState && item.objWareId.warehouseState.value && !item.objStoreId) {\n            let message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549406324'', ReactAPI.international.getText(''HierarchicalMod.factoryWareMaterial.FactoryMateria.wareId''), item.rowIndex + 1) + \"，\" + ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549502918'');\n            ReactAPI.showMessage(\"f\", message);\n            return false;\n        }\n    }\n}\n\n//测点页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'']) {\n    let tagDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'');\n\t// 测点和测点标签不能重复\n    for (let item of tagDataGrid.getDatagridData()) {\n\t\tlet i = item.rowIndex;\n\t\tlet tagId = item.objTagId.id;\n\t\tlet paramLabel = item.paramLabel;\n\t\tfor (let item2 of tagDataGrid.getDatagridData()) {\n\t\t\tif(i != item2.rowIndex){\n\t\t\t\tif (item2.objTagId.id == tagId) {\n\t\t\t\t\tlet message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i+1, item2.rowIndex+1,\n\t\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.technologyCard.TechCard.tagNameStr''));\n\t\t\t\t\tReactAPI.showMessage(\"f\", message);\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t\tif(item2.paramLabel == paramLabel){\n\t\t\t\t\tlet message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i+1 , item2.rowIndex+1,\n\t\t\t\t\t\tReactAPI.international.getText(''HierarchicalMod.factoryModel.TagInfos.paramLabel''));\n\t\t\t\t\tReactAPI.showMessage(\"f\", message);\n\t\t\t\t\treturn false;\n\t\t\t\t}\t\n\t\t\t}\n\t\t}\n    }\n}","name":"onsave"},{"function":"//隐藏装置tab\n//ReactAPI.Layout.hideTab(\"tabs-29\");\n$(\"#factoryModel_endItemId_name\").attr(\"style\", \"display:none;\");\n$(\"#label_factoryModel_endItemId_name\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_assignBatchNoId_name\").attr(\"style\", \"display:none;\");\n$(\"#label_factoryModel_assignBatchNoId_name\").attr(\"style\", \"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_workshopId\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_workshopId\").attr(\"style\", \"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_lineId\").attr(\"style\", \"display:none;\");\n$(\"#factoryModel_lineId\").attr(\"style\", \"display:none;\");\n\nvar nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\nif (nodeTypes.length) {\n    var code = nodeTypes[0].code;\n    if (code == ''006'' || code == ''005'') {\n        ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').setReadonly(false);\n        //配料系统值可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(false);\n    }\n    //获取节点类型,如果为节点类型为生产线/过程组元/生产单元时，“是否包装线”可以编辑，装置可编辑\n    if (code == \"004\") {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(false);\n    }\n}\nvar selWareTypeSystemCode = ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'');\nvar selWareType = selWareTypeSystemCode.getValue();\nif (selWareType.value) {\n    // 指定\n    if (selWareType.value == ''HierarchicalMod_selWareType/allocate'') {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setRequired(true);\n        ReactAPI.getComponentAPI().Label.APIs(''factoryModel.wareId.code'').setNullableStyle(true);\n\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(false);\n        var storesetState = ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.wareId.storesetState'').getValue();\n        if (storesetState.value) {\n            ReactAPI.getComponentAPI().Label.APIs(''factoryModel.storeId.code'').setNullableStyle(true);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(true);\n        }\n    }\n    // 映射\n    if (selWareType.value == ''HierarchicalMod_selWareType/mapping'') {\n        // 是否只读\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(true);\n    }\n}\n\n// 隐藏仓库与计量点\n//$(''.ant-tabs-nav-wrap .ant-tabs-tab:gt(5)'').hide();\nif (ReactAPI.getParamsInRequestUrl().id) {\n    // 节点编码字段不能修改\n    ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.code'').setReadonly(true);\n    // 如果已选外部系统，则外部系统也不能修改\n    if (ReactAPI.getFormData().isOtherSystem) {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.objFactoryIdSystemObjId'').setReadonly(true);\n    }\n    // 节点类型\n    var _nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\n    if (_nodeTypes.length && _nodeTypes[0].id <= 1002) {\n        // 如果选择的节点为“企业”、“工厂”、“生产区域”时，部门必填\n        ReactAPI.getComponentAPI(''Reference'').APIs(\"factoryModel.departmentId.name\").setRequired(true);\n        ReactAPI.getComponentAPI(''Label'').APIs(\"factoryModel.departmentId.name\").setNullableStyle(true);\n    }\n}\n// 新增时\nelse {\n        // 有父节点\n        if (ReactAPI.getParamsInRequestUrl().parentId && ReactAPI.getParamsInRequestUrl().parentId > 0) {\n            // 获取父节点\n            ReactAPI.request({\n                type: \"get\",\n                data: {},\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + ReactAPI.getParamsInRequestUrl().parentId\n            }, function (res) {\n                console.log(res);\n                if (res.code == 200) {\n                    var data = res.data;\n                    // 如父节点类型为生产区域或生产线时，回填父节点id到相应字\n                    if (data.nodeTypeId) {\n                        if (data.nodeTypeId.id == 1002) {\n                            ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.workshopId\").setValue(Number(ReactAPI.getParamsInRequestUrl().parentId));\n                        }\n                        if (data.nodeTypeId.id == 1003) {\n                            ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.lineId\").setValue(Number(ReactAPI.getParamsInRequestUrl().parentId));\n                        }\n                    }\n                    // 如父级节点的部门有值，自动赋值给当前节点\n                    if (data.departmentId) {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.departmentId.name'').setValue(data.departmentId);\n                    }\n                    if (data.workshopId) {\n                        ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.workshopId\").setValue(Number(data.workshopId));\n                    }\n                    if (data.lineId) {\n                        ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.lineId\").setValue(Number(data.lineId));\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            });\n        }\n    }\n\n// 判断是否有errorMessage，有则显示\nvar id = ReactAPI.getParamsInRequestUrl().id;\nvar keyName = ''syncBatch_factoryModel_'' + id;\nif (id && sessionStorage.getItem(keyName)) {\n    ReactAPI.showMessage(''f'', sessionStorage.getItem(keyName));\n    // 删除errorMessage\n    sessionStorage.removeItem(keyName);\n}\n\n//载入时，查看基础模型配置，是否启用批控的值\nvar isBatch = false;\nReactAPI.request({\n    type: \"post\",\n    async: false,\n    data: {},\n    url: \"/msService/HierarchicalMod/factoryModel/factoryModel/getBatchIsEnable\"\n}, function (res) {\n    console.log(res);\n    isBatch = res.data.batchIsEnable;\n});\n\nReactAPI.submitCallback(function (result) {\n    console.log(\" isBatch  :\" + isBatch);\n    // 如果需要同步批控 且选择了外部系统\n    if (isBatch && ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.objFactoryIdSystemObjId'').getValue().length) {\n        console.log(111);\n        if (result.code == 200) {\n            if (opener) {\n                // 获取parentId\n                var parentId = ReactAPI.getParamsInRequestUrl().parentId ? ReactAPI.getParamsInRequestUrl().parentId : ReactAPI.getFormData().parentId;\n                // 刷新树\n                opener.ReactAPI.getComponentAPI(\"NavTree\").APIs(\"HierarchicalMod_1.0.0_factoryModel_factoryTreeList_factoryModel_nt\").refreshTreeNode(parentId);\n                // 刷新节点列表\n                opener.$(''button[data-id=\"query\"]'').click();\n            }\n            // 节点id\n            var id = result.data.id;\n            // 同步节点到外部系统\n            ReactAPI.request({\n                type: \"post\",\n                async: false,\n                data: {},\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/syncOtherSystem/\" + id\n            }, function (res) {\n                console.log(111);\n                if (res.code == 200) {\n                    var data = res.data;\n                    if (!data.dealSuccessFlag) {\n                        sessionStorage.setItem(''syncBatch_factoryModel_'' + id, data.errorMessage);\n                        var url = \"/msService/HierarchicalMod/factoryModel/factoryModel/factoryEdit?viewCode=HierarchicalMod_1.0.0_factoryModel_factoryTreeList&entityCode=HierarchicalMod_1.0.0_factoryModel&__pc__=\" + ReactAPI.getParamsInRequestUrl()[''__pc__''] + \"&openType=frame&id=\" + id;\n                        location.replace(url);\n                    }\n                }\n            });\n        }\n    }\n});","name":"onload_es5"},{"function":"//隐藏装置tab\n//ReactAPI.Layout.hideTab(\"tabs-29\");\n$(\"#factoryModel_endItemId_name\").attr(\"style\",\"display:none;\");\n$(\"#label_factoryModel_endItemId_name\").attr(\"style\",\"display:none;\");\n$(\"#factoryModel_assignBatchNoId_name\").attr(\"style\",\"display:none;\");\n$(\"#label_factoryModel_assignBatchNoId_name\").attr(\"style\",\"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_workshopId\").attr(\"style\",\"display:none;\");\n$(\"#factoryModel_workshopId\").attr(\"style\",\"display:none;\");\n\n//生产区域id\n$(\"#label_factoryModel_lineId\").attr(\"style\",\"display:none;\");\n$(\"#factoryModel_lineId\").attr(\"style\",\"display:none;\");\n\nlet nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\nif (nodeTypes.length){\n    let code = nodeTypes[0].code;\n    if (code == ''006'' ||　code == ''005''){\n        ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'').setReadonly(false);\n        //配料系统值可编辑\n        ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.burdenValue'').setReadonly(false);\n    }\n    //获取节点类型,如果为节点类型为生产线/过程组元/生产单元时，“是否包装线”可以编辑，装置可编辑\n    if(code == \"004\") {\n        ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.packageLine'').setReadonly(false);\n        //ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.equipName.name'').setReadonly(false);\n    }\n}\nlet selWareTypeSystemCode = ReactAPI.getComponentAPI(''SystemCode'').APIs(''factoryModel.selWareType'');\nlet selWareType= selWareTypeSystemCode.getValue();\nif(selWareType.value){\n    // 指定\n    if (selWareType.value == ''HierarchicalMod_selWareType/allocate''){\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setRequired(true)\n        ReactAPI.getComponentAPI().Label.APIs(''factoryModel.wareId.code'').setNullableStyle(true);\n            \n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(false);\n        let storesetState = ReactAPI.getComponentAPI(''Checkbox'').APIs(''factoryModel.wareId.storesetState'').getValue();\n        if (storesetState.value) {\n            ReactAPI.getComponentAPI().Label.APIs(''factoryModel.storeId.code'').setNullableStyle(true);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setRequired(true)\n        }\n    }\n    // 映射\n    if(selWareType.value == ''HierarchicalMod_selWareType/mapping''){\n        // 是否只读\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.storeId.code'').setReadonly(true);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.wareId.code'').setReadonly(true)\n    }\n}\n\n// 隐藏仓库与计量点\n//$(''.ant-tabs-nav-wrap .ant-tabs-tab:gt(5)'').hide();\nif (ReactAPI.getParamsInRequestUrl().id) {\n    // 节点编码字段不能修改\n    ReactAPI.getComponentAPI(''Input'').APIs(''factoryModel.code'').setReadonly(true);\n    // 如果已选外部系统，则外部系统也不能修改\n    if (ReactAPI.getFormData().isOtherSystem) {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.objFactoryIdSystemObjId'').setReadonly(true);\n    }\n    // 节点类型\n    let nodeTypes = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue()\n    if (nodeTypes.length && nodeTypes[0].id <= 1002) {\n        // 如果选择的节点为“企业”、“工厂”、“生产区域”时，部门必填\n        ReactAPI.getComponentAPI(''Reference'').APIs(\"factoryModel.departmentId.name\").setRequired(true);\n        ReactAPI.getComponentAPI(''Label'').APIs(\"factoryModel.departmentId.name\").setNullableStyle(true);\n    } \n}\n// 新增时\nelse {\n    // 有父节点\n    if (ReactAPI.getParamsInRequestUrl().parentId && ReactAPI.getParamsInRequestUrl().parentId > 0) {\n        // 获取父节点\n        ReactAPI.request(\n            {\n                type: \"get\",\n                data: {},\n                url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + ReactAPI.getParamsInRequestUrl().parentId\n            },\n            (res) => {\n                console.log(res);\n                if (res.code==200) {\n                    let data = res.data;\n                    // 如父节点类型为生产区域或生产线时，回填父节点id到相应字\n                    if (data.nodeTypeId ){\n                        if(data.nodeTypeId.id == 1002){\n                            ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.workshopId\").setValue(Number(ReactAPI.getParamsInRequestUrl().parentId));\n                        }\n                        if(data.nodeTypeId.id == 1003){\n                            ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.lineId\").setValue(Number(ReactAPI.getParamsInRequestUrl().parentId));\n                        }\n                    }\n                    // 如父级节点的部门有值，自动赋值给当前节点\n                    if (data.departmentId) {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.departmentId.name'').setValue(data.departmentId);\n                    }\n                    if (data.workshopId){\n                        ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.workshopId\").setValue(Number(data.workshopId));\n                    }\n                    if (data.lineId){\n                        ReactAPI.getComponentAPI(''InputNumber'').APIs(\"factoryModel.lineId\").setValue(Number(data.lineId));\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            }\n        );\n    }\n}\n\n// 判断是否有errorMessage，有则显示\nlet id = ReactAPI.getParamsInRequestUrl().id;\nlet keyName = ''syncBatch_factoryModel_'' + id;\nif (id && sessionStorage.getItem(keyName)) {\n    ReactAPI.showMessage(''f'', sessionStorage.getItem(keyName));\n    // 删除errorMessage\n    sessionStorage.removeItem(keyName);\n}\n\n//载入时，查看基础模型配置，是否启用批控的值\nvar isBatch = false;\nReactAPI.request(\n    {\n        type: \"post\",\n        async: false,\n        data: {},\n        url: \"/msService/HierarchicalMod/factoryModel/factoryModel/getBatchIsEnable\"\n    },\n    function (res) {\n        console.log(res);\n        isBatch = res.data.batchIsEnable;\n    }\n);\n\n\nReactAPI.submitCallback(function (result) {\n    console.log(\" isBatch  :\" + isBatch);\n    // 如果需要同步批控 且选择了外部系统\n    if (isBatch && ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.objFactoryIdSystemObjId'').getValue().length) {\n        console.log(111);\n        if (result.code==200) {\n            if (opener) {\n                // 获取parentId\n                let parentId = ReactAPI.getParamsInRequestUrl().parentId ? ReactAPI.getParamsInRequestUrl().parentId : ReactAPI.getFormData().parentId;\n                // 刷新树\n                opener.ReactAPI.getComponentAPI(\"NavTree\")\n                    .APIs(\"HierarchicalMod_1.0.0_factoryModel_factoryTreeList_factoryModel_nt\")\n                    .refreshTreeNode(parentId);\n                // 刷新节点列表\n                opener.$(''button[data-id=\"query\"]'').click();\n            }\n            // 节点id\n            var id = result.data.id;\n            // 同步节点到外部系统\n            ReactAPI.request(\n                {\n                    type: \"post\",\n                    async: false,\n                    data: {},\n                    url: \"/msService/HierarchicalMod/factoryModel/factoryModel/syncOtherSystem/\" + id\n                },\n                function (res) {\n                    console.log(111);\n                    if (res.code==200) {\n                        let data = res.data;\n                        if (!data.dealSuccessFlag) {\n                            sessionStorage.setItem(''syncBatch_factoryModel_'' + id, data.errorMessage);\n                            var url = \"/msService/HierarchicalMod/factoryModel/factoryModel/factoryEdit?viewCode=HierarchicalMod_1.0.0_factoryModel_factoryTreeList&entityCode=HierarchicalMod_1.0.0_factoryModel&__pc__=\" + ReactAPI.getParamsInRequestUrl()[''__pc__''] + \"&openType=frame&id=\" + id;\n                            location.replace(url);\n                        }\n                    }\n                }\n            );\n        }\n    }\n});","name":"onload"},{"function":"var nodeType = ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').getValue();\nif (nodeType.length) {\n    // 如果不从顶级节点创建，需要获取上一级节点\n    var parentId = ReactAPI.getParamsInRequestUrl().parentId ? ReactAPI.getParamsInRequestUrl().parentId : ReactAPI.getFormData().parentId;\n    if (parentId && parentId > 0) {\n        // 获取父节点\n        var parent = null;\n        ReactAPI.request({\n            type: \"get\",\n            url: \"/msService/HierarchicalMod/factoryModel/factoryModel/data/\" + parentId,\n            async: false\n        }, function (res) {\n            parent = res.data;\n        });\n        // 如果选择类型的id小于父节点类型的id\n        if (parent.nodeTypeId) {\n            if (nodeType[0].id <= parent.nodeTypeId.id) {\n\n                ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1573436074669'', parent.nodeTypeId.name));\n                ReactAPI.getComponentAPI(''Reference'').APIs(''factoryModel.nodeTypeId.name'').setValidateStyle(''error'');\n                return false;\n            }\n        }\n    }\n    //检查当前节点是否是生产线、工作单元组、工作单元，如是，则判断上层节点否有工作区域\n    // let nodeTypeID = nodeType[0].id; \n    // if(nodeTypeID>=1003){\n    //     let IsWorkArea=false;\n    //     ReactAPI.request(\n    //         {\n    //             type: \"get\",\n    //             url: \"/msService/HierarchicalMod/factoryModel/factoryModel/getWorkShopIsEnable/\" + parentId,\n    //             async: false\n    //         },\n    //         res=>{\n    //             IsWorkArea = res.data.workArea;\n    //         });\n    //     if(!IsWorkArea){ \n    //         // 上级节点必须有生产区域类型的节点\n    //         ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1591840508749'', parent.nodeTypeId.name));\n    //         return false;\n    //     }\n    // }\n}\n\n// 设备页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'']) {\n    var equipDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202192487'');\n    var _iteratorNormalCompletion = true;\n    var _didIteratorError = false;\n    var _iteratorError = undefined;\n\n    try {\n        for (var _iterator = equipDataGrid.getDatagridData()[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n            var item = _step.value;\n\n            // 设备位号和设备名称至少保证一个中有内容\n            if (item.isFixed) {\n                // 当固定位号勾选 时，设备位号和设备名称至少添加一项\n                if ((item.equipmentNum === null || !item.equipmentNum.trim()) && (item.objEqu === null || !item.objEqu.id)) {\n                    var message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585097165367'', ReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), item.rowIndex + 1);\n                    ReactAPI.showMessage(\"f\", message);\n                    return false;\n                }\n            } else {\n                // 当固定位号没有勾选时，设备名称需有内容 <b>页签【{0}】</b><br>“{1}” 第{2}行不允许为空！\n                if (item.name === null || !item.name) {\n                    var _message = ReactAPI.international.getText(''HierarchicalMod.custom.randon1585105550077'', ReactAPI.international.getText(''HierarchicalMod.tabnamenew2.randon1597233997319.flag''), ReactAPI.international.getText(''HierarchicalMod.equip.AccessoryDev.name''), item.rowIndex + 1);\n                    ReactAPI.showMessage(\"f\", _message);\n                    return false;\n                }\n            }\n\n            // if (item.selWareType.value == \"指定\") {\n            // \tif (!item.wareId.id) {\n            // \t\t// <b>页签【{0}】</b><br> 第{1}行，仓库指定方式为【指定】，仓库不允许为空！\n            // \t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''HierarchicalMod.custom.randon1597389653474'', ''设备'', item.rowIndex + 1));\n            // \t\treturn false;\n            // \t}\n            // }\n        }\n    } catch (err) {\n        _didIteratorError = true;\n        _iteratorError = err;\n    } finally {\n        try {\n            if (!_iteratorNormalCompletion && _iterator.return) {\n                _iterator.return();\n            }\n        } finally {\n            if (_didIteratorError) {\n                throw _iteratorError;\n            }\n        }\n    }\n}\n// 仓库页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'']) {\n    var wareDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1573202120574'');\n    var _iteratorNormalCompletion2 = true;\n    var _didIteratorError2 = false;\n    var _iteratorError2 = undefined;\n\n    try {\n        for (var _iterator2 = wareDataGrid.getDatagridData()[Symbol.iterator](), _step2; !(_iteratorNormalCompletion2 = (_step2 = _iterator2.next()).done); _iteratorNormalCompletion2 = true) {\n            var _item = _step2.value;\n\n            // 启用货位时，货位必填\n            if (_item.objWareId && _item.objWareId.warehouseState && _item.objWareId.warehouseState.value && !_item.objStoreId) {\n                var _message2 = ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549406324'', ReactAPI.international.getText(''HierarchicalMod.factoryWareMaterial.FactoryMateria.wareId''), _item.rowIndex + 1) + \"，\" + ReactAPI.international.getText(''HierarchicalMod.custom.randon1573549502918'');\n                ReactAPI.showMessage(\"f\", _message2);\n                return false;\n            }\n        }\n    } catch (err) {\n        _didIteratorError2 = true;\n        _iteratorError2 = err;\n    } finally {\n        try {\n            if (!_iteratorNormalCompletion2 && _iterator2.return) {\n                _iterator2.return();\n            }\n        } finally {\n            if (_didIteratorError2) {\n                throw _iteratorError2;\n            }\n        }\n    }\n}\n\n//测点页签\nif (ReactAPI.getComponentAPI(''SupDataGrid'')[''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'']) {\n    var tagDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''HierarchicalMod_1.0.0_factoryModel_factoryEditdg1597279515664'');\n    // 测点和测点标签不能重复\n    var _iteratorNormalCompletion3 = true;\n    var _didIteratorError3 = false;\n    var _iteratorError3 = undefined;\n\n    try {\n        for (var _iterator3 = tagDataGrid.getDatagridData()[Symbol.iterator](), _step3; !(_iteratorNormalCompletion3 = (_step3 = _iterator3.next()).done); _iteratorNormalCompletion3 = true) {\n            var _item2 = _step3.value;\n\n            var i = _item2.rowIndex;\n            var tagId = _item2.objTagId.id;\n            var paramLabel = _item2.paramLabel;\n            var _iteratorNormalCompletion4 = true;\n            var _didIteratorError4 = false;\n            var _iteratorError4 = undefined;\n\n            try {\n                for (var _iterator4 = tagDataGrid.getDatagridData()[Symbol.iterator](), _step4; !(_iteratorNormalCompletion4 = (_step4 = _iterator4.next()).done); _iteratorNormalCompletion4 = true) {\n                    var item2 = _step4.value;\n\n                    if (i != item2.rowIndex) {\n                        if (item2.objTagId.id == tagId) {\n                            var _message3 = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i + 1, item2.rowIndex + 1, ReactAPI.international.getText(''HierarchicalMod.technologyCard.TechCard.tagNameStr''));\n                            ReactAPI.showMessage(\"f\", _message3);\n                            return false;\n                        }\n                        if (item2.paramLabel == paramLabel) {\n                            var _message4 = ReactAPI.international.getText(''HierarchicalMod.custom.randon1599793866407'', i + 1, item2.rowIndex + 1, ReactAPI.international.getText(''HierarchicalMod.factoryModel.TagInfos.paramLabel''));\n                            ReactAPI.showMessage(\"f\", _message4);\n                            return false;\n                        }\n                    }\n                }\n            } catch (err) {\n                _didIteratorError4 = true;\n                _iteratorError4 = err;\n            } finally {\n                try {\n                    if (!_iteratorNormalCompletion4 && _iterator4.return) {\n                        _iterator4.return();\n                    }\n                } finally {\n                    if (_didIteratorError4) {\n                        throw _iteratorError4;\n                    }\n                }\n            }\n        }\n    } catch (err) {\n        _didIteratorError3 = true;\n        _iteratorError3 = err;\n    } finally {\n        try {\n            if (!_iteratorNormalCompletion3 && _iterator3.return) {\n                _iterator3.return();\n            }\n        } finally {\n            if (_didIteratorError3) {\n                throw _iteratorError3;\n            }\n        }\n    }\n}","name":"onsave_es5"}]}', 0)
