,\n                onClick: event => {\n                    //防止重复提交\n                    var isSubmit = false;\n                    if (!isSubmit) {\n                        //获取表格对象\n                        var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"HierarchicalMod_1.0.0_factoryWare_factoryRepairEditdg1600736387426\");\n                        //获取表格数据\n                        var tableData = editTable.getDatagridData();\n                        if (!tableData.length) {\n                            // 请确认表体至少添加一条数据！\n                            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"HierarchicalMod.custom.randon1602826097797\"));\n                            return false;\n                        }\n                        for (let i = 0; i < tableData.length; i++) {\n                            if (!tableData[i].stockNum || tableData[i].stockNum < 0) {\n                                event.ReactAPI.submitFormData();\n                                return;\n                            }\n                        }\n                        var url = \"/msService/HierarchicalMod/factoryWare/factoryWarePre/prePraOrderEdit\";\n                        $.ajax({\n                            type: \"POST\",\n                            url: url,\n                            data: { \"tableData\": JSON.stringify(tableData) },\n                            //请求成功\n                            success: function (result) {\n                                if (result.code == 200) {\n                                    let data = result.data;\n                                    let resultStr = JSON.parse(data.resultStr);\n                                    if (resultStr.data.result === \"单据生成成功！\"|| resultStr.data.result === \"The document is generated successfully!\") {\n                                        // 关闭窗口\n                                        ReactAPI.destroyDialog(dialogName);\n                                