e != null && selMatInfo.validDate != \"\") {\n\t\t\tinvalidDate = new Date(new Date(selMatInfo.validDate).toLocaleDateString()).getTime();\n\t\t}\n\t\t\n\t\tvar errorFlag = false;\n\t\tif(invalidDate != null && invalidDate <= new Date(new Date().toLocaleDateString()).getTime()) {\n\t\t\terrorFlag = true;\n\t\t}\n\t\tif(selMatInfo.matState.id != \"LIMSMaterial_mATState/available\" || selMatInfo.stockQty <= 0) {\n\t\t\terrorFlag = true;\n\t\t}\n\t\t\n\t\tif(errorFlag) {\n\t\t\t//材料试剂未停用、未销毁、未失效且数量不为0时才可以变更位置！\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"LIMSMaterial.mATInfo.operate.warn.notAllowedChangeStoreSet\"));\n\t\t\treturn false;\n\t\t}\n\t}\n\t\n\tReactAPI.getPowerCode(\"matInfoList_locationChange_add_LIMSMaterial_5.1.0.1_mATInfo_matInfoList\", function(res) {\n\t\tvar powerCode = res[\"matInfoList_locationChange_add_LIMSMaterial_5.1.0.1_mATInfo_matInfoList\"];\n\t\t//打开位置变更编辑页面\n\t\tReactAPI.createDialog(\"matRecordEditDialog\", {\n\t\t\ttitle: ReactAPI.international.getText(\"LIMSMaterial.viewtitle.randon1596776669864\"),\n\t\t\turl: \"/msService/LIMSMaterial/mATInfo/matRecord/matRecordEdit?__pc__=\" + powerCode,\n\t\t\tsize: 2,\n\t\t\tisRef: false, //是否开启参照\n\t\t\tonOk:function(event) {\n\t\t\t\tevent.ReactAPI.submitFormData(\"save\");\n\t\t\t\t//处理记录数据\n\t\t\t\tvar matRecord = event.ReactAPI.getSaveData().matRecord;\n\t\t\t\tvar matRecordJson = JSON.stringify(matRecord);\n\t\t\t\t\n\t\t\t\t//组织材料试剂id串\n\t\t\t\tvar matInfoIds = \"\";\n\t\t\t\tfor(var i = 0; i < matInfoDg.getSelecteds().length; i++) {\n\t\t\t\t\tvar oldStoreSetId = matInfoDg.getSelecteds()[i].storeSetId.id;\n\t\t\t\t\tif(oldStoreSetId != matRecord.storeSetId.id) {\n\t\t\t\t\t\tmatInfoIds += \",\" + matInfoDg.getSelecteds()[i].id;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\tif(matInfoIds == \"\") {\n\t\t\t\t\t//存放位置相同，请重新选择！\n\t\t\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"LIMSMaterial.mATInfo.operate.warn.storeSetInfoSame\"));\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t\t\n\t\t\t\t$.ajax({\n\t\t\t\t\turl: \"/msService/LIMSMaterial/mATInfo/matInfo/updateStoreSet\",\n\t\t\t\t\ttype: ''post'',\n\t\t\t\t\tasync: false,\n\t\t\t\t\tdata: { matInfoIds:matInfoIds.substr(1), matRecordJson:matRecordJson },\n\t\t\t\t\tsuccess: function(res) {\n\t\t\t\t\t\t//ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n\t\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.operate.success\"), \"2\", true);\n\t\t\t\t\t\tsetTimeout(function(){\n\t\t\t\t\t\t\tReactAPI.destroyDialog(\"matRecordEditDialog\");\n\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"LIMSMaterial_5.1.0.1_mATInfo_matInfoList_matInfo_sdg\").refreshDataByRequst();\n\t\t\t\t\t\t}, 1000);\t\n\t\t\t\t\t},\n\t\t\t\t\terror: function(res){\n\t\t\t\t\t\tres = JSON.parse(res.responseText);\n\t\t\t\t\t\tReactAPI.showMessage(\"f\", result.message, ReactAPI.international.getText(''EditView.notice.operate.failure''));\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t},\n\t\t\t//okText:\"保存\",    \n\t\t\tokText: ReactAPI.international.getText(\"EditView.operate.button.submit\"),\n\t\t\tonCancel:function(){\n\t\t\t\tReactAPI.destroyDialog(\"matRecordEditDialog\");   \n\t\t\t}\n\t\t});\n\t});\n}","funcname":"onclick=''locationChange()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":true,"cellCode":"cell_1597025997605_6408","buttonoperationcode":"matInfoList_locationChange_add_LIMSMaterial_5.1.0.1_mATInfo_matInfoList","isHide":false,"showname":"位置变更","ecEnv":"product","pc":"__pc__=bWF0SW5mb0xpc3RfbG9jYXRpb25DaGFuZ2VfYWRkX0xJTVNNYXRlcmlhbF81LjEuMC4xX21BVEluZm9fbWF0SW5mb0xpc3R8","regionType":"BUTTON","iscallback":false,"modelCode":"LIMSMaterial_5.1.0.1_mATInfo_MatInfo","namekey":"LIMSMaterial.buttonPropertyshowName.randon1597026037801.flag","funcbody_es5":"function locationChange() {\n\tvar matInfoDg = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"LIMSM