\tif (selectData[i].cid != userCid) {\n\t\t\tdifferentCompanyMsg += \",\" + (selectData[i].rowIndex + 1);\n\t\t}\n\t}\n\tif (differentCompanyMsg.length > 0) {\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"foundation.data.cross.company\", differentCompanyMsg.substring(1)));\n\t\treturn false;\n\t}\n\n\t//获取collectSimple(简易取样)配置项\n\tvar result = ReactAPI.getSystemConfig(\n\t\t{\n\t\t\tmoduleCode: \"LIMSSample\",\n\t\t\tkey: \"LIMSSample.simpSamplehandle\",\n\t\t\tprofilescAtive: \"\"\n\t\t}\n\t)\n\tvar simpSamplehandle = result[\"LIMSSample.simpSamplehandle\"];\n\t\n\t//若配置项为否,则打开样品取样页面,填写取样信息\n\tif (simpSamplehandle.indexOf(\"collectSimple\") === -1) {\n\t\tReactAPI.createDialog(\"sampleCollectDialog\", {\n\t\t\ttitle: ReactAPI.international.getText(\"LIMSSample.viewtitle.randon1588122600213\"),\n\t\t\turl: \"/msService/LIMSSample/sample/sampleInfo/collectSampleEdit\",\n\t\t\tsize: 2,\n\t\t\tisRef: false, // 是否开启参照\n\t\t\tbuttons: [\n\t\t\t\t{\n\t\t\t\t\ttext: ReactAPI.international.getText(\"EditView.operate.button.submit\"),\n\t\t\t\t\ttype: \"primary\",\n\t\t\t\t\tonClick: function(event) {\n\t\t\t\t\t\tevent.ReactAPI.submitFormData(\"save\");\n\t\t\t\t\t}\t\t\t\t        \t\n\t\t\t\t},\n\t\t\t\t{\n\t\t\t\t\ttext: ReactAPI.international.getText(\"Button.text.cancel\"),\n\t\t\t\t\ttype: \"cancel\",\n\t\t\t\t\tonClick: function(event) {\n\t\t\t\t\t\tReactAPI.destroyDialog(\"sampleCollectDialog\");\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t]\n\t\t});\n\t}else {\n\t\tvar signatureEnabled = ReactAPI.eSign.signatureEnabled({\n\t\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_collectListPart_BUTTON_collect\"\n\t\t});\n\n\t\tif(signatureEnabled){//电子签名启用\n\t\t\t//打开电子签名\n\t\t\tReactAPI.eSign.openEsign({\n\t\t\t\tbuttonCode: \"LIMSSample_5.0.0.0_sample_collectListPart_BUTTON_collect\",\n\t\t\t\tgetSignLog: function(signatureLog) {\t\n\t\t\t\t\tcollectSample(selectData, \"collectSampleSubmit\", signatureLog);\n\t\t\t\t}\n\t\t\t});\n\t\t}else {\n\t\t\tReactAPI.openConfir