要使用平台提供的方法\nlet sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg'');\n// 开始\nsdg.setBtnImg(''btn-startTask'', ''sup-btn-own-qiyong'');\n// 暂停\nsdg.setBtnImg(''btn-pauseTask'', ''sup-btn-own-zt'');\n// 恢复\nsdg.setBtnImg(''btn-recoveryTask'', ''sup-btn-own-hf'');\n// 停止\nsdg.setBtnImg(''btn-stopTask'', ''sup-btn-own-ty'');\n// 提前投料\nsdg.setBtnImg(''btn-earlyPutIn'', ''sup-btn-own-jxtl'');\n//请检\nsdg.setBtnImg(''btn-manuInspect'', ''sup-btn-own-fqqj'');","ratio_h":100,"dbcustomtextarea":"function taskDbClick(event, task) {\n    var status = task.status;\n    var batchContral = task.batchContral;\n\tvar taskRunState = task.taskRunState;\n\t//console.log(taskRunState);\n    var formulaProcess;\n    if (task.formulaId != null && task.formulaId.setProcess != null) {\n        formulaProcess = task.formulaId.setProcess.id;\n    }\n    var url;\n    let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n\n    var url = \"/msService/baseService/user/open-pending?tableInfoId=\" + task.tableInfoId + \"&id=\" + task.id + \"&entityCode=WOM_7.5.0.0_produceTask&__pc__=\" + powerCode;\n\t//\n    console.log(url);\n\n\t//生效单据处理\n    if (status == 99) {\n\t\tif(taskRunState != null &&　taskRunState.id == ''WOM_runState/waitForRun''){\n\t\t\t//待执行的单据打开查看视图\n\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskSubmitView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t}else{\t\n\t\t\tif (!batchContral) {\n\t\t\t\tif (formulaProcess == ''RM_formulaType/commonFormula'') {\n\t\t\t\t\t//标准指令单报工\n\t\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t\t} else {\n\t\t\t\t\t//简易指令单报工\n\t\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/easyTaskOperateView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t\t}\n\t\t\t\n\t\t\t} else {\n\t\t\t\t//批控指令单查看视图\n\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskBatchView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t}\n\t\t}\t\n    }\n\t\n\t//编辑状态双击列表数据正常打开流程单据\n\tif (task.pending != null && task.pending.id!=null && task.pending.deploymentId!=null) {\n        url += \"&pendingId=\" + task.pending.id + \"&deploymentId\" + task.pending.deploymentId;\n    }\n\t\n    makeTaskBatchView = window.open(url);\n}","ptPageInit_es5":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nvar sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg'');\n// 开始\nsdg.setBtnImg(''btn-startTask'', ''sup-btn-own-qiyong'');\n// 暂停\nsdg.setBtnImg(''btn-pauseTask'', ''sup-btn-own-zt'');\n// 恢复\nsdg.setBtnImg(''btn-recoveryTask'', ''sup-btn-own-hf'');\n// 停止\nsdg.setBtnImg(''btn-stopTask'', ''sup-btn-own-ty'');\n// 提前投料\nsdg.setBtnImg(''btn-earlyPutIn'', ''sup-btn-own-jxtl'');\n//请检\nsdg.setBtnImg(''btn-manuInspect'', ''sup-btn-own-fqqj'');","isdbcustom":true,"modelCode":"WOM_1.0.0_produceTask_ProduceTask","downloadXls":"/msService/WOM/produceTask/produceTask/downloadXls","selectFirstRow":false,"renderOver":"if (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"taskRunState\").getOptionById(\"WOM_runState/waitToBeChecked\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"taskRunState\").removeOption(\"WOM_runState/waitToBeChecked\")\n}\nlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg'');\nlet produceTasks = dataGrid.getDatagridData();\nfor (let produceTask of produceTasks) {\n    if (!produceTask.taskRunState) {\n        continue;\n    }\n    // 显示颜色\n    let color;\n    let runState = produceTask.taskRunState.id;\n    if (produceTask.isAbnormal) {\n        // 异常结束，红色\n        color = ''#ff7875'';\n    } else if (runState === ''WOM_runState/waitForRun'') {\n        // 待执行，灰色\n        color = ''#e8e8e8'';\n    } else if (runState === ''WOM_runState/runing'') {\n        // 执行中，绿色\n        color = ''#95de64'';\n    } else if (runState === ''WOM_runState/iskeep'') {\n        // 已暂停，黄色\n        color = ''#fff566'';\n    } else if (runState === ''WOM_runState/finished'') {\n        // 正常结束，蓝色\n        color = ''#69c0ff'';\n    } else {\n        color = ''white'';\n    }\n    // 设置背景颜色\n    dataGrid.setDatagridCellAttr(produceTask.rowIndex, \"taskRunState.value\", { style: { background: color } });\n}\n//判断产品编码是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getDatagridData();\n    let materialId = [];\n    let id;\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].productId != null && data[i].productId.id != null) {\n            materialId.push({ \"materialId\": data[i].productId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code==200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        } else {\n            console.log(res.msg);\n        }\n    }\n    );\n}, 10);","buttons":[{"isSignatureConfig":true,"funcbody":"function startTaskEvent(event) {\n    var selecteds = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getSelecteds();\n    if (selecteds.length == 0) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    var data = selecteds[0];\n    if (data.batchContral) {\n        //只有非批控的工单才可以操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958091725''));\n        return false;\n    }\n    if (data.status != 99) {\n        //请先将指令单生效再进行操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958171058''));\n        return false;\n    }\n    var taskRunState = data.taskRunState.id;\n    if (taskRunState != ''WOM_runState/waitForRun'') {\n        //只能开始执行状态为待执行的指令单\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958246066''));\n        return false;\n    }\n    var taskId = data.id;\n    $.ajax({\n        url: \"/msService/WOM/produceTask/produceTask/updateTaskState\",\n        type: ''post'',\n        async: false,\n        data: { state: \"start\", taskId: taskId },\n        success: function (res) {\n            if (res.code = 200) {\n                let data = res.data;\n                if (data.dealSuccessFlag) {\n                    // 指令单已开始！\n                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''WOM.custom.randon1602655303748''));\n                    let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().currentPage;\n                    let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().pageSize;\n                    let url = \"/msService/WOM/produceTask/produceTask/makeTaskList-query\";\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\")\n                        .refreshDataByRequst({\n                            type: \"POST\",\n                            url: url,\n                            param: {\n                                classifyCodes: \",\",\n                                customCondition: {},\n                                pageNo: currentPage,\n                                paging: true,\n                                pageSize: pageSize,\n                            },\n                        }); //查询刷新PT；\n                } else {\n                    ReactAPI.showMessage(\"f\", data.errorMessage);\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", res.msg);\n            }\n        }\n    });\n}","funcname":"onclick=''startTaskEvent(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1575439162732_788","buttonoperationcode":"makeTaskList_startTask_add_WOM_1.0.0_produceTask_makeTaskList","isHide":false,"showname":"开始","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrTGlzdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_produceTask_ProduceTask","namekey":"WOM.buttonPropertyshowName.randon1575439168443.flag","funcbody_es5":"function startTaskEvent(event) {\n    var selecteds = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getSelecteds();\n    if (selecteds.length == 0) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    var data = selecteds[0];\n    if (data.batchContral) {\n        //只有非批控的工单才可以操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958091725''));\n        return false;\n    }\n    if (data.status != 99) {\n        //请先将指令单生效再进行操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958171058''));\n        return false;\n    }\n    var taskRunState = data.taskRunState.id;\n    if (taskRunState != ''WOM_runState/waitForRun'') {\n        //只能开始执行状态为待执行的指令单\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958246066''));\n        return false;\n    }\n    var taskId = data.id;\n    $.ajax({\n        url: \"/msService/WOM/produceTask/produceTask/updateTaskState\",\n        type: ''post'',\n        async: false,\n        data: { state: \"start\", taskId: taskId },\n        success: function success(res) {\n            if (res.code = 200) {\n                var _data = res.data;\n                if (_data.dealSuccessFlag) {\n                    // 指令单已开始！\n                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''WOM.custom.randon1602655303748''));\n                    var currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().currentPage;\n                    var pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().pageSize;\n                    var url = \"/msService/WOM/produceTask/produceTask/makeTaskList-query\";\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").refreshDataByRequst({\n                        type: \"POST\",\n                        url: url,\n                        param: {\n                            classifyCodes: \",\",\n                            customCondition: {},\n                            pageNo: currentPage,\n                            paging: true,\n                            pageSize: pageSize\n                        }\n                    }); //查询刷新PT；\n                } else {\n                    ReactAPI.showMessage(\"f\", _data.errorMessage);\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", res.msg);\n            }\n        }\n    });\n}","id":"startTask","operatetype":"CUSTOM","isconfirm":false,"CODE":"makeTaskList_startTask_add_WOM_1.0.0_produceTask_makeTaskList","NAME":"开始","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"isSignatureConfig":true,"funcbody":"function pauseTaskEvent(event) {\n    console.log(''pause'');\n    var selecteds = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getSelecteds();\n    if (selecteds.length == 0) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    var data = selecteds[0];\n    if (data.batchContral) {\n        //只有非批控的工单才可以操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958091725''));\n        return false;\n    }\n    if (data.status != 99) {\n        //请先将指令单生效再进行操作\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958171058''));\n        return false;\n    }\n    var taskRunState = data.taskRunState.id;\n    if (taskRunState != ''WOM_runState/runing'') {\n        //只有执行中的指令单可以暂停\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575959595767''));\n        return false;\n    }\n    var taskId = data.id;\n    $.ajax({\n        url: \"/msService/WOM/produceTask/produceTask/updateTaskState\",\n        type: ''post'',\n        async: false,\n        data: { state: \"hold\", taskId: taskId },\n        success: function (res) {\n            debugger;\n            if (res.code == 200) {