                          ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").refreshDataByRequst({\n                                            type: \"POST\",\n                                            url: _url,\n                                            param: {\n                                                classifyCodes: \",\",\n                                                customCondition: {},\n                                                pageNo: currentPage,\n                                                paging: true,\n                                                pageSize: pageSize\n                                            }\n                                        }); //查询刷新PT；\n                                    } else {\n                                        ReactAPI.showMessage(\"f\", _data.errorMessage);\n                                    }\n                                } else {\n                                    ReactAPI.showMessage(\"f\", res.msg);\n                                }\n                            },\n                            error: function error(XMLHttpRequest, textStatus, errorThrown) {\n                                var errObj = JSON.parse(XMLHttpRequest.responseText);\n                                ReactAPI.showMessage(\"f\", errObj.msg);\n                            }\n                        });\n                    }\n                });\n            }\n        }, {\n            text: \"关闭\",\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"stopTask","operatetype":"CUSTOM","isconfirm":false,"CODE":"makeTaskList_stopTask_add_WOM_1.0.0_produceTask_makeTaskList","NAME":"结束","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"isSignatureConfig":true,"funcbody":"function earlyPutInFunc(event) {\n    // 获取选中行\n    let selectedRows = ReactAPI.g