;\n                            let url = \"/msService/WOM/produceTask/produceTask/makeTaskList-query\";\n                            ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                .APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\")\n                                .refreshDataByRequst({\n                                    type: \"POST\",\n                                    url: url,\n                                    param: {\n                                        classifyCodes: \",\",\n                                        customCondition: {},\n                                        pageNo: currentPage,\n                                        paging: true,\n                                        pageSize: pageSize,\n                                    },\n                                });\n                            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''ec.engine.view.dealsuccess''));\n                        }\n\n                    });\n\n                }\n            }, {\n                operatetype: \"no\",\n                text: ReactAPI.international.getText(''ec.select.no''),\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                }\n            }\n            ]\n        });\n    }\n}","funcname":"onclick=''earlyPutInFunc(event)''","buttonstyle":"recover","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1591581000619_8465","buttonoperationcode":"makeTaskList_earlyPutIn_recover_WOM_1.0.0_produceTask_makeTaskList","isHide":false,"showname":"提前放料","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrTGlzdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_produceTask_ProduceTask","namekey":"WOM.buttonPropertyshowName.randon1591581142666.flag","funcbody_es5":"function earlyPutInFunc(event) {\n    // 获取选中行\n    var s