   ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1575958171058''));\n        return false;\n    }\n    //只有【执行中】的指令单允许请检！\n    if (selectedRow.taskRunState.id != \"WOM_runState/runing\") {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1597996619261''));\n        return false;\n    }\n    //该指令单无需质检\n    if (selectedRow.inspectTimer == null) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1598676953828''));\n        return false;\n    }\n\n    var message = \"\";\n    var taskId = selectedRow.id;\n    //判断该批次的批次信息是否有待检或已检的检验报告\n    $.ajax({\n        url: \"/msService/WOM/produceTask/produceTask/findCheckMsgByBatch\",\n        type: ''get'',\n        async: false,\n        data: { taskId: taskId },\n        success: function (res) {\n            if (res.data.success) {\n                //检验状态\n                if (res.data.checkState != undefined) {\n                    if (res.data.checkState == \"待检\") {\n                        message = ReactAPI.international.getText(''WOM.custom.randon1598424040495'');\n                    } else {\n                        //该指令单检验状态为{} \n                        message = ReactAPI.international.getText(''WOM.custom.randon1597226087560'', res.data.checkState);\n                    }\n\n                }\n                // ,检验结论为{}\n                if (res.data.checkResult != undefined) {\n                    message += ReactAPI.international.getText(''WOM.custom.randon1597227115284'', res.data.checkResult);\n                }\n            }\n        }\n    });\n\n    if (message != '''') {\n        ReactAPI.openConfirm({\n            title: ReactAPI.international.getText(''WOM.custom.randon1597309436125''),\n            message: message,\n            buttons: [{\n                operatetype: \"yes\",\n                text: ReactAPI.international.getText(\"WOM.custom.randon1596434273127\"),// 是\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                    //下推请检单\n                    $.ajax({\n                        url: \"/msService/WOM/produceTask/produceTask/createManuInspect\",\n                        type: ''post'',\n                        async: true,\n                        data: {\n                            \"taskId\": taskId\n                        },\n                        success: function (res) {\n                            if (res.code == 200) {\n                                let data = res.data;\n                                if (data.success) {\n                                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"WOM.custom.randon1597231220469\"));// 处理成功！\n                                    $(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n                                } else {\n                                    ReactAPI.showMessage(\"f\", data.errMsg);\n                                }\n                            } else {\n                                ReactAPI.showMessage(\"f\", res.msg);\n                            }\n                        }\n                    });\n                }\n            }, {\n                operatetype: \"no\",\n                text: ReactAPI.international.getText(\"WOM.custom.randon1596434330969\"),// 否\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                }\n            }\n            ]\n        });\n    } else {\n        ReactAPI.openConfirm({\n            title: ReactAPI.international.getText(''WOM.custom.randon1597309436125''),\n            buttons: [{\n                operatetype: \"yes\",\n                text: ReactAPI.international.getText(\"WOM.custom.randon1596434273127\"),// 是\n                type: \"primary\",\n                onClick: function () {\n                    ReactAPI.closeConfirm();\n                    //下推请检单\n                    $.ajax({\n                        url: \"/msService/WOM/produceTask/produceTask/createManuInspect\",\n                        type: ''post'',\n                        async: true,\n                        data: {\n                            \"taskId\": taskId\n                        },\n                        success: function (res) {\n                            if (res.code == 200) {\n                                let data = res.data;\n                                if (data.success) {\n                                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"WOM.custom.randon1597231220469\"));// 处理成功！\n                                    let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().currentPage;\n                                    let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\").getTablePagination().pageSize;\n                                    let url = \"/msService/WOM/produceTask/produceTask/makeTaskList-query\";\n                                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                        .APIs(\"WOM_1.0.0_produceTask_makeTaskList_produceTask_sdg\")\n                                        .refreshDataByRequst({\n                                            type: \"POST\",\n                                            url: url,\n                                            param: {\n                                                classifyCodes: \",\",\n                                                customCondition: {},\n                                                pageNo: currentPage,\n                                                paging: true,\n                                                pageSize: pageSize,\n                                            },\n                 