:"cell_1596788921479_44","element":{"showTypeHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_prepareMakeTaskList_FASTQUERY_OTHER_WOM_1.0.0_produceTask_ProduceTask_actEndTime","nullable":true,"displayName":"WOM.produceTask.ProduceTask.actEndTime","containLower":false,"showFormatHasChanged":false,"partDepend":"common","defaultValueHasChanged":false,"dbColumnType":"DATETIME","crosscol":false,"ecEnv":"product","propertyCode":"WOM_1.0.0_produceTask_ProduceTask_actEndTime","readonly":false,"layRec":"actEndTime","modelCode":"WOM_1.0.0_produceTask_ProduceTask","namekey":"WOM.produceTask.ProduceTask.actEndTime","showType":"DATETIME","exp":"equal","key":"actEndTime","entityCode":"WOM_1.0.0_produceTask","showFormat":"YMD_HMS","moduleCode":"WOM_1.0.0","iscrosscompany":false,"caseSensitive":false,"mnecode":false,"selfType":"DATETIME","fullPropertyCode":"WOM_1.0.0_produceTask_ProduceTask_actEndTime","columnType":"DATETIME","isrefselect":false,"name":"actEndTime","modelcode":"WOM_1.0.0_produceTask_ProduceTask","multable":false,"maxLength":null,"columnName":"ACT_END_TIME"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"isSuperTable":false,"idPrefix":"ec_WOM_produceTask_produceTask_prepareMakeTaskList","isFirstLoad":false,"type":"layoutDatagrid","ptPageInit":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nlet sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_prepareMakeTaskList_produceTask_sdg'');\n// 下推备料\nsdg.setBtnImg(\"btn-prePareNeed\", \"sup-btn-own-xd\");\n//$(''button[data-id=\"query\"]'').click()","ratio_h":100,"dbcustomtextarea":"function taskDbClick(event, task) {\n    var status = task.status;\n    var batchContral = task.batchContral;\n\tvar taskRunState = task.taskRunState;\n    var formulaProcess;\n    if (task.formulaId != null && task.formulaId.setProcess != null) {\n        formulaProcess = task.formulaId.setProcess.id;\n    }\n    var url;\n    let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n\n    var url = \"/msService/baseService/user/open-pending?tableInfoId=\" + task.tableInfoId + \"&id=\" + task.id + \"&entityCode=WOM_7.5.0.0_produceTask&__pc__=\" + powerCode;\n    //编辑状态双击列表数据正常打开流程单据\n\tif (task.pending != null && status == 88) {\n        url += \"&pendingId=\" + task.pending.id + \"&deploymentId\" + task.pending.deploymentId;\n    }\n\t//生效单据处理\n    if (status == 99) {\n\t\tif(taskRunState != null &&　taskRunState.id == ''WOM_runState/waitForRun''){\n\t\t\t//待执行的单据打开查看视图\n\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskSubmitView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t}else{\t\n\t\t\tif (!batchContral) {\n\t\t\t\tif (formulaProcess == ''RM_formulaType/commonFormula'') {\n\t\t\t\t\t//标准指令单报工\n\t\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t\t} else {\n\t\t\t\t\t//简易指令单报工\n\t\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/easyTaskOperateView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\t//批控指令单查看视图\n\t\t\t\turl = ''/msService/WOM/produceTask/produceTask/makeTaskBatchView?tableInfoId='' + task.tableInfoId + ''&entityCode=WOM_1.0.0_produceTask&id='' + task.id + ''&__pc__='' + powerCode\n\t\t\t}\n\t\t}\t\n    }\n    makeTaskBatchView = window.open(url);\n}","ptPageInit_es5":"// 样式修改不可使用JQuery,需要使用平台提供的方法\nvar sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_prepareMakeTaskList_produceTask_sdg'');\n// 下推备料\nsdg.setBtnImg(\"btn-prePareNeed\", \"sup-btn-own-xd\");\n//$(''button[data-id=\"query\"]'').click()","isdbcustom":true,"modelCode":"WOM_1.0.0_produceTask_ProduceTask","downloadXls":"/msService/WOM/produceTask/produceTask/downloadXls","selectFirstRow":false,"renderOver":"let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_prepareMakeTaskList_produceTask_sdg'');\nlet produceTasks = dataGrid.getDatagridData();\nfor (let produceTask of produceTasks) {\n    if (!produceTask.taskRunState) {\n        continue;\n    }\n    // 显示颜色\n    let color;\n    let runState = produceTask.taskRunState.id;\n    if (produceTask.isAbnormal) {\n        // 异常结束，红色\n        color = ''#ff7875'';\n    } else if (runState === ''WOM_runState/waitForRun'') {\n        // 待执行，灰色\n        color = ''#e8e8e8'';\n    } else if (runState === ''WOM_runState/runing'') {\n        // 执行中，绿色\n        color = ''#95de64'';\n    } else if (runState === ''WOM_runState/paused'') {\n        // 已暂停，黄色\n        color = ''#fff566'';\n    } else if (runState === ''WOM_runState/finished'') {\n        // 正常结束，蓝色\n        color = ''#69c0ff'';\n    } else {\n        color = ''white'';\n    }\n    // 设置背景颜色\n    dataGrid.setDatagridCellAttr(produceTask.rowIndex, \"taskRunState.value\", { style: { background: color } });\n}","buttons":[{"isSignatureConfig":true,"funcbody":"function prePareNeed(event) { \n\t//获取表格对象\n\tvar table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_prepareMakeTaskList_produceTask_sdg\");\n\t//获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (!selectedData.length) {\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.randon1585636817654''));\n        return false;\n    }\n    var ids = \"\";\n    var workAreaNames = new Array()\n\tfor(var i = 0;i<selectedData.length;i++){\n        let workAreaName = selectedData[i].workAreaId.name;\n        if (workAreaNames.length != 0 && workAreaNames.indexOf(workAreaName) == -1) {\n            // 所选指令单不在同一生产区域！\n            ReactAPI.showMessage(\"f\",ReactAPI.international.getText(\"WOM.custom.randon1597053990353\"));\n            return false;\n        }\n        workAreaNames.push(workAreaName)\n        ids += 