-- WOM_1.0.0_produceTask_makeTaskEdit from /Users/zhangchu/Documents/ADP/mes-modules-source-repo/modules/wom/WOM_6.1.3.4/service/src/main/resources/META-INF/bap/module.xml
DO $$
DECLARE runtime_extra_view_json_is_oid boolean;
DECLARE runtime_extra_view_payload text := '{"components":[{"components":[{"fix_h":44,"components":null,"layoutmethod":"container","type":"title"},{"fix_h":44,"components":[],"layoutmethod":"container","type":"button"},{"components":[{"tabViewIndex":0,"isborder":1,"components":[{"components":[{"isborder":0,"components":[{"isborder":0,"cells":[{"colspan":1,"firstTd":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577348327970_308","name":"产品编码","type":"layoutCell","element":{"showTypeHasChanged":true,"couple":true,"onlyLeaf":false,"iscontrol":false,"nullable":false,"isOfficeHandSign":false,"isRevision":false,"showFormatHasChanged":true,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_ProduceTask_productId||BaseSet_1.0.0_material_Material_code","elalign":"right","readonly":false,"convertPdfOnLine":true,"modelCode":"BaseSet_1.0.0_material_Material","complex":false,"isgroup":false,"showType":"LABEL","isCreateNew":false,"officeNotNull":false,"mneenable":false,"isOfficeSign":false,"columnType":"TEXT","isTitle":true,"isrefselect":false,"name":"物料编码","isNoCopy":false,"maxLength":200,"acceptRevisions":false,"code":"WOM_1.0.0_produceTask_makeTaskEdit_EDIT_LABEL_WOM_1.0.0_produceTask_ProduceTask_productId_BaseSet_1.0.0_material_Material_code","displayName":"WOM.propertyshowName.randon1575440267989.flag","multallowview":false,"hideRevision":false,"getRevisions":false,"allowview":false,"showRevision":false,"namekey":"WOM.propertyshowName.randon1575440267989.flag","isreadonly":false,"officePrint":false,"key":"produceTask.productId.code","downloadDoc":true,"entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","showFormat":"TEXT","autoresize":false,"fullPropertyCode":"WOM_1.0.0_produceTask_ProduceTask_productId||BaseSet_1.0.0_material_Material_code","saveTemplate":false,"isCustom":false,"openEmptyDoc":true,"multable":false,"columnName":"CODE"}},{"callbackbody_es5":"function productRefCallback(products) {\n    if (products.length) {\n        // 选中产品后，如有该产品的默认配方，直接带出\n        var product = products[0];\n        // 根据产品id获取该产品默认配方\n        ReactAPI.request({\n            type: \"get\",\n            url: ''/msService/RM/formula/formula/default/product/'' + product.id\n        }, function (res) {\n            // 配方输入框\n            var formualComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.formulaId.formualCode'');\n            if (res.success) {\n                var formula = res.data;\n                // 有默认配方，设置配方输入框的值\n                formualComponent.setValue(formula);\n                /* -------------------------------------------配方有关字段---------------------------------------- */\n                if (formula.setProcess.id == ''RM_formulaType/commonFormula'') {\n                    var inspectTimer = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n                    inspectTimer.setReadonly(true);\n                    inspectTimer.setValue(res.data.inspectTimer.id);\n                    var inspectValue = inspectTimer.getValue().value;\n                    if (inspectValue != '''' && inspectValue != \"RM_inspectTimer/active\") {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(true);\n                        ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(true);\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(false);\n                    } else {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                        ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(true);\n                    }\n                }\n\n                // ''允许提前放料''置为false\n                ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(formula.advanceCharge);\n                // 清空''放料条件''且只读\n                if (formula.advanceCharge) {\n                    var feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                    feedConditionComponent.setReadonly(false);\n                    feedConditionComponent.setValue(formula.feedCondition);\n                }\n                //报工模式 \n                if (formula.reportType != undefined) {\n                    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").setValue(formula.reportType.id);\n                }\n                //质量标准\n                var qualityStdId = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'');\n                if (res.data.qualityStdId) {\n                    qualityStdId.setValue(res.data.qualityStdId);\n                }\n            } else {\n                // 没有默认配方，则清空配方输入框\n                formualComponent.removeValue();\n                /* ---------------------------------------清空与配方相关的字段-------------------------------------- */\n                // ''完工后检验''置为false\n                //ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.insAfterManu'').setValue(false);\n                // ''质量标准''取消必填\n                ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                // ''允许提前放料''置为false\n                ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(false);\n                // 清空''放料条件''且只读\n                var _feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                _feedConditionComponent.setReadonly(true);\n                _feedConditionComponent.setValue('''');\n                // 清空''质量标准''\n                ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'').removeValue();\n            }\n        });\n    }\n    //判断产品编码是否为危化品\n    var data = ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.productId.code\").getValue();\n    var materialCode = void 0;\n    if (data[0] != null && data[0].id != null) {\n        //有数据\n        materialCode = data[0].id;\n        ReactAPI.request({\n            type: \"get\",\n            ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + materialCode,\n            contentType: \"application/json;charset=UTF-8\"\n        }, function (res) {\n            if (res.success) {\n                if (res.data.materialAttr == true) {\n                    //如果是危化品则为红色\n                    document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#B30303\";\n                } else {\n                    document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#505050\";\n                }\n                console.log(res.data.materialAttr);\n                console.log(res.data);\n            } else {\n                console.log(res.msg);\n            }\n        });\n    }\n}","callbackbody":"function productRefCallback(products) {\n    if (products.length) {\n        // 选中产品后，如有该产品的默认配方，直接带出\n        let product = products[0];\n        // 根据产品id获取该产品默认配方\n        ReactAPI.request({\n            type: \"get\",\n            url: ''/msService/RM/formula/formula/default/product/'' + product.id,\n        },\n            res => {\n                // 配方输入框\n                let formualComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.formulaId.formualCode'');\n                if (res.success) {\n                    let formula = res.data;\n                    // 有默认配方，设置配方输入框的值\n                    formualComponent.setValue(formula);\n                    /* -------------------------------------------配方有关字段---------------------------------------- */\n                    if(formula.setProcess.id==''RM_formulaType/commonFormula''){\n                        let inspectTimer=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n                        inspectTimer.setReadonly(true);\n                        inspectTimer.setValue(res.data.inspectTimer.id);\n                        let inspectValue=inspectTimer.getValue().value;                        \n                        if(inspectValue!='''' && inspectValue!=\"RM_inspectTimer/active\"){\n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(true);\n                            ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(true); \n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(false)\n                        }else{\n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                            ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false); \n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(true)\n                        }\n                    }\n\n                    // ''允许提前放料''置为false\n                    ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(formula.advanceCharge);\n                    // 清空''放料条件''且只读\n                    if (formula.advanceCharge) {\n                        let feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                        feedConditionComponent.setReadonly(false);\n                        feedConditionComponent.setValue(formula.feedCondition);\n                    }\n                    //报工模式 \n                    if(formula.reportType!=undefined){\n                        ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").setValue(formula.reportType.id);\n                    }\n                    //质量标准\n                    let qualityStdId = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'');\n                    if (res.data.qualityStdId) {\n                        qualityStdId.setValue(res.data.qualityStdId);\n                    } \n                } else {\n                    // 没有默认配方，则清空配方输入框\n                    formualComponent.removeValue();\n                    /* ---------------------------------------清空与配方相关的字段-------------------------------------- */\n                    // ''完工后检验''置为false\n                    //ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.insAfterManu'').setValue(false);\n                    // ''质量标准''取消必填\n                    ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                    ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                    // ''允许提前放料''置为false\n                    ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(false);\n                    // 清空''放料条件''且只读\n                    let feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                    feedConditionComponent.setReadonly(true);\n                    feedConditionComponent.setValue('''');\n                    // 清空''质量标准''\n                    ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'').removeValue();\n                }\n            });\n    }\n        //判断产品编码是否为危化品\n        let data=ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.productId.code\").getValue();\n        let materialCode;\n        if(data[0]!=null&&data[0].id!=null){//有数据\n            materialCode=data[0].id;\n            ReactAPI.request({\n                type: \"get\",\n                ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n                url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\"+materialCode,\n                contentType: \"application/json;charset=UTF-8\",\n            }, function (res) {\n                if(res.success){\n                    if(res.data.materialAttr==true){//如果是危化品则为红色\n                        document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color=\"#B30303\";\t\n                    }\n                    else{\n                        document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color=\"#505050\";\n                    }\n                  console.log(res.data.materialAttr);\t\n                  console.log(res.data);\n                }else{\t\n                    console.log(res.msg);\n                }\n            }\n            );\n        }\n}","funcbody":"function clearQualityStd(deleteObj) {\n    debugger;\n    // 适用产线清空\n    ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.lineId.name'').removeValue();\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").removeValue();\n    ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.workAreaId.name\").removeValue();\n\n    // 设置是否批控\n    ReactAPI.getComponentAPI(''Checkbox'').APIs(''produceTask.batchContral'').setValue(false);\n    // 工序活动、用料汇总、检验清单页签均隐藏\n    $(\"[role=''tab'']:gt(0)\").hide();\n\n    // ''完工后检验''置为false\n    //ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.insAfterManu'').setValue(false);\n    let inspectTimer=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n    let qualityStd = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'');\n\n    inspectTimer.setReadonly(true);\n    inspectTimer.removeValue();\n    // 清空''质量标准''且只读\n    qualityStd.removeValue();\n    qualityStd.setReadonly(true);\n    qualityStd.setRequired(false);\n    ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n    //配方清空\n    let formualCode=ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.formulaId.formualCode'');\n    formualCode.removeValue();\n    // ''允许提前放料''置为false\n    ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(false);\n    // 清空''放料条件''且只读\n    let feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n    feedConditionComponent.setReadonly(true);\n    feedConditionComponent.setValue('''');\n\n    //计划数量\n    ReactAPI.getComponentAPI(\"InputNumber\").APIs(\"produceTask.planNum\").setValue()\n    //生产批号清空\n    ReactAPI.getComponentAPI(\"Input\").APIs(\"produceTask.produceBatchNum\").setValue('''')\n\n\t// 改变配方编码的点击样式\n    $(''#label_produceTask_formulaId_formualCode'').html(window._supcon_origin_html);\n}@@@@function isDeleteQualityStd(obj) {\n    let currentProducts = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.productId.code'').getValue();\n    if (currentProducts.length && currentProducts[0].id != obj[0].id) {\n        ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'').removeValue();\n    }\n}@@@@function productRefCallback(products) {\n    if (products.length) {\n        // 选中产品后，如有该产品的默认配方，直接带出\n        let product = products[0];\n        // 根据产品id获取该产品默认配方\n        ReactAPI.request({\n            type: \"get\",\n            url: ''/msService/RM/formula/formula/default/product/'' + product.id,\n        },\n            res => {\n                // 配方输入框\n                let formualComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.formulaId.formualCode'');\n                if (res.success) {\n                    let formula = res.data;\n                    // 有默认配方，设置配方输入框的值\n                    formualComponent.setValue(formula);\n                    /* -------------------------------------------配方有关字段---------------------------------------- */\n                    if(formula.setProcess.id==''RM_formulaType/commonFormula''){\n                        let inspectTimer=ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n                        inspectTimer.setReadonly(true);\n                        inspectTimer.setValue(res.data.inspectTimer.id);\n                        let inspectValue=inspectTimer.getValue().value;                        \n                        if(inspectValue!='''' && inspectValue!=\"RM_inspectTimer/active\"){\n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(true);\n                            ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(true); \n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(false)\n                        }else{\n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                            ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false); \n                            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(true)\n                        }\n                    }\n\n                    // ''允许提前放料''置为false\n                    ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(formula.advanceCharge);\n                    // 清空''放料条件''且只读\n                    if (formula.advanceCharge) {\n                        let feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                        feedConditionComponent.setReadonly(false);\n                        feedConditionComponent.setValue(formula.feedCondition);\n                    }\n                    //报工模式 \n                    if(formula.reportType!=undefined){\n                        ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").setValue(formula.reportType.id);\n                    }\n                    //质量标准\n                    let qualityStdId = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'');\n                    if (res.data.qualityStdId) {\n                        qualityStdId.setValue(res.data.qualityStdId);\n                    } \n                } else {\n                    // 没有默认配方，则清空配方输入框\n                    formualComponent.removeValue();\n                    /* ---------------------------------------清空与配方相关的字段-------------------------------------- */\n                    // ''完工后检验''置为false\n                    //ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.insAfterManu'').setValue(false);\n                    // ''质量标准''取消必填\n                    ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                    ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                    // ''允许提前放料''置为false\n                    ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(false);\n                    // 清空''放料条件''且只读\n                    let feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                    feedConditionComponent.setReadonly(true);\n                    feedConditionComponent.setValue('''');\n                    // 清空''质量标准''\n                    ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'').removeValue();\n                }\n            });\n    }\n        //判断产品编码是否为危化品\n        let data=ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.productId.code\").getValue();\n        let materialCode;\n        if(data[0]!=null&&data[0].id!=null){//有数据\n            materialCode=data[0].id;\n            ReactAPI.request({\n                type: \"get\",\n                ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n                url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\"+materialCode,\n                contentType: \"application/json;charset=UTF-8\",\n            }, function (res) {\n                if(res.success){\n                    if(res.data.materialAttr==true){//如果是危化品则为红色\n                        document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color=\"#B30303\";\t\n                    }\n                    else{\n                        document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color=\"#505050\";\n                    }\n                  console.log(res.data.materialAttr);\t\n                  console.log(res.data);\n                }else{\t\n                    console.log(res.msg);\n                }\n            }\n            );\n        }\n}","funcname":"onAfterClear=''clearQualityStd(deleteObj)'' beforecallback=''isDeleteQualityStd(obj)'' callback=''productRefCallback(products)''","cellCode":"cell_1577348327972_9921","type":"layoutCell","colspan":1,"sourcepropertyname":"produceTask.productId","regionType":"EDIT","topAssName":"id","rowspan":1,"funcbody_es5":"function clearQualityStd(deleteObj) {\n    debugger;\n    // 适用产线清空\n    ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.lineId.name'').removeValue();\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").removeValue();\n    ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.workAreaId.name\").removeValue();\n\n    // 设置是否批控\n    ReactAPI.getComponentAPI(''Chec