方，直接带出\n        var product = products[0];\n        // 根据产品id获取该产品默认配方\n        ReactAPI.request({\n            type: \"get\",\n            url: ''/msService/RM/formula/formula/default/product/'' + product.id\n        }, function (res) {\n            // 配方输入框\n            var formualComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.formulaId.formualCode'');\n            if (res.success) {\n                var formula = res.data;\n                // 有默认配方，设置配方输入框的值\n                formualComponent.setValue(formula);\n                /* -------------------------------------------配方有关字段---------------------------------------- */\n                if (formula.setProcess.id == ''RM_formulaType/commonFormula'') {\n                    var inspectTimer = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n                    inspectTimer.setReadonly(true);\n                    inspectTimer.setValue(res.data.inspectTimer.id);\n                    var inspectValue = inspectTimer.getValue().value;\n                    if (inspectValue != '''' && inspectValue != \"RM_inspectTimer/active\") {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(true);\n                        ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(true);\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(false);\n                    } else {\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                        ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(true);\n                    }\n                }\n\n                // ''允许提前放料''置为false\n                ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(formula.advanceCharge);\n                // 清空''放料条件''且只读\n                if (formula.advanceCharge) {\n                    var feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                    feedConditionComponent.setReadonly(false);\n                    feedConditionComponent.setValue(formula.feedCondition);\n                }\n                //报工模式 \n                if (formula.reportType != undefined) {\n                    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").setValue(formula.reportType.id);\n                }\n                //质量标准\n                var qualityStdId = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'');\n                if (res.data.qualityStdId) {\n                    qualityStdId.setValue(res.data.qualityStdId);\n                }\n            } else {\n                // 没有默认配方，则清空配方输入框\n                formualComponent.removeValue();\n                /* ---------------------------------------清空与配方相关的字段-------------------------------------- */\n                // ''完工后检验''置为false\n                //ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.insAfterManu'').setValue(false);\n                // ''质量标准''取消必填\n                ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n                ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n                // ''允许提前放料''置为false\n                ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'').setValue(false);\n                // 清空''放料条件''且只读\n                var _feedConditionComponent = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n                _feedConditionComponent.setReadonly(true);\n                _feedConditionComponent.setValue('''');\n                // 清空''质量标准''\n                ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'').removeValue();\n            }\n        });\n    }\n    //判断产品编码是否为危化品\n    var data = ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.productId.code\").getValue();\n    var materialCode = void 0;\n    if (data[0] != null && data[0].id != null) {\n        //有数据\n        materialCode = data[0].id;\n        ReactAPI.request({\n            type: \"get\",\n            ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + materialCode,\n            contentType: \"application/json;charset=UTF-8\"\n        }, function (res) {\n            if (res.success) {\n                if (res.data.materialAttr == true) {\n                    //如果是危化品则为红色\n                    document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#B30303\";\n                } else {\n                    document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#505050\";\n                }\n                console.log(res.data.materialAttr);\n                console.log(res.data);\n            } else {\n                console.log(res.msg);\n            }\n        });\n    }\n}","callbackname":"productRefCallback(products)","element":{"showTypeHasChanged":true,"couple":true,"onlyLeaf":false,"iscontrol":false,"nullable":false,"isOfficeHandSign":false,"isRevision":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"dbColumnType":"TEXT","referenceview":{"code":"BaseSet_1.0.0_material_materialRefLayout","iscrosscompany":"false","name":"materialRefLayout","title":"BaseSet.viewtitle.randon1569570764419","mneType":"other","url":"/msService/BaseSet/material/material/materialRefLayout","openType":"frame"},"propertyCode":"WOM_1.0.0_produceTask_ProduceTask_productId||BaseSet_1.0.0_mate