alId\": -1 });\n}\nif (data.length != 0 && materialId.length != 0) {//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.success) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}\nlet dataGridAll = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\").getDatagridData();\nfor(let data of dataGridAll){\n    if(data.property.id == \"RM_RMproperty/02\"){\n        ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\").setDatagridCellAttr(data.rowIndex, \"needPrepare\", { readonly: true });\n    }\n\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1575441241774_5658","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1575441036618","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produ