aterialId.length!=0){//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if(res.success){\n          for(let i=0;i<data.length;i++){//遍历\n            if(res.data[i]!=null&&res.data[i]==true){//如果是危化品则为红色\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskSubmitViewdg1577346695192\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\t\n               // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n            }\n            else if(res.data[i]!=null&&res.data[i]==false){\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskSubmitViewdg1577346695192\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n               // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n            }\n          }\n        }else{\t\n            console.log(res.msg);\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1577346694931_46","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1577346695192","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskSubmitViewdg1577346695192_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_materialId_BaseSet_1.0.0_material_Material_code","nullable":true,"isTotal":false,"displayName":"WOM.propertyshowName.randon1575441566757.flag","showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"