:"left","isCustom":false,"modelcode":"HierarchicalMod_1.0.0_factoryModel_FactoryModel","refCondition":"// 工单工序表格\nlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskEditdg1575440388973'');\n// 生产线组件\nlet lineComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.lineId.name'');\n// 所选工单工序\nlet taskProcess = dataGrid.getSelecteds()[0];\n// 配方工序id\nlet processId = taskProcess.formulaProcessId.id;\nlet lineId = lineComponent.getValue().length ? lineComponent.getValue()[0].id : -1;\nreturn \"processId=\" + processId + \"&lineId=\" + lineId;","multable":false,"maxLength":255,"columnName":"NAME"},{"showTypeHasChanged":false,"precisionHasChanged":true,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_procSort","nullable":true,"isTotal":false,"showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_procSort","regionType":"DATAGRID","layRec":"procSort","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.propertyshowName.randon1578288803288.flag","isreadonly":false,"showType":"TEXTFIELD","isgroup":false,"key":"procSort","popView":false,"showFormat":"TEXT","cellCode":"cell_1578288798543_9671","mneenable":false,"label":"报工顺序","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrVmlld19zZWxmfA__","width":100,"textalign":"left","isCustom":false,"multable":false,"maxLength":255,"columnName":"PROC_SORT"},{"showTypeHasChanged":false,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_remark","nullable":true,"isTotal":false,"showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"LONGTEXT","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_remark","regi