ribute\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + materialCode,\n            contentType: \"application/json;charset=UTF-8\",\n        }, function (res) {\n            if (res.success) {\n                if (res.data.materialAttr == true) {//如果是危化品则为红色\n                    document.getElementsByClassName(\"supplant-ellipsis-wrap\")[2].style.color = \"#B30303\";\n                }\n                else {\n                    document.getElementsByClassName(\"supplant-ellipsis-wrap\")[2].style.color = \"#505050\";\n                }\n            }\n        }\n        );\n    }\n}","funcbody":"function productRefCallback(products) {\n    //判断产品编码是否为危化品\n    let data = ReactAPI.getComponentAPI(\"Reference\").APIs(\"produceTask.productId.code\").getValue();\n    let materialCode;\n    if (data[0] != null && data[0].id != null) {//有数据\n        materialCode = data[0].id;\n        ReactAPI.request({\n            type: \"get\",\n            ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + materialCode,\n            contentType: \"application/json;charset=UTF-8\",\n        }, function (res) {\n            if (res.success) {\n                if (res.data.materialAttr == true) {//如果是危化品则为红色\n                    document.getElementsByClassName(\"supplant-ellipsis-wrap\")[2].style.color = \"#B30303\";\n                }\n                else {\n                    document.getElementsByClassName(\"supplant-ellipsis-wrap\")[2].style.color = \"#505050\";\n                }\n            }\n        }\n        );\n    }\n}","funcname":"callback=''productRefCallback(products)''","cellCode":"cell_1586416569829_6","type":"layoutCell","colspan":1,"sourcepropertyname":"produceTask.productId","regionType":"EDIT","topAssName":"id","rowspan":1,"funcbody_es5":"function productRefCallback(products) {\n    //判断产品编码是否为危化品\n    var data = Reac