:false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrQmF0Y2hWaWV3X3NlbGZ8","textalign":"left","width":100,"isCustom":false,"multable":false,"columnName":"REMARK"}],"treePaging":false,"isNoCopy":false,"isCheckBox":false,"cannotAddNewRow":true,"acceptRevisions":false,"targetPropertyCode":"WOM_1.0.0_produceTask_TaskProcess_taskId","code":"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990","idPrefix":"TaskProcess_dg1586416569990","hideRevision":false,"title":"WOM.dataGriddataGridName.randon1575440661677.flag","getRevisions":false,"ptPageInit":"/*\n *  如果是批控制造指令单则隐藏对应的按钮:\n *      工序集合: 开始、结束、设置工作单元和机动执行\n *      \n */\nif (ReactAPI.getFormData().batchContral) {\n    // 工序集合\n    $(\"#btn-startProcess\").hide();\n    $(\"#btn-endProcess\").hide();\n    $(\"#btn-setUnit\").hide();\n    $(\"#btn-otherActive\").hide();\n}\n\n// 样式修改不可使用JQuery,需要使用平台提供的方法\nlet sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\nsdg.setBtnImg(''btn-startProcess'', ''sup-btn-own-qiyong'');\nsdg.setBtnImg(''btn-endProcess'', ''sup-btn-own-ty'');\n\n// 工序列表\nlet processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n// 指令单\nlet task = ReactAPI.getFormData();\n// 指令单执行状态\nlet taskRunState = task.taskRunState.id;\n// 设置点击事件\nprocessDataGrid.setClickEvt((event, process) => {\n    let processRunState = process.processRunState.id;\n    // 开始工序按钮，情况：指令单在执行中，且工序在待执行状态\n    setBtnStyle(''btn-startProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/waitForRun'');\n\n    // 结束工序按钮, 情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-endProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 设置工作单元按钮，情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-setUnit'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 机动执行按钮，情况：指令单在非待执行，且工序在非待执行中\n    setBtnStyle(''btn-otherActive'', taskRunState !== ''WOM_runState/waitForRun'' && processRunState !== ''WOM_runState/waitForRun'');\n\n    let activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027'');\n    // 根据工单工序获取工单活动\n    activeDataGrid.refreshDataByRequst({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskActive/queryByProcess?processId=\" + process.id + \"&showBatch=false\",\n        param: {}\n    })\n});","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''processType.id'',''taskId.id'',''formulaId.id'',''equipmentId.id'',''formulaProcessId.id'',''id.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function startProcessEvent(event) {\n    console.log(\"startProcess\")\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n    let task = ReactAPI.getFormData();\n    // 获取选中行\n    let process = dataGrid.getSelecteds()[0];\n    // 开启工序\n    ReactAPI.request(\n        {\n            type: \"post\",\n            url: \"/msService/WOM/produceTask/taskProcess/start/\" + process.id\n        },\n        res => {\n            if (res.dealSuccessFlag) {\n                // 刷新列表\n                dataGrid.refreshDataByRequst({\n                    type: \"POST\",\n                    url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990&id=\" + task.id,\n                    param: {\n                        pageSize: 65535\n                    }\n                });\n                // 清空工单活动表\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'').deleteLine();\n            } else {\n                ReactAPI.showMessage(\"f\", res.errorMessage);\n            }\n        }\n    );\n}","funcname":"onclick=''startProcessEvent(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1586416570005_1","isHide":false,"showname":"开始","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrQmF0Y2hWaWV3X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"WOM.buttonPropertyshowName.randon1576045686052.flag","funcbody_es5":"function startProcessEvent(event) {\n    console.log(\"startProcess\");\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n    var task = ReactAPI.getFormData();\n    // 获取选中行\n    var process = dataGrid.getSelecteds()[0];\n    // 开启工序\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskProcess/start/\" + process.id\n    }, function (res) {\n        if (res.dealSuccessFlag) {\n            // 刷新列表\n            dataGrid.refreshDataByRequst({\n                type: \"POST\",\n                url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990&id=\" + task.id,\n                param: {\n                    pageSize: 65535\n                }\n            });\n            // 清空工单活动表\n            ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'').deleteLine();\n        } else {\n            ReactAPI.showMessage(\"f\", res.errorMessage);\n        }\n    });\n}","id":"startProcess","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"funcbody":"function endProcessEvent(event) {\n    console.log(\"endProcess\");\n    let dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\n        \"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990\"\n    );\n    let task = ReactAPI.getFormData();\n    // 获取选中行\n    let process = dataGrid.getSelecteds()[0];\n    //ajax判断是否有未完成活动\n\n    ReactAPI.request(\n        {\n            type: \"get\",\n            url:\n                \"/msService/WOM/produceTask/taskProcess/isUnFinishActives/\" + process.id\n        },\n        res => {\n            if (res.dealSuccessFlag) {\n                ReactAPI.openConfirm({\n                    message:\n                        \"工序【\" +\n                        process.name +\n                        \"】中存在未完成的活动，是否确认结束?\",\n                    buttons: [\n                        {\n                            operatetype: \"yes\",\n                            text: \"是\",\n                            type: \"primary\",\n                            onClick: function () {\n                                ReactAPI.closeConfirm();\n                                // 结束工序\n                                ReactAPI.request(\n                                    {\n                                        type: \"post\",\n                                        url:\n                                            \"/msService/WOM/produceTask/taskProcess/end/\" + process.id\n                                    },\n                                    res => {\n                                        if (res.dealSuccessFlag) {\n                                            // 刷新列表\n                                            dataGrid.refreshDataByRequst({\n                                                type: \"POST\",\n                                                url:\n                                                    \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990&id=\" +\n                                                    task.id,\n                                                param: {\n                                                    pageSize: 65535\n                                                }\n                                           