wIndex, \"processRunState.value\", { style: { background: color } });\n    }\n} catch (err) {\n    _didIteratorError = true;\n    _iteratorError = err;\n} finally {\n    try {\n        if (!_iteratorNormalCompletion && _iterator.return) {\n            _iterator.return();\n        }\n    } finally {\n        if (_didIteratorError) {\n            throw _iteratorError;\n        }\n    }\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-3","ratio_h":35,"layoutmethod":"container","ptRealTimeLoad":0,"isreadonly":0,"layno":3,"layoutname":"column-8","islefttopfixed":false,"nums":1},{"isborder":0,"tabViewIndex":0,"components":[{"isborder":0,"components":[{"canInsertRow":false,"isSuperTable":false,"iscontrol":false,"nullable":false,"isTransverseShow":false,"isOfficeHandSign":false,"isRevision":false,"isFirstLoad":false,"type":"layoutDatagrid","isEditable":false,"readonly":0,"ptPageInit_es5":"/**\n *  如果是批控制造指令单则隐藏对应的按钮:\n *      活动集合: 开始、结束\n */\nif (!ReactAPI.getFormData().batchContral) {\n    var activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027'');\n    // 样式修改不可使用JQuery,需要使用平台提供的方法\n    activeDataGrid.setBtnImg(''btn-startActive'', ''sup-btn-own-qiyong'');\n    activeDataGrid.setBtnImg(''btn-endActive'', ''sup-btn-own-ty'');\n\n    var processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n    var task = ReactAPI.getFormData();\n    // 执行状态\n    var taskRunState = task.taskRunState.id;\n    // 设置单击事件\n    activeDataGrid.setClickEvt(function (event, active) {\n        console.log(\"activeclick\");\n\n        // 活动对应工序id\n        var processId = active.taskProcessId.id;\n        var processes = processDataGrid.getDatagridData();\n        // 对应选中工序行\n        var selectedProcess = processes.filter(function (process) {\n            return process.id === processId;\n        })[0];\n        // 工序执行状态\n        var processRunState = selectedProcess.processRunState.id;\n        // 设置选中工序\n        processDataGrid.setSelecteds(selectedProcess.rowIndex + '''');\n\n        // 活动执行状态\n        var activeRunState = active.runState.id;\n\n        // 开始按钮，可用情况：指令单为执行中，且工序为待执行或执行中，且活动为待执行\n        setBtnStyle(''btn-startActive'', taskRunState === ''WOM_runState/runing'' && (processRunState === ''WOM_runState/waitForRun'' || processRunState === ''WOM_runState/runing'') && activeRunState === ''WOM_runState/waitForRun'');\n        // 结束按钮，可用情况：指令单为执行中，且工序为执行中，且活动为执行中\n        setBtnStyle(''btn-endActive'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'' && activeRunState === ''WOM_runState/runing'');\n    });\n\n    // 设置双击事件\n    activeDataGrid.setDbclickEvt(function (event, active) {\n        console.log(\"DbclickEvt\");\n        // 活动执行状态\n        var activeRunState = active.runState.id;\n\n        // 活动对应工序id\n        var processId = active.taskProcessId.id;\n        var processes = processDataGrid.getDatagridData();\n        // 对应选中工序行\n        var selectedProcess = processes.filter(function (process) {\n            return process.id === processId;\n        })[0];\n        // 工序执行状态\n        var processRunState = selectedProcess.processRunState.id;\n\n        // 如果活动是待执行状态，或者(指令单为暂停中或工序为完成)且活动是执行中，无法打开报工界面\n        if (activeRunState === ''WOM_runState/waitForRun'' || (taskRunState === ''WOM_runState/paused'' || processRunState === ''WOM_runState/finished'') && activeRunState === ''WOM_runState/runing'') {\n            return;\n        }\n        var url = void 0;\n        switch (active.activeType.id) {\n            case \"RM_activeType/check\":\n                // 检查\n                url = ''/msService/WOM/procReport/procReport/checkFeedBack'';\n                break;\n            case \"RM_activeType/putin\":\n                // 人工投料\n                url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n                break;\n            case \"RM_activeType/pipePutin\":\n                // 管道投料\n                url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n                break;\n            case \"RM_activeType/output\":\n                // 人工产出\n                url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n                break;\n            case \"RM_activeType/pipeOutput\":\n                // 管道产出\n                url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n                break;\n            case \"RM_activeType/batchPutin\":\n                // 人工投配料\n                url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n                break;\n            case \"RM_activeType/pipeBatchPutin\":\n                // 管道投配料\n                url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n                break;\n            default:\n                return;\n        }\n        // 获取工序报工id\n        ReactAPI.request({\n            type: \"get\",\n            url: \"/msService/WOM/procReport/procReport/by/active/\" + active.id\n        }, function (res) {\n            console.log(\"报工双击事件\");\n            if (res.data.dealSuccessFlag) {\n                var powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n                // 如果是执行中状态，则打开edit视图，否则打开view视图\n                url += activeRunState === ''WOM_runState/runing'' ? ''Edit'' : ''View'';\n                window.open(url + ''?id='' + res.data.procReportId + ''&__pc__='' + powerCode);\n            } else {\n                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n            }\n        });\n    });\n} else {\n    // 活动集合\n    $(\"#btn-startActive\").hide();\n    $(\"#btn-endActive\").hide();\n}","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_produceTask_TaskActive","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"// 设置开始活动，结束活动按钮不可用\nsetBtnStyle(''btn-startActive'', false);\nsetBtnStyle(''btn-endActive'', false);\n// 活动列表\nlet activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027'');\nlet actives = activeDataGrid.getDatagridData();\nlet powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n\n// 如果是检验活动并且不良品处理方式为检验\nfor (let active of actives) {\n    let url = ''/msService/WOM/produceTask/taskProcess/adjustActiveView?id='' + active.taskProcessId.id + ''&activeId='' + active.id + ''&__pc__='' + powerCode;\n    if (active.activeType.id === ''RM_activeType/quality'' && active.activeBatchState && active.activeBatchState.dealType && active.activeBatchState.dealType.id === ''BaseSet_dealType/adjust'') {\n        activeDataGrid.setFormatHtml(active.rowIndex, \"activeBatchState.dealType.value\", \"<a class=''adjust'' target=''_blank'' href=\" + url + \">调整</a>\");\n    }\n    // else if (active.activeType.id === ''RM_activeType/quality'') {\n    //     // todo: 开发显示用\n    //     activeDataGrid.setFormatHtml(active.rowIndex, \"activeBatchState.dealType.value\", \"<a class=''adjust'' target=''_blank'' href=\" + url + \">调整</a>\");\n    // }\n\n    // 设置执行状态颜色\n    if (!active.runState) {\n        continue;\n    }\n    // 显示颜色\n    let color;\n    let runState = active.runState.id;\n    if (runState === ''WOM_runState/waitForRun'') {\n        // 待执行，灰色\n        color = ''#e8e8e8'';\n    } else if (runState === ''WOM_runState/runing'') {\n        // 执行中，绿色\n        color = ''#95de64'';\n    } else if (runState === ''WOM_runState/paused'') {\n        // 已暂停，黄色\n        color = ''#fff566'';\n    } else if (runState === ''WOM_runState/finished'') {\n        // 正常结束，蓝色\n        color = ''#69c0ff'';\n    } else {\n        color = ''white'';\n    }\n    // 设置背景颜色\n    activeDataGrid.setDatagridCellAttr(active.rowIndex, \"runState.value\", { style: { background: color } });\n}\n//判断物料是否为危化品\nlet materialId=[];\nlet id;\nfor(let i=0;i<actives.length;i++){\n    if(actives[i].materialId!=null&&actives[i].materialId.id!=null){\n        materialId.push({ \"materialId\":actives[i].materialId.id });\n    }\n    else\n        materialId.push({ \"materialId\":-1 });\n}  \nif(actives.length!=0&&materialId.length!=0){//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if(res.success){\n          for(let i=0;i<actives.length;i++){//遍历\n            if(res.data[i]!=null&&res.data[i]==true){//如果是危化品则为红色\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\t\n            }\n            else if(res.data[i]!=null&&res.data[i]==false){\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n            }\n          }\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1586416569831_14","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1586416570027","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_taskProcessId_WOM_1.0.0_produceTask_TaskProcess_name","nullable":true,"isTotal":false,"displayName":"WOM.produceTask.TaskProcess.name","showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_TaskActive_taskProcessId||WOM_1.0.0_produceTask_TaskProcess_name","regionType":"DATAGRID","layRec":"WOM_TASK_PROCESSES,ID,WOM_TASK_ACTIVES,TASK_PROCESS_ID-name","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.produceTask.TaskProcess.name","isreadonly":false,"showType":"SELECTCOMP","isgroup":false,"key":"taskProcessId.name","popView":false,"showFormat":"SELECTCOMP","entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","cellCode":"cell_1586416570062_3","mneenable":false,"label":"工序名称","fullPropertyCode":"WOM_1.0.0_produceTask_TaskActive_taskProcessId||WOM_1.0.0_produceTask_TaskProcess_name","isHidden":false,"columnType":"TEXT","hide":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrQmF0Y2hWaWV3X3NlbGZ8","width":100,"textalign":"left","isCustom":false,"modelcode":"WOM_1.0.0_produceTask_TaskProcess","multable":false,"maxLength":255,"columnName":"NAME"},{"showTypeHasChanged":false,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_name","nullable":true,"isTotal":false,"displayName":"WOM.produceTask.TaskActive.name","showFormatHasChanged":false,"defaultValueHasChanged":fal