ion = true;\nvar _didIteratorError = false;\nvar _iteratorError = undefined;\n\ntry {\n    for (var _iterator = actives[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n        var active = _step.value;\n\n        var url = ''/msService/WOM/produceTask/taskProcess/adjustActiveView?id='' + active.taskProcessId.id + ''&activeId='' + active.id + ''&__pc__='' + powerCode;\n        if (active.activeType.id === ''RM_activeType/quality'' && active.activeBatchState && active.activeBatchState.dealType && active.activeBatchState.dealType.id === ''BaseSet_dealType/adjust'') {\n            activeDataGrid.setFormatHtml(active.rowIndex, \"activeBatchState.dealType.value\", \"<a class=''adjust'' target=''_blank'' href=\" + url + \">调整</a>\");\n        }\n        // else if (active.activeType.id === ''RM_activeType/quality'') {\n        //     // todo: 开发显示用\n        //     activeDataGrid.setFormatHtml(active.rowIndex, \"activeBatchState.dealType.value\", \"<a class=''adjust'' target=''_blank'' href=\" + url + \">调整</a>\");\n        // }\n\n        // 设置执行状态颜色\n        if (!active.runState) {\n            continue;\n        }\n        // 显示颜色\n        var color = void 0;\n        var runState = active.runState.id;\n        if (runState === ''WOM_runState/waitForRun'') {\n            // 待执行，灰色\n            color = ''#e8e8e8'';\n        } else if (runState === ''WOM_runState/runing'') {\n            // 执行中，绿色\n            color = ''#95de64'';\n        } else if (runState === ''WOM_runState/paused'') {\n            // 已暂停，黄色\n            color = ''#fff566'';\n        } else if (runState === ''WOM_runState/finished'') {\n            // 正常结束，蓝色\n            color = ''#69c0ff'';\n        } else {\n            color = ''white'';\n        }\n        // 设置背景颜色\n        activeDataGrid.setDatagridCellAttr(active.rowIndex, \"runState.value\", { style: { background: color } });\n    }\n    //判断物料是否为危化品\n} catch (err) {\n    _didIteratorError = true;\n    _iteratorError = err;\n} finally {\n    try {\n        if (!_iteratorNormalCompletion && _iterator.return) {\n            _iterator.return();\n        }\n    } finally {\n        if (_didIteratorError) {\n            throw _iteratorError;\n        }\n    }\n}\n\nvar materialId = [];\nvar id = void 0;\nfor (var i = 0; i < actives.length; i++) {\n    if (actives[i].materialId != null && actives[i].materialId.id != null) {\n        materialId.push({ \"materialId\": actives[i].materialId.id });\n    } else materialId.push({ \"materialId\": -1 });\n}\nif (actives.length != 0 && materialId.length != 0) {\n    //如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId) // 将json数据转化为字符\n    }, function (res) {\n        if (res.success) {\n            for (var _i = 0; _i < actives.length; _i++) {\n                //遍历\n                if (res.data[_i] != null && res.data[_i] == true) {\n                    //如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    });\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:n