== ''WOM_runState/runing'');\n\n    // 机动执行按钮，情况：指令单在非待执行，且工序在非待执行中\n    setBtnStyle(''btn-otherActive'', taskRunState !== ''WOM_runState/waitForRun'' && processRunState !== ''WOM_runState/waitForRun'');\n\n    let activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027'');\n    // 根据工单工序获取工单活动\n    activeDataGrid.refreshDataByRequst({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskActive/queryByProcess?processId=\" + process.id + \"&showBatch=false\",\n        param: {}\n    })\n});","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''processType.id'',''taskId.id'',''formulaId.id'',''equipmentId.id'',''formulaProcessId.id'',''id.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function startProcessEvent(event) {\n    console.log(\"startProcess\")\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n    let task = ReactAPI.getFormData();\n    // 获取选中行\n    let process = dataGrid.getSelecteds()[0];\n    // 开启工序\n    ReactAPI.request(\n        {\n            type: \"post\",\n            url: \"/msService/WOM/produceTask/taskProcess/start/\" + process.id\n        },\n        res => {\n            if (res.dealSuccessFlag) {\n                // 刷新列表\n                dataGrid.refreshDataByRequst({\n                    type: \"POST\",\n                    url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990&id=\" + task.id,\n                    param: {\n                        pageSize: 65535\n                    }\n                });\n                // 清空工单活动表\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'').deleteLine();\n         