false,"isCount":false,"dbColumnType":"LONG","referenceview":{"code":"WOM_1.0.0_produceTask_taskProcessExelogRef","iscrosscompany":"false","name":"taskProcessExelogRef","title":"WOM.viewtitle.randon1576139290244","mneType":"other","url":"/msService/WOM/produceTask/taskProcess/taskProcessExelogRef","openType":"frame"},"minValue":"-9223372036854775808","propertyCode":"WOM_1.0.0_produceTask_TaskActive_taskProcessId||WOM_1.0.0_produceTask_TaskProcess_id","regionType":"DATAGRID","layRec":"WOM_TASK_PROCESSES,ID,WOM_TASK_ACTIVES,TASK_PROCESS_ID-id","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"ec.common.ID","isreadonly":true,"showType":"TEXTFIELD","isgroup":false,"key":"taskProcessId.id","popView":false,"showFormat":"TEXT","entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","maxValue":"9223372036854775807","cellCode":"cell_1586416570067_29","mneenable":false,"label":"ID","fullPropertyCode":"WOM_1.0.0_produceTask_TaskActive_taskProcessId||WOM_1.0.0_produceTask_TaskProcess_id","isHidden":true,"columnType":"LONG","hide":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrQmF0Y2hWaWV3X3NlbGZ8","width":100,"textalign":"center","isCustom":false,"modelcode":"WOM_1.0.0_produceTask_TaskProcess","multable":false,"columnName":"ID"},{"showTypeHasChanged":false,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_remark","nullable":true,"isTotal":false,"displayName":"WOM.produceTask.TaskActive.remark","showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"LONGTEXT","propertyCode":"WOM_1.0.0_produceTask_TaskActive_remark","regionType":"DATAGRID","layRec":"remark","modelCode":"WOM_1.0.0_produceTask_TaskActive","namekey":"WOM.produceTask.TaskActive.remark","isreadonly":false,"showType":"TEXTFIELD","isgroup":false,"key":"remark","popView":false,"showFormat":"TEXT","entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","cellCode":"cell_1586416570067_30","mneenable":false,"label":"备注","fullPropertyCode":"WOM_1.0.0_produceTask_TaskActive_remark","isHidden":false,"columnType":"LONGTEXT","hide":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrQmF0Y2hWaWV3X3NlbGZ8","width":100,"textalign":"left","isCustom":false,"multable":false,"columnName":"REMARK"}],"treePaging":false,"isNoCopy":false,"isCheckBox":false,"cannotAddNewRow":true,"acceptRevisions":false,"targetPropertyCode":"WOM_1.0.0_produceTask_TaskActive_taskId","code":"WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027","idPrefix":"TaskActive_dg1586416570027","hideRevision":false,"title":"WOM.dataGriddataGridName.randon1575440771609.flag","maxTableHeight":0,"getRevisions":false,"ptPageInit":"/**\n *  如果是批控制造指令单则隐藏对应的按钮:\n *      活动集合: 开始、结束\n */\nif (!ReactAPI.getFormData().batchContral) {\n    let activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416570027'');\n\t// 样式修改不可使用JQuery,需要使用平台提供的方法\n\tactiveDataGrid.setBtnImg(''btn-startActive'', ''sup-btn-own-qiyong'');\n\tactiveDataGrid.setBtnImg(''btn-endActive'', ''sup-btn-own-ty'');\n\t\n    let processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskBatchViewdg1586416569990'');\n    let task = ReactAPI.getFormData();\n    // 执行状态\n    let taskRunState = task.taskRunState.id;\n    // 设置单击事件\n    activeDataGrid.setClickEvt(function (event, active) {\n        console.log(\"activeclick\")\n\n        // 活动对应工序id\n        let processId = active.taskProcessId.id;\n        let processes = processDataGrid.getDatagridData();\n        // 对应选中工序行\n        let selectedProcess = processes.filter(process => process.id === processId)[0];\n        // 工序执行状态\n        let processRunState = selectedProcess.processRunState.id;\n        // 设置选中工序\n        processDataGrid.setSelecteds(selectedProcess.rowIndex + '''');\n\n        // 活动执行状态\n        let activeRunState = active.runState.id;\n\n        // 开始按钮，可用情况：指令单为执行中，且工序为待执行或执行中，且活动为待执行\n        setBtnStyle(''btn-startActive'',\n            taskRunState === ''WOM_runState/runing''\n            && (processRunState === ''WOM_runState/waitForRun'' || processRunState === ''WOM_runState/runing'')\n            && (activeRunState === ''WOM_runState/waitForRun''));\n        // 结束按钮，可用情况：指令单为执行中，且工序为执行中，且活动为执行中\n        setBtnStyle(''btn-endActive'',\n            taskRunState === ''WOM_runState/runing''\n            && processRunState === ''WOM_runState/runing''\n            && activeRunState === ''WOM_runState/runing'');\n    });\n\n    // 设置双击事件\n    activeDataGrid.setDbclickEvt((event, active) => {\n        console.log(\"DbclickEvt\")\n        // 活动执行状态\n        let activeRunState = active.runState.id;\n\n        // 活动对应工序id\n        let processId = active.taskProcessId.id;\n        let processes = processDataGrid.getDatagridData();\n        // 对应选中工序行\n        let selectedProcess = processes.filter(process => process.id === processId)[0];\n        // 工序执行状态\n        let processRunState = selectedProcess.processRunState.id;\n\n        // 如果活动是待执行状态，或者(指令单为暂停中或工序为完成)且活动是执行中，无法打开报工界面\n        if (activeRunState === ''WOM_runState/waitForRun'' || ((taskRunState === ''WOM_runState/paused'' || processRunState === ''WOM_runState/finished'') && activeRunState === ''WOM_runState/runing'')) {\n            return;\n        }\n        let url;\n        switch (active.activeType.id) {\n            case \"RM_activeType/check\": // 检查\n                url = ''/msService/WOM/procReport/procReport/checkFeedBack'';\n                break;\n            case \"RM_activeType/putin\": // 人工投料\n                url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n                break;\n            case \"RM_activeType/pipePutin\": // 管道投料\n                url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n                break;\n            case \"RM_activeType/output\": // 人工产出\n                url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n                break;\n            case \"RM_activeType/pipeOutput\": // 管道产出\n                url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n                break;\n            case \"RM_activeType/batchPutin\": // 人工投配料\n                url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n                break;\n            case \"RM_activeType/pipeBatchPutin\": // 管道投配料\n                url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n                break;\n            default:\n                return;\n        }\n        // 获取工序报工id\n        ReactAPI.request(\n            {\n                type: \"get\",\n                url: \"/msService/WOM/procReport/procReport/by/active/\" + active.id\n            },\n            res => {\n                console.log(\"报工双击事件\");\n                if (res.data.dealSuccessFlag) {\n                    let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n                    // 如果是执行中状态，则打开edit视图，否则打开view视图\n                    url += activeRunState === ''WOM_runState/runing'' ? ''Edit'' : ''View'';\n                    window.open(url + ''?id='' + res.data.procReportId + ''&__pc__='' + powerCode);\n                } else {\n                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                }\n            }\n        );\n    });\n} else {\n    // 活动集合\n    $(\"#btn-startActive\").hide();\n    $(\"#btn-endActive\").hide();\n}","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''formulaActiveId.id'',''taskId.id'',''checkStaffId.id'',''checkDepId.id'',''formulaId.id'',''applyCheckStaffId.id'',''taskProcessId.id'',''materialId.id'',''formulaProcessId.id'',''id.id'',''applyCheckDepId.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function startActive(event) {\n    console.log(''