               // 产出\n                    url += isFinish ? ''outputFeedBackView2'' : ''outputFeedBackEdit2'';\n                }\n                url += ''?id='' + procReportId + ''&__pc__='' + powerCode;\n                // 打开url\n                window.open(url);\n                //刷新父页面\n                if (window.opener) {\n                    window.opener.ReactAPI.getComponentAPI(''ListView'').SearchList.submitEditDialogCallback();\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", data.errorMessage);\n            }\n        } else {\n            ReactAPI.showMessage(\"f\", res.message);\n        }\n    });\n});","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_produceTask_TaskActive","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"// 报工按钮不可用\nsetBtnStyle(''btn-report'', false);","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1577337333433_1026","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1577337007020","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_easyTaskOperateViewdg1577337007020_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_materialId_BaseSet_1.0.0_material_Material_code","nullable":true,"isTotal":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"code":"BaseSet_1.0.0_material_materialRefLayout","iscrosscompany":"false","name":"materialRefLayout","title":"BaseSet.viewtitle.randon1569570764419","mneType":"other","url":"/msService/BaseSet/material/material/materialRefLayout","openType":"frame"},"propertyCode":"WOM_1.0.0_produceTask_TaskActive_materialId||BaseSet_1.0.0_material_Material_code","regionType":"DATAGRID","layRec":"BASESET_MAT