\n});\n\n// 设置双击事件\ndataGrid.setDbclickEvt((event, active) => {\n    // 如果指令单是待执行或((指令单为暂停或完成)且活动未结束)，不能进入报工页面\n    if (taskRunState === ''WOM_runState/waitForRun'' || ((taskRunState === ''WOM_runState/paused'' || taskRunState === ''WOM_runState/finished'') && !active.isFinish)) {\n        return;\n    }\n    // 获取工序报工id\n    ReactAPI.request(\n        {\n            type: \"get\",\n            url: \"/msService/WOM/procReport/procReport/by/easyActive/\" + active.id\n        },\n        res => {\n            if (res.code =200) {\n                let data = res.data;\n                if (data.dealSuccessFlag) {\n                    // 工序报工id\n                    let procReportId = data.procReportId;\n                    // 性质\n                    let property = active.property.id;\n                    // 是否完成(为空是未完成)\n                    let isFinish = active.isFinish ? true : false;\n                    let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n                    // 视图的url\n                    let url = ''/msService/WOM/procReport/procReport/'';\n                    if (property === ''RM_RMproperty/01'') {\n                        // 投入\n                        url += isFinish ? ''putInFeedBackView2'' : ''putInFeedBackEdit2'';\n                    } else if (property === ''RM_RMproperty/02'') {\n                        // 产出\n                        url += isFinish ? ''outputFeedBackView2'' : ''outputFeedBackEdit2'';\n                    }\n                    url += ''?id='' + procReportId + ''&__pc__='' + powerCode;\n                    // 打开url\n                    window.open(url);\n                    //刷新父页面\n                    if (window.opener) {\n                        window.opener.ReactAPI.getComponentAPI(''ListView'').SearchList.submitEditDialogCallback()\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", data.errorMessage);\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", res.message);\n            }\n        }\n    );\n})","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''formulaActiveId.id'',''activeBatchState.id'',''taskId.id'',''checkStaffId.id'',''checkDepId.id'',''formulaId.id'',''applyCheckStaffId.id'',''taskProcessId.id'',''materialId.id'',''formulaProcessId.id'',''id.id'',''applyCheckDepId.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function reportEvent(event) {\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_easyTaskOperateViewdg1577337007020'');\n    // 获取选中行\n    let actives = dataGrid.getSelecteds();\n    if (!actives.length) {\n        // 如果没有选中行，提示请选择一条记录进行操作\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    let active = actives[0];\n    if (active.isFinish) {\n        // 判断活动是否已经完成，如果完成则提示：该活动已报工，无须重复报工。\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1577356176633''));\n        return false;\n    }\n\t// 开启遮罩\n\tReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n    // 报工\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/endEasyActive/\" + active.id,\n    },\n        res => {\n\t\t// 关闭遮罩\n\t\tReactAPI.closeLoading();\n        //debugger\n        if (res.code ==200) {\n            let data = res.data;\n            if (data.dealSuccessFlag) {\n                // 处理成功\n                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n                // 刷新列表\n                dataGrid.refreshDataByRequst({\n                    type: \"post\",\n                    url: \"/msService/WOM/produceTask/produceTask/data-dg1577337007020?datagridCode=WOM_1.0.0_produceTask_