ts":[{"isborder":0,"components":[{"canInsertRow":false,"isSuperTable":false,"iscontrol":false,"nullable":false,"isTransverseShow":false,"isOfficeHandSign":false,"isRevision":false,"isFirstLoad":false,"type":"layoutDatagrid","isEditable":false,"readonly":0,"ptPageInit_es5":"// 结束报工\n$(\"#btn-report i\").attr(\"class\", \"sup-btn-icon  sup-btn-own-ty\");\n// 指令单\nvar task = ReactAPI.getFormData();\n// 指令单执行状态\nvar taskRunState = task.taskRunState.id;\nvar dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_easyTaskOperateViewdg1577337007020'');\n\n// 设置单击事件\ndataGrid.setClickEvt(function (event, active) {\n    var isFinish = active.isFinish;\n    // 结束报工按钮可用情况：指令单状态为执行中，且选中活动状态为未完成\n    setBtnStyle(''btn-report'', taskRunState === ''WOM_runState/runing'' && !isFinish);\n});\n\n// 设置双击事件\ndataGrid.setDbclickEvt(function (event, active) {\n    // 如果指令单是待执行或((指令单为暂停或完成)且活动未结束)，不能进入报工页面\n    if (taskRunState === ''WOM_runState/waitForRun'' || (taskRunState === ''WOM_runState/paused'' || taskRunState === ''WOM_runState/finished'') && !active.isFinish) {\n        return;\n    }\n    // 获取工序报工id\n    ReactAPI.request({\n        type: \"get\",\n        url: \"/msService/WOM/procReport/procReport/by/easyActive/\" + active.id\n    }, function (res) {\n        if (res.code = 200) {\n            var data = res.data;\n            if (data.dealSuccessFlag) {\n                // 工序报工id\n                var procReportId = data.procReportId;\n                // 性质\n                var property = active.property.id;\n                // 是否完成(为空是未完成)\n                var isFinish = active.isFinish ? true : false;\n                var powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n                // 视图的url\n                var url = ''/msService/WOM/procReport/procReport/'';\n                if (property === ''RM_RMproperty/01'') {\n                    // 投入\n                    url += isFinish ? ''putInFeedBackView2'' : ''putInFeedBackEdit2'';\n                } else if (property === ''RM_RMproperty/02'') {\n                    // 产出\n                    url += isFinish ? ''outputFeedBackView2'' : ''outputFeedBackEdit2'';\n                }\n                url += ''?id='' + procReportId + ''&__pc__='' + powerCode;\n                // 打开url\n                window.open(url);\n                //刷新父页面\n                if (window.opener) {\n                    window.opener.ReactAPI.getComponentAPI(''ListView'').SearchList.submitEditDialogCallback();\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", data.errorMessage);\n            }\n        } else {\n            ReactAPI.showMessage(\"f\", res.message);\n        }\n    });\n});","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_produceTask_TaskActive","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"// 报工按钮不可用\nsetBtnStyle(''btn-report'', false);","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1577337333433_1026","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1577337007020","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_easyTaskOperateViewdg1577337007020_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_materialId_BaseSet_1.0.0_material_Material_code","nullable":true,"isTotal":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"code":"BaseSet_1.0.0_material_materialRefLayout","iscrosscompany":"false","name":"materialRefLayout","title":"BaseSet.viewtitle.randon1569570764419","mneType":"other","url":"/msService/BaseSet/material/material/materialRefLayout","openType":"frame"},"propertyCode":"WOM_1.0.0_produceTask_TaskActive_materialId||BaseSet_1.0.0_