\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\").setBtnImg(\"btn-complete\", \"sup-btn-own-gb\");\nReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\").setBtnImg(\"btn-adjustment\", \"sup-btn-own-modify\");","isdbcustom":false,"modelCode":"WOM_1.0.0_prepareMaterialNeed_PrePraNeedPart","downloadXls":"/msService/WOM/prepareMaterialNeed/prePraNeedPart/downloadXls","selectFirstRow":false,"renderOver":"let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\").getDatagridData();\nlet materialId = [];\nfor (let i = 0; i < data.length; i++) {\n    if (data[i].materialId != null && data[i].materialId.id != null) {\n        materialId.push({ \"materialId\": data[i].materialId.id });\n    }\n    else\n        materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0 && materialId.length != 0) {\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}","buttons":[{"isSignatureConfig":true,"funcbody":"function createPreOrder(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1585636817654''));\n        return false;\n    }\n    for (var i = 0; i < selectedData.length; i++) {\n        var rowIndex = selectedData[i].rowIndex + 1;\n        if (selectedData[i].partNeedState.id == \"WOM_partNeedState/close\") {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1585288840152'', rowIndex));\n            return false;\n        }\n    }\n    //打开备料指令编辑\n    var url = \"/msService/WOM/prepareMaterialNeed/prePraNeedPart/prepareOrderHeadEdit\";\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(\"WOM.custom.randon1594428493204\"),\n        size: 6,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(\"Button.text.confirm\"),// 确认\n                type: \"primary\",\n                onClick: event => {\n                    //防止重复提交\n                    var isSubmit = false;\n                    if (!isSubmit) {\n                        //获取表格对象\n                        var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_prepareOrderHeadEditdg1591238065146\");\n                        //获取表格数据\n                        var tableData = editTable.getDatagridData();\n                        if (tableData.length == 0) {\n                            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"WOM.custom.randon1585271636861\"));\n                            return false;\n                        }\n                        for (var i = 0; i < tableData.length; i++) {\n                            var rowIndex = tableData[i].rowIndex;\n                            //校验方法\n                            var preNum = Number(tableData[i].prepareNum);// 备料数量\n                            var createStaff = tableData[i].makeStaff;// 创建人\n\n                            if (!preNum || preNum < 0 || !createStaff) {\n                                $(''#makeBatOrdEditDialog'')[0].contentWindow.ReactAPI.submitFormData();\n                                return false;\n                            }\n                        }\n                        var filter = tableData.map(item => { delete item.orderDepartMent.rowHtmlObj; return item; });// IE转换报错问题\n                        //调用创建备料指令\n                        var url = \"/msService/WOM/prepareMaterialNeed/prePraNeedPart/needPartcreatePrePraOrder\";\n                        var data = {\n                            details: JSON.stringify(filter)\n                        }\n                        $.ajax({\n                            type: \"post\",\n                            url: url,\n                            data: data,\n                            async: false,\n                            success: function (res) {\n                                var data = res.data;\n                                if (!data.dealSuccessFlag) {\n                                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                                } else {\n                                    // 关闭窗口\n                                    ReactAPI.destroyDialog(dialogName);\n                                    // 刷新列表\n                                    $(\"button[data-id=''query'']\").click();\n                                    // 处理成功！\n                                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n                                }\n                            },\n                            error: function (res) {\n                                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                            }\n                        });\n                    }\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.close\"),// 关闭 \n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''createPreOrder(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582526535224_3924","buttonoperationcode":"demandBreakdownList_instruction_add_WOM_1.0.0_prepareMaterialNeed_demandBreakdownList","isHide":false,"showname":"创建指令","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3ByZXBhcmVNYXRlcmlhbE5lZWRfZGVtYW5kQnJlYWtkb3duTGlzdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_prepareMaterialNeed_PrePraNeedPart","namekey":"WOM.buttonPropertyshowName.randon1582526569442.flag","funcbody_es5":"function createPreOrder(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1585636817654''));\n        return false;\n    }\n    for (var i = 0; i < selectedData.length; i++) {\n        var rowIndex = selectedData[i].rowIndex + 1;\n        if (selectedData[i].partNeedState.id == \"WOM_partNeedState/close\") {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1585288840152'', rowIndex));\n            return false;\n        }\n    }\n    //打开备料指令编辑\n    var url = \"/msService/WOM/prepareMaterialNeed/prePraNeedPart/prepareOrderHeadEdit\";\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(\"WOM.custom.randon1594428493204\"),\n        size: 6,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(\"Button.text.confirm\"), // 确认\n            type: \"primary\",\n            onClick: function onClick(event) {\n                //防止重复提交\n                var isSubmit = false;\n                if (!isSubmit) {\n                    //获取表格对象\n                    var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_prepareOrderHeadEditdg1591238065146\");\n                    //获取表格数据\n                    var tableData = editTable.getDatagridData();\n                    if (tableData.length == 0) {\n                        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"WOM.custom.randon1585271636861\"));\n                        return false;\n                    }\n                    for (var i = 0; i < tableData.length; i++) {\n                        var rowIndex = tableData[i].rowIndex;\n                        //校验方法\n                        var preNum = Number(tableData[i].prepareNum); // 备料数量\n                        var createStaff = tableData[i].makeStaff; // 创建人\n\n                        if (!preNum || preNum < 0 || !createStaff) {\n                            $(''#makeBatOrdEditDialog'')[0].contentWindow.ReactAPI.submitFormData();\n                            return false;\n                        }\n                    }\n                    var filter = tableData.map(function (item) {\n                        delete item.orderDepartMent.rowHtmlObj;return item;\n                    }); // IE转换报错问题\n                    //调用创建备料指令\n                    var url = \"/msService/WOM/prepareMaterialNeed/prePraNeedPart/needPartcreatePrePraOrder\";\n                    var data = {\n                        details: JSON.stringify(filter)\n                    };\n                    $.ajax({\n                        type: \"post\",\n                        url: url,\n                        data: data,\n                        async: false,\n                        success: function success(res) {\n                            var data = res.data;\n                            if (!data.dealSuccessFlag) {\n                                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                            } else {\n                                // 关闭窗口\n                                ReactAPI.destroyDialog(dialogName);\n                                // 刷新列表\n                                $(\"button[data-id=''query'']\").click();\n                                // 处理成功！\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"EditView.notice.operate.success\"));\n                            }\n                        },\n                        error: function error(res) {\n                            ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                        }\n                    });\n                }\n            }\n        }, {\n            text: ReactAPI.international.getText(\"Button.text.close\"), // 关闭 \n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"instruction","operatetype":"CUSTOM","isconfirm":false,"CODE":"demandBreakdownList_instruction_add_WOM_1.0.0_prepareMaterialNeed_demandBreakdownList","NAME":"创建指令","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"createPreOrder(event)","