DO $$
DECLARE runtime_extra_view_json_is_oid boolean;
DECLARE runtime_extra_view_payload text := '{"dealInfoShow":false,"hasAttachment":false,"components":[{"components":[{"components":[{"components":[{"isborder":0,"tabViewIndex":0,"components":[{"isborder":0,"components":[{"canInsertRow":false,"isSuperTable":false,"iscontrol":false,"nullable":false,"isTransverseShow":false,"isOfficeHandSign":false,"isRevision":false,"isFirstLoad":false,"type":"layoutDatagrid","isEditable":true,"readonly":0,"regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_prepareMaterialNeed_PrePraNeedPart","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"//获取表格对象\nvar table = parent.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_demandBreakdownList_prePraNeedPart_sdg\");\n//获取选择的数据\nvar selectedData = table.getSelecteds();\nfor (var i = 0; i < selectedData.length; i++) {\n    var data = selectedData[i];\n    var newRowData = {\n        materialId: data.materialId,\n        needNum: data.needNum,\n        hasDoneNum: data.hasDoneNum,\n        id: data.id\n    };\n    //获取可编辑表格\n    var editTable = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_needPartAdjustEditdg1592037512706\");\n    //增加一行\n    editTable.addLine();\n    //设置数据\n    editTable.setRowData(i, newRowData);\n}\n//判断物料是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prepareMaterialNeed_needPartAdjustEditdg1592037512706\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    if (data.length != 0 && materialId.length != 0) {\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msServic