Flag){\n                                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                                }else {\n                                    ReactAPI.destroyDialog(dialogName);\n                                     // 刷新列表\n                                    $(\"button[data-id=''query'']\").click();\n                                   ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n                                }\n                            },\n                            error:function(res){\n                                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                            }\n\t\t\t\t\t\t});\t\t\t\t\n\t\t\t\t\t}\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.close\"),// 关闭 \n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''complete(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1591149111394_1816","buttonoperationcode":"preOrderScheduleList_complete_add_WOM_1.0.0_prePraOrder_preOrderScheduleList","isHide":false,"showname":"完成","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3ByZVByYU9yZGVyX3ByZU9yZGVyU2NoZWR1bGVMaXN0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_prePraOrder_PrePraOrder","namekey":"WOM.buttonPropertyshowName.randon1591149120580.flag","funcbody_es5":"function complete(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_preOrderScheduleList_prePraOrder_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        