ion(\"WOM_runState/resuming\");\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"orderState\").getOptionById(\"WOM_runState/waitToBeChecked\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"orderState\").removeOption(\"WOM_runState/waitToBeChecked\");\n}\n//判断物料是否为危化品\nsetTimeout(function () {\n    var data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_preOrderScheduleList_prePraOrder_sdg\").getDatagridData();\n    var materialId = [];\n    for (var i = 0; i < data.length; i++) {\n        if (data[i].productId != null && data[i].productId.id != null) {\n            materialId.push({ \"materialId\": data[i].productId.id });\n        } else materialId.push({ \"materialId\": -1 });\n    }\n    //if(data[i].materialId!=null&&data[i].materialId.id!=null){//如果物料编码字段不为空，则发送请求\n    if (data.length != 0 && materialId.length != 0) {\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n            contentType: \"application/json;charset=UTF-8\",\n            data: JSON.stringify(materialId) // 将json数据转化为字符\n        }, function (res) {\n            if (res.code = 200) {\n                for (var _i = 0; _i < data.length; _i++) {\n                    //遍历\n                    if (res.data[_i] != null && res.data[_i] == true) {\n                        //如果是危化品则为红色\n                        ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_preOrderScheduleList_prePraOrder_sdg\").setDatagridCellAttr(_i, \"productId.code\", { style: { color: \"#B30303\" } });\n                        // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                    } else if (res.data[_i] != null && res.data[_i] == false) {\n                        ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_preOrderScheduleList_prePraOrder_sdg\").setDatagridCellAttr(_i, \"productId.code\", { style: { color: \"#5