\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(''WOM.custom.randon1594429483825''),\n        size: 1,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(\"Button.text.save\"),// 保存\n                type: \"primary\",\n                onClick: event => {\n\t\t\t\t\t//防止重复提交\n\t\t\t\t\tvar isSubmit = false;\n\t\t\t\t\tif(!isSubmit){\n                        // 关闭描述\n                        var\tendReason = \"\";                      \n                        // 备注\n                        var\tremark = event.ReactAPI.getComponentAPI(''Input'').APIs(''prePraOrder.remark'').getValue();\n                        event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").setValidateStyle(''success'');\n                        if(event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").getValue().length == 0){\n\t\t\t\t\t\t\tevent.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").setValidateStyle(''error'', event.ReactAPI.international.getText(\"WOM.custom.randon1592197993210\"));\n\t\t\t\t\t\t\treturn false;\n\t\t\t\t\t\t}else{\n\t\t\t\t\t\t\tendReason = event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").getValue();\n\t\t\t\t\t\t}\n\t\t\t\t\t\tvar url = \"/msService/WOM/prePraOrder/prePraOrder/operate\";\n\t\t\t\t\t\tvar data = {\n                            \"ids\":ids,\n\t\t\t\t\t\t\t\"status\":\"complete\",\n\t\t\t\t\t\t\tendReason:endReason,\n\t\t\t\t\t\t\tremark:remark,\n\t\t\t\t\t\t};\n\t\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''WOM.custom.randon1594429512423''),''1'',true);\n\t\t\t\t\t\t$.ajax({\n\t\t\t\t\t\t\ttype:\"post\",\n\t\t\t\t\t\t\turl:url,\n\t\t\t\t\t\t\tdata:data,\n\t\t\t\t\t\t\tasync:false,\n\t\t\t\t\t\t\tsuccess:function(res){\n                                var data=res.data;\n                                if(!data.dealSuccessFlag){\n                                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                                }else {\n                                    ReactAPI.destroyDialog(dialogName);\n                                     // 刷新列表\n                                    $(\"button[data-id=''query'']\").click();\n                                   ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n                                }\n                            },\n                            error:function(res){\n                                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                            }\n\t\t\t\t\t\t});\t\t\t\t\n\t\t\t\t\t}\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.close\"),// 关闭 \n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''complete(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1591149111394_1816","buttonoperationcode":"preOrderScheduleList_complete_add_WOM_1.0.0_prePraOrder_preOrderScheduleList","isHide":false,"showname":"完成","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3ByZVByYU9yZGVyX3ByZU9yZGVyU2NoZWR1bGVMaXN0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_prePraOrder_PrePraOrder","namekey":"WOM.buttonPropertyshowName.randon1591149120580.flag","funcbody_es5":"function complete(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_preOrderScheduleList_prePraOrder_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return;\n    }\n    //多条数据\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        if (selectedData[i].orderState.id != \"WOM_runState/runing\" && selectedData[i].orderState.id != \"WOM_runState/waitForRun\") {\n            // 第{0}行，备料指令状态不为【待执行】或【执行中】，不允许进行完成操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1592553552685\", selectedData[i].rowIndex + 1));\n            return;\n        } else {\n            ids += selectedData[i].id + \",\";\n        }\n    }\n    //打开指令编辑\n    var url = \"/msService/WOM/prePraOrder/prePraOrder/orderOperateEdit\";\n\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(''WOM.custom.randon1594429483825''),\n        size: 1,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(\"Button.text.save\"), // 保存\n            type: \"primary\",\n            onClick: function onClick(event) {\n                //防止重复提交\n                var isSubmit = false;\n                if (!isSubmit) {\n                    // 关闭描述\n                    var endReason = \"\";\n                    // 备注\n                    var remark = event.ReactAPI.getComponentAPI(''Input'').APIs(''prePraOrder.remark'').getValue();\n                    event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").setValidateStyle(''success'');\n                    if (event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").getValue().length == 0) {\n                        event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prePraOrder.endReason\").setValidateStyle(''error'', event.ReactAPI.international.getText(\"WOM.custom.randon1592197993210\"));\n                        return false;\n                    } else {\n        