//判断物料是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    //if(data[i].materialId!=null&&data[i].materialId.id!=null){//如果物料编码字段不为空，则发送请求\n    if (data.length != 0 && materialId.length != 0) {\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n            contentType: \"application/json;charset=UTF-8\",\n            data: JSON.stringify(materialId)// 将json数据转化为字符\n        }, function (res) {\n            if (res.code = 200) {\n                for (let i = 0; i < data.length; i++) {//遍历\n                    if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                            .APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\")\n                            .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                    }\n                    else if (res.data[i] != null && res.data[i] == false) {\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                            .APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\")\n                            .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                    }\n                }\n            }\n        }\n        );\n    }\n\n}, 10);","buttons":[{"isSignatureConfig":true,"funcbody":"function submit(event) {\n\t//获取表格对象\n\tvar table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\");\n\t//获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1585636817654''));\n        return false;\n    }\n    var ids = \"\";\n\tfor(var i = 0;i<selectedData.length;i++){\n        if(selectedData[i].recordState == null) {\n            ids += selectedData[i].id+\",\";\n        }else if(selectedData[i].recordState != null){// 已收\n            // 第{0}行，备料记录状态不为空，不允许进行提交操作！</br>\n\t\t\tReactAPI.showMessage(\"f\",ReactAPI.international.getText(\"WOM.custom.randon1592556465711\", selectedData[i].rowIndex+1));\n\t\t\treturn false;\n\t\t}\n    }\n\tvar confirmMsg = \"\";\n\tvar url = \"/msService/WOM/prePraOrder/prepMatralReco/sumbitAndRecall\";\n\tif(confirmMsg!=\"\"){\n\t\tReactAPI.openConfirm({\n            // 确认是否提交备料？ \n\t\t\ttitle:ReactAPI.international.getText(''WOM.custom.randon1594429967819''),\n\t\t\tmessage: confirmMsg,\n\t\t\tonOk:function(){\n\t\t\t\tReactAPI.closeConfirm();\n\t\t\t\t//调借口更新需求状态\n\t\t\t\t$.ajax({\n\t\t\t\t\ttype:\"post\",\n\t\t\t\t\turl:url,\n                    data:{\n                        \"ids\":ids,\n                        \"status\":\"submit\"\n                    },\n\t\t\t\t\tbeforeSend:function(){\n\t\t\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));//处理中\n\t\t\t\t\t},\n\t\t\t\t\tsuccess:function(res){\n\t\t\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\t\t\tif(res.code == 200){\n\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n\t\t\t\t\t\t\t//刷新表格\n\t\t\t\t\t\t\t$(\"button[data-id = ''query'']\").click();\n\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\terror:function(res){\n\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message);\n\t\t\t\t\t},\n\t\t\t\t\tcomplete:function(){\n\t\t\t\t\t\tReactAPI.closeLoading();\n\t\t\t\t\t}\n\t\t\t\t});\n\t\t\t}\n\t\t});\n\t}else{\n\t\tReactAPI.ope