etValidateStyle(''error'', event.ReactAPI.international.getText(\"WOM.custom.randon1592357888907\"));\n\t\t\t\t\t\t\treturn false;\n\t\t\t\t\t\t}else{\n\t\t\t\t\t\t\tdeliverCode = event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prepMatralReco.deliverCode\").getValue();\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\tvar url = \"/msService/WOM/prePraOrder/prepMatralReco/prepRecodeDeliver\";\n\t\t\t\t\t\tvar data = {\n                            \"ids\":ids,\n\t\t\t\t\t\t\tdeliverCode:deliverCode,\n\t\t\t\t\t\t\tremark:remark,\n\t\t\t\t\t\t};\n\t\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''WOM.custom.randon1594429512423''),''1'',true);\n\t\t\t\t\t\t$.ajax({\n\t\t\t\t\t\t\ttype:\"post\",\n\t\t\t\t\t\t\turl:url,\n\t\t\t\t\t\t\tdata:data,\n\t\t\t\t\t\t\tasync:false,\n\t\t\t\t\t\t\tsuccess:function(res){\n                                var data=res.data;\n                                if(!data.dealSuccessFlag){\n                                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                                }else {\n                                    ReactAPI.destroyDialog(dialogName);\n                                     // 刷新列表\n                                    $(\"button[data-id=''query'']\").click();\n                                   ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n                                }\n                            },\n                            error:function(res){\n                                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                            }\n\t\t\t\t\t\t});\t\t\t\t\n\t\t\t\t\t}\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.close\"),// 关闭 \n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                    \n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''deliver(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1591238902329_9920","buttonoperationcode":"recordingList_deliver_add_WOM_1.0.0_prePraOrder_recordingList","isHide":false,"showname":"派送","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX3ByZVByYU9yZGVyX3JlY29yZGluZ0xpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_prePraOrder_PrepMatralReco","namekey":"WOM.buttonPropertyshowName.randon1591238904931.flag","funcbody_es5":"function deliver(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return;\n    }\n    //多条数据\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        if (selectedData[i].recordState == null) {\n            // 第{0}行，备料记录状态不为【待送】，不允许进行操作！</br>\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"WOM.custom.randon1592556633058\", selectedData[i].rowIndex + 1));\n            return false;\n        } else if (selectedData[i].recordState.id != \"WOM_prePareState/waitSent\") {\n            // 已收\n            // 第{0}行，备料记录状态不为【待送】，不允许进行操作！</br>\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"WOM.custom.randon1592556633058\", selectedData[i].rowIndex + 1));\n            return false;\n        } else if (selectedData[i].recordState.id == \"WOM_prePareState/waitSent\") {\n            // 待送\n            ids += selectedData[i].id + \",\";\n        }\n    }\n    var url = \"/msService/WOM/prePraOrder/prepMatralReco/recordingDeliverEdit\";\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    ReactAPI.createDialog(dialogName, {\n        // 备料记录派送 \n        title: ReactAPI.international.getText(''WOM.custom.randon1594430304696''),\n        size: 1,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(\"Button.text.save\"), // 保存\n            type: \"primary\",\n            onClick: function onClick(event) {\n                //防止重复提交\n                var isSubmit = false;\n                if (!isSubmit) {\n                    // 派单号\n                    var deliverCode = \"\";\n                    // 备注\n                    var remark = event.ReactAPI.getComponentAPI(''Input'').APIs(''prepMatralReco.remark'').getValue();\n                    //event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prepMatralReco.deliverCode\").setValidateStyle(''success'');\n                    event.ReactAPI.getComponentAPI(\"Label\").APIs(''prepMatralReco.deliverCode'').setNullableStyle(true);\n                    if (event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prepMatralReco.deliverCode\").getValue().length == 0) {\n                        // 派单号不允许为空\n                        event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prepMatralReco.deliverCode\").setValidateStyle(''error'', event.ReactAPI.international.getText(\"WOM.custom.randon1592357888907\"));\n                        return false;\n                    } else {\n                        deliverCode = event.ReactAPI.getComponentAPI(\"Input\").APIs(\"prepMatralReco.deliverCode\").getValue();\n                    }\n\n                    var url = \"/msService/WOM/prePraOrder/prepMatralReco/prepRecodeDeliver\";\n                    var data = {\n                        \"ids\": ids,\n                        deliverCode: deliverCode,\n                        remark: remark\n                    };\n                    event.ReactAPI.openLoading(ReactAPI.international.getText(''WOM.custom.randon1594429512423''), ''1'', true);\n                    $.ajax({\n                        type: \"post\",\n                        url: url,\n                        data: data,\n                        async: false,\n                        success: function success(res) {\n                            var data = res.data;\n                            if (!data.dealSuccessFlag) {\n                                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                            } else {\n                                ReactAPI.destroyDialog(dialogName);\n                                // 刷新列表\n                                $(\"button[data-id=''query'']\").click();\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''EditView.notice.operate.success''));\n                            }\n                        },\n                        error: function error(res) {\n                            ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                        }\n                    });\n                }\n            }\n        }, {\n            text: ReactAPI.international.getText(\"Button.text.close\"), // 关闭 \n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"deliver","operatetype":"CUSTOM","isconfirm":false,"CODE":"recordingList_deliver_add_WOM_1.0.0_prePraOrder_recordingList","NAME":"派送","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"deliver(event)","ONCLICK":"deliver(event)"},{"isSignatureConfig":true,"funcbody":"function secondsyn(event) {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_recordingList_prepMatralReco_sdg\");\n    let selecteds = data.getSelecteds();\n\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(''w'', ReactAPI.international.getText(''WOM.custom.randon1585636817654''));\n        return;\n    }\n    let ids = \"\";\n    for (let i = 0; i < selecteds.length; i++) {\n        //如果有某条记录不需要同步或者已经同步