-- WOM_1.0.0_prePraOrder_instructionEdit from /Users/zhangchu/Documents/ADP/mes-modules-source-repo/modules/wom/WOM_6.1.3.4/service/src/main/resources/META-INF/bap/module.xml
DO $$
DECLARE runtime_extra_view_json_is_oid boolean;
