adonly: true });\n        table.setDatagridCellAttr(i, \"fromStore.code\", { readonly: true });\n    }\n}\n//判断物料是否为危化品\nlet data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_instructionEditdg1591151401772\").getDatagridData();\nlet materialId = [];\nfor (let i = 0; i < data.length; i++) {\n    if (data[i].materialId != null && data[i].materialId.id != null) {\n        materialId.push({ \"materialId\": data[i].materialId.id });\n    }\n    else\n        materialId.push({ \"materialId\": -1 });\n}\nif (data.length != 0 && materialId.length != 0) {\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_instructionEditdg1591151401772\").setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" }, readonly: true });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_instructionEditdg1591151401772\").setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" }, readonly: true });\n                }\n            }\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1591151416053_3412","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1591151401772","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM