alueByKey(rowIndex,\"receiveNum\",preNum)\n        // 是否只读\n\t\tdata.setDatagridCellAttr(rowIndex,\"receiveNum\", { readonly: true });\n        data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n        data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: false });\n        data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n\n\t}else if(dataSelected.receiveState.id ==  \"WOM_receiveState/partReceive\"){\n\t\t//部分接收\n\t\tdata.setCellValueByKey(rowIndex,\"rejectReason\",null)\n        data.setCellValueByKey(rowIndex,\"receiveNum\",null)\n        data.setCellValueByKey(rowIndex,\"rejectReason\",null)\n\n\t\tdata.setDatagridCellAttr(rowIndex,\"receiveNum\", { readonly: false });\n        data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n        data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: false });\n\n\t} else {\n        // 是否只读\n        data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n        data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: true });\n\t\tdata.setDatagridCellAttr(rowIndex,\"receiveNum\", { readonly: true });\n\n        // 清空\n        data.setValueByKey(rowIndex, ''rejectReason.value'', null);\n        // data.setValueByKey(rowIndex, \"toStoreId.code\", null);\n        // data.setValueByKey(rowIndex, \"toStoreId.name\", null);\n\t\tdata.setValueByKey(rowIndex,\"receiveNum\", null);\n    }\n}","showFormat":"SELECTCOMP","entityCode":"WOM_1.0.0_prePraOrder","moduleCode":"WOM_1.0.0","cellCode":"cell_1591346069489_1082","mneenable":false,"label":"接收/拒收","fullPropertyCode":"WOM_1.0.0_prePraOrder_PrepMatralReco_receiveState","fill":{"fillType":3,"fillName":"系统编码","fillContent":"WOM_receiveState","listType":"list"},"isHidden":false,"columnType":"SYSTEMCODE","hide":false,"pc":"__pc__=V09NXzEuMC4wX3ByZVByYU9yZGVyX3JlY29yZGluZ1JlY2VpdmVFZGl0X3NlbGZ8","width":100,"textalign":"center","isCustom":false,"funcbody_es5":"function receiveStateClick() {\n      var data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_prePraOrder_recordingReceiveEditdg1591239791392\");\n      var dataSelected = data.getSelecteds()[0];\n      var rowIndex = dataSelected.rowIndex; //获取单元格序号\n      var rejectReason = dataSelected.rejectReason; //拒签原因\n      var preNum = dataSelected.preNum; //备料数量\n\n      //拒收\n      if (dataSelected.receiveState.id == \"WOM_receiveState/reject\") {\n            data.setCellValueByKey(rowIndex, \"receiveNum\", null);\n            data.setDatagridCellAttr(rowIndex, \"receiveNum\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: false });\n            data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: true });\n\n            //接收\n      } else if (dataSelected.receiveState.id == \"WOM_receiveState/receive\") {\n            data.setCellValueByKey(rowIndex, \"rejectReason\", null);\n            data.setCellValueByKey(rowIndex, \"receiveNum\", preNum);\n            // 是否只读\n            data.setDatagridCellAttr(rowIndex, \"receiveNum\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: false });\n            data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n      } else if (dataSelected.receiveState.id == \"WOM_receiveState/partReceive\") {\n            //部分接收\n            data.setCellValueByKey(rowIndex, \"rejectReason\", null);\n            data.setCellValueByKey(rowIndex, \"receiveNum\", null);\n            data.setCellValueByKey(rowIndex, \"rejectReason\", null);\n\n            data.setDatagridCellAttr(rowIndex, \"receiveNum\", { readonly: false });\n            data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: false });\n      } else {\n            // 是否只读\n            data.setDatagridCellAttr(rowIndex, \"rejectReason.value\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"toStoreId.code\", { readonly: true });\n            data.setDatagridCellAttr(rowIndex, \"receiveNum\", { readonly: true });\n\n            // 清空\n            data.setValueByKey(rowIndex, ''rejectReason.value'', null);\n            // data.setValueByKey(rowIndex, \"toStoreId.code\", null);\n            // data.setValueByKey(rowIndex, \"toStoreId.name\", null);\n            data.setValueByKey(rowIndex, \"receiveNum\", null);\n      }\n}","multable":false,"maxLength":4000,"columnName":"RECEIVE_STATE"},{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_prePraOrder_recordingReceiveEditdg1591239791392_DATAGRID_OTHER_WOM_1.0.0_prePraOrder_PrepMatralReco_toWareId_BaseSet_1.0.0_warehouse_Warehouse_code","nullable":true,"isTotal":false,"displayName":"WOM.propertyshowName.randon1598333851042.flag","showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"code":"BaseSet_1.0.0_warehouse_warehouseRefLayout","iscrosscompany":"false","name":"warehouseRefLayout","title":"BaseSet.viewtitle.randon1569487225237","mneType":"other","url":"/msService/BaseSet/warehouse/warehouse/warehouseRefLayout","openType":"frame"},"propertyCode":"WOM_1.0.0_prePraOrder_PrepMatralReco_toWareId||BaseSet_1.0.0_warehouse_Warehouse_code","regionType":"DATAGRID","layRec":"BASESET_WAREHOUSES,ID,WOM_PREP_MATRAL_RECOS,TO_WARE_ID-code","modelCode":"BaseSet_1.0.0_warehouse_Warehouse","namekey":"WOM.propertyshowName.randon1598333851042.flag","isreadonly":true,"showType":"SELECTCOMP","isgroup":false,"key":"toWareId.code","popView":false,"showFormat":"SELECTCOMP","entityCode":"WOM_1.0.0_prePraOrder","moduleCode":"WOM_1.0.0","cellCode":"cell_1591239863119_9953","mneenable":false,"label":"目的仓库编码","fullPropertyCo