w\", ReactAPI.international.getText(\"WOM.custom.randon1585284032149\", selectedData[i].rowIndex + 1));\n\t\t\treturn;\n\t\t} else {\n\t\t\tneedIds += selectedData[i].id + \",\";\n\t\t}\n\t}\n\t/*\n  * 若设置了区间上下限，判断已配数量是否大于等于区间下限，若小于，弹出提示框确认是否完成。\n  * 若没有设置区间上下限，判断已配数量是否大于等于需配数量，若小于，弹出提示框确认是否完成。\n  */\n\tvar confirmMsg = \"\";\n\tfor (var i = 0; i < selectedData.length; i++) {\n\t\tvar dataItem = selectedData[i];\n\t\tvar rowIndex = dataItem.rowIndex + 1;\n\t\tvar maxQuantity = dataItem.maxQuantity;\n\t\tvar minQuantity = dataItem.minQuantity;\n\t\tvar planNum = dataItem.planNum;\n\t\tvar offerNum = dataItem.offerNum;\n\t\tif (dataItem.needState.id == \"WOM_batMatState/noBatch\") {\n\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289496950\", rowIndex);\n\t\t} else if (dataItem.needState.id == \"WOM_batMatState/batching\") {\n\t\t\t//若设置了区间下限\n\t\t\tif (minQuantity != null && minQuantity !== \"\") {\n\t\t\t\tif (offerNum == null || offerNum === \"\") {\n\t\t\t\t\tofferNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum < minQuantity) {\n\t\t\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289757908\", rowIndex);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (planNum == null || planNum === \"\") {\n\t\t\t\t\tplanNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum == null || offerNum === \"\") {\n\t\t\t\t\tofferNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum < planNum) {\n\t\t\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289822557\", rowIndex);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tif (confirmMsg != \"\") {\n\t\tReactAPI.openConfirm({\n\t\t\t//title:\"是否确认完成？\",\n\t\t\tmessage: confirmMsg,\n\t\t\tonOk: function onOk() {\n\t\t\t\tReactAPI.closeConfirm();\n\t\t\t\t//调接口更新需求状态\n\t\t\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\t\t\tvar data = { \"needIds\": needIds };\n\t\t\t\t$.ajax({\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\turl: url,\n\t\t\t\t\tdata: data,\n\t\t\t\t\tbeforeSend: function beforeSend() {\n\t\t\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t\t\t},\n\t\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\t\t\tif (res.code == 200) {\n\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t\t\t//刷新表格\n\t\t\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\terror: function error(res) {\n\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message + \"！\");\n\t\t\t\t\t},\n\t\t\t\t\tcomplete: function complete() {\n\t\t\t\t\t\tReactAPI.closeLoading();\n\t\t\t\t\t}\n\n\t\t\t\t});\n\t\t\t}\n\t\t});\n\t} else {\n\t\t//调接口更新配料需求状态\n\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\tvar data = { \"needIds\": needIds };\n\t\t$.ajax({\n\t\t\ttype: \"post\",\n\t\t\turl: url,\n\t\t\tdata: data,\n\t\t\tbeforeSend: function beforeSend() {\n\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t},\n\t\t\tsuccess: function success(res) {\n\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\tif (res.code == 200) {\n\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t//刷新表格\n\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t}\n\t\t\t},\n\t\t\terror: function error(res) {\n\t\t\t\tReactAPI.showMessage(\"f\", res.message + \"！\");\n\t\t\t},\n\t\t\tcomplete: function complete() {\n\t\t\t\tReactAPI.closeLoading();\n\t\t\t}\n\t\t});\n\t}\n}","id":"complete","operatetype":"CUSTOM","isconfirm":false,"CODE":"batchMaterialNeed_complete_add_WOM_1.0.0_batchMaterialNeed_batchMaterialNeed","NAME":"完成","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"complete(event)","ONCLICK":"complete(event)"}],"importMainXls":"/msService/WOM/batchMaterialNeed/batchMatNeed/importMainXls","mainDisplayName":"id","isTransCondition":false,"renderOver_es5":"if (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/delivered\"