upDataGrid'').APIs(''WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg'');\nsdg.setBtnImg(''btn-complete'', ''sup-btn-own-plwc'');","isdbcustom":false,"modelCode":"WOM_1.0.0_batchMaterialNeed_BatchMatNeed","downloadXls":"/msService/WOM/batchMaterialNeed/batchMatNeed/downloadXls","selectFirstRow":false,"renderOver":"if (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/delivered\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/delivered\")\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/finish\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/finish\")\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/puted\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/puted\")\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/reject\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/reject\")\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/waitAllocat\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/waitAllocat\")\n\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").getOptionById(\"WOM_batMatState/waitPut\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"needState\").removeOption(\"WOM_batMatState/waitPut\")\n}\n//判断物料编码的物料是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","buttons":[{"isSignatureConfig":true,"funcbody":"function add(event) {\n    //获取表格对象\n    var table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    // 拒料测试记录等不完整数据不能转成正常生产配料指令。\n    for (var invalidIndex = 0; invalidIndex < selectedData.length; invalidIndex++) {\n        var invalidRow = selectedData[invalidIndex];\n        if (!invalidRow.needState || !invalidRow.needState.id ||\n            !invalidRow.batchSite || !invalidRow.batchSite.id ||\n            !invalidRow.materialId || !invalidRow.materialId.id) {\n            ReactAPI.showMessage(\"w\", \"当前记录不是有效的生产配料需求，请从制造指令生成配料需求\");\n            return false;\n        }\n    }\n    //选了多条数据，有\n    for(var i = 0;i<selectedData.length;i++){\n        if((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/done\"){\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585277863700\", selectedData[i].rowIndex+1));\n            return;\n        }else if((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/stop\"){\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585283991307\", selectedData[i].rowIndex+1));\n            return;\n        }else if((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/cancel\"){\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585284032149\", selectedData[i].rowIndex+1));\n            return;\n        }\n    }\n    //打开配料指令编辑\n    var url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/makeBatOrdEdit\";\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: \"创建配料指令\",// 创建配料指令单,\n        size: 6,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [\n            {\n                text: \"确认\",// 确认\n                type: \"primary\",\n                onClick: event => {\n                    //防止重复提交\n                    var isSubmit = false;\n                    if(!isSubmit){\n                        //获取表格对象\n                        var editTable= event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_makeBatOrdEditdg1582856369922\");\n                        //获取表格数据\n                        var tableData = editTable.getDatagridData();\n                        for(var i=0;i<tableData.length;i++){\n                            var minQuantity= tableData[i].minQuantity;\n                            var maxQuantity = tableData[i].maxQuantity;\n                            var batchNum = tableData[i].batchNum;\n                            var batchType = tableData[i].batchType;\n                            var makeStaff=tableData[i].makeStaff;\n                            editTable.setDatagridCellAttr(i, \"batchNum\", { style: { background: \"white\" } });\n                            event.$(''.batchTypeSelect:eq( '' +i+ '')'').css({ background: ''white'' });\n                            if(batchNum<minQuantity  || minQuantity<0 || (batchNum > maxQuantity && maxQuantity!= \"\" && maxQuantity!= undefined) || !batchNum || !batchType || !batchType.id || !makeStaff){\n                                $(''#makeBatOrdEditDialog'')[0].contentWindow.ReactAPI.submitFormData();\n                                return false;\n                            }\n                        }\n                        var filter=tableData.map(item=>{delete item.orderDepartMent.rowHtmlObj;return item;});// IE转换报错问题\n                        //调借口更新需求状态\n                        var url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/createTask\";\n                        var data = {\n                            details:JSON.stringify(filter)\n                        };\n                        $.ajax({\n                            type:\"post\",\n                            url:url,\n                            data:data,\n                            async:false,\n                            success:function(res){\n                                var data=res.data;\n                                if(!data.dealSuccessFlag){\n                                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                                }else {\n                                    // 关闭窗口\n                                    ReactAPI.destroyDialog(dialogName);\n                                    // 刷新列表\n                                    $(\"button[data-id=''query'']\").click();\n                                    // 处理成功！\n                                    ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"WOM.custom.randon1585287777177\"));                    \n                                }\n                            },\n                            error:function(res){ \n                                ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                            }   \n                        });\n                    }\n                }\n            },\n            {\n                text:  \"关闭\",// 关闭 \n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''add(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582010636957_7653","buttonoperationcode":"batchMaterialNeed_addBatchMaterial_add_WOM_1.0.0_batchMaterialNeed_batchMaterialNeed","isHide":false,"showname":"创建配料指令","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxOZWVkX2JhdGNoTWF0ZXJpYWxOZWVkX3NlbGZ8","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterialNeed_BatchMatNeed","namekey":"WOM.buttonPropertyshowName.randon1582010692636.flag","funcbody_es5":"function add(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    // 拒料测试记录等不完整数据不能转成正常生产配料指令。\n    for (var invalidIndex = 0; invalidIndex < selectedData.length; invalidIndex++) {\n        var invalidRow = selectedData[invalidIndex];\n        if (!invalidRow.needState || !invalidRow.needState.id ||\n            !invalidRow.batchSite || !invalidRow.batchSite.id ||\n            !invalidRow.materialId || !invalidRow.materialId.id) {\n            ReactAPI.showMessage(\"w\", \"当前记录不是有效的生产配料需求，请从制造指令生成配料需求\");\n            return false;\n        }\n    }\n    //选了多条数据，有\n    for (var i = 0; i < selectedData.length; i++) {\n        if ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/done\") {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585277863700\", selectedData[i].rowIndex + 1));\n            return;\n        } else if ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/stop\") {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585283991307\", selectedData[i].rowIndex + 1));\n            return;\n        } else if ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/cancel\") {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585284032149\", selectedData[i].rowIndex + 1));\n            return;\n        }\n    }\n    //打开配料指令编辑\n    var url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/makeBatOrdEdit\";\n    // 对话框名称\n    var dialogName = ''makeBatOrdEditDialog'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: \"创建配料指令\", // 创建配料指令单,\n        size: 6,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [{\n            text: \"确认\", // 确认\n            type: \"primary\",\n            onClick: function onClick(event) {\n                //防止重复提交\n                var isSubmit = false;\n                if (!isSubmit) {\n                    //获取表格对象\n                    var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_makeBatOrdEditdg1582856369922\");\n                    //获取表格数据\n                    var tableData = editTable.getDatagridData();\n                    for (var i = 0; i < tableData.length; i++) {\n                        var minQuantity = tableData[i].minQuantity;\n                        var maxQuantity = tableData[i].maxQuantity;\n                        var batchNum = tableData[i].batchNum;\n                        var batchType = tableData[i].batchType;\n                        var makeStaff = tableData[i].makeStaff;\n                        editTable.setDatagridCellAttr(i, \"batchNum\", { style: { background: \"white\" } });\n                        event.$(''.batchTypeSelect:eq( '' + i + '')'').css({ background: ''white'' });\n                        if (batchNum < minQuantity || minQuantity < 0 || batchNum > maxQuantity && maxQuantity != \"\" && maxQuantity != undefined || !batchNum || !batchType || !batchType.id || !makeStaff) {\n                            $(''#makeBatOrdEditDialog'')[0].contentWindow.ReactAPI.submitFormData();\n                            return false;\n                        }\n                    }\n                    var filter = tableData.map(function (item) {\n                        delete item.orderDepartMent.rowHtmlObj;return item;\n                    }); // IE转换报错问题\n                    //调借口更新需求状态\n                    var url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/createTask\";\n                    var data = {\n                        details: JSON.stringify(filter)\n                    };\n                    $.ajax({\n                        type: \"post\",\n                        url: url,\n                        data: data,\n                        async: false,\n                        success: function success(res) {\n                            var data = res.data;\n                            if (!data.dealSuccessFlag) {\n                                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                            } else {\n                                // 关闭窗口\n                                ReactAPI.destroyDialog(dialogName);\n                                // 刷新列表\n                                $(\"button[data-id=''query'']\").click();\n                                // 处理成功！\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"WOM.custom.randon1585287777177\"));\n                            }\n                        },\n                        error: function error(res) {\n                            ReactAPI.showMessage(\"f\", res.responseJSON.message);\n                        }\n                    });\n                }\n            }\n        }, {\n            text: \"关闭\", // 关闭 \n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }]\n    });\n}","id":"addBatchMaterial","operatetype":"CUSTOM","isconfirm":false,"CODE":"batchMaterialNeed_addBatchMaterial_add_WOM_1.0.0_batchMaterialNeed_batchMaterialNeed","NAME":"创建配料指令","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"add(event)","ONCLICK":"add(event)"},{"isSignatureConfig":true,"funcbody":"function complete(event) {\n\t//获取表格对象\n\tvar table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\");\n\t//获取选择的数据\n\tvar selectedData = table.getSelecteds();\n\tif (selectedData.length == 0) {\n\t\t//提示未选择数据\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n\t\treturn false;\n\t}\n\tfor (var invalidIndex = 0; invalidIndex < selectedData.length; invalidIndex++) {\n        if (!selectedData[invalidIndex].needState || !selectedData[invalidIndex].needState.id) {\n            ReactAPI.showMessage(\"w\", \"当前记录缺少配料需求状态，不能完成\");\n            return false;\n        }\n    }\n    //如果全部已更新无需再操作\n\tvar needIds = \"\";\n\tfor(var i = 0;i<selectedData.length;i++){\n\t\tif((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/done\"){\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585277863700\", selectedData[i].rowIndex+1));\n\t\t\treturn;\n\t\t}else if((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/stop\"){\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585283991307\", selectedData[i].rowIndex+1));\n\t\t\treturn;\n\t\t}else if((selectedData[i].needState && selectedData[i].needState.id)==\"WOM_batMatState/cancel\"){\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585284032149\", selectedData[i].rowIndex+1));\n\t\t\treturn;\n\t\t}else{\n\t\t\tneedIds+=selectedData[i].id+\",\";\n\t\t}\n\t}\n\t/*\n\t * 若设置了区间上下限，判断已配数量是否大于等于区间下限，若小于，弹出提示框确认是否完成。\n\t * 若没有设置区间上下限，判断已配数量是否大于等于需配数量，若小于，弹出提示框确认是否完成。\n\t */\n\t var confirmMsg = \"\";\n\t for(var i = 0;i<selectedData.length;i++){\n\t\tvar dataItem = selectedData[i];\n\t\tvar rowIndex = dataItem.rowIndex+1;\n\t\tvar maxQuantity = dataItem.maxQuantity;\n\t\tvar minQuantity = dataItem.minQuantity;\n\t\tvar planNum = dataItem.planNum;\n\t\tvar offerNum = dataItem.offerNum;\n\t\tif(dataItem.needState.id==\"WOM_batMatState/noBatch\"){\n\t\t\tconfirmMsg+=ReactAPI.international.getText(\"WOM.custom.randon1585289496950\", rowIndex);\n\t\t}else if(dataItem.needState.id==\"WOM_batMatState/batching\"){\n\t\t\t//若设置了区间下限\n\t\t\tif(minQuantity!=null && minQuantity!==\"\"){\n\t\t\t\tif(offerNum==null||offerNum===\"\"){\n\t\t\t\t\tofferNum=0;\n\t\t\t\t}\n\t\t\t\tif(offerNum<minQuantity){\n\t\t\t\t\tconfirmMsg+=ReactAPI.international.getText(\"WOM.custom.randon1585289757908\", rowIndex);\n\t\t\t\t}\n\t\t\t}else{\n\t\t\t\tif(planNum==null||planNum===\"\"){\n\t\t\t\t\tplanNum=0;\n\t\t\t\t}\n\t\t\t\tif(offerNum==null||offerNum===\"\"){\n\t\t\t\t\tofferNum=0;\n\t\t\t\t}\n\t\t\t\tif(offerNum<planNum){\n\t\t\t\t\tconfirmMsg+=ReactAPI.international.getText(\"WOM.custom.randon1585289822557\", rowIndex);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tif(confirmMsg!=\"\"){\n\t\tReactAPI.openConfirm({\n\t\t\t//title:\"是否确认完成？\",\n\t\t\tmessage: confirmMsg,\n\t\t\tonOk:function(){\n\t\t\t\tReactAPI.closeConfirm();\n\t\t\t\t//调接口更新需求状态\n\t\t\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\t\t\tvar data={\"needIds\":needIds};\n\t\t\t\t$.ajax({\n\t\t\t\t\ttype:\"post\",\n\t\t\t\t\turl:url,\n\t\t\t\t\tdata:data,\n\t\t\t\t\tbeforeSend:function(){\n\t\t\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t\t\t},\n\t\t\t\t\tsuccess:function(res){\n\t\t\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\t\t\tif(res.code == 200){\n\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t\t\t//刷新表格\n\t\t\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\terror:function(res){\n\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message+\"！\");\n\t\t\t\t\t},\n\t\t\t\t\tcomplete:function(){\n\t\t\t\t\t\tReactAPI.closeLoading();\n\t\t\t\t\t}\n\t\t\t\t\t\n\t\t\t\t});\n\t\t\t}\n\t\t});\n\t}else{\n\t\t//调接口更新配料需求状态\n\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\tvar data={\"needIds\":needIds};\n\t\t$.ajax({\n\t\t\ttype:\"post\",\n\t\t\turl:url,\n\t\t\tdata:data,\n\t\t\tbeforeSend:function(){\n\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t},\n\t\t\tsuccess:function(res){\n\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\tif(res.code == 200){\n\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t//刷新表格\n\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t}\n\t\t\t},\n\t\t\terror:function(res){\n\t\t\t\tReactAPI.showMessage(\"f\", res.message+\"！\");\n\t\t\t},\n\t\t\tcomplete:function(){\n\t\t\t\tReactAPI.closeLoading();\n\t\t\t} \n\t\t});\n\t}\n}","funcname":"onclick=''complete(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582010749623_662","buttonoperationcode":"batchMaterialNeed_complete_add_WOM_1.0.0_batchMaterialNeed_batchMaterialNeed","isHide":false,"showname":"完成","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxOZWVkX2JhdGNoTWF0ZXJpYWxOZWVkX3NlbGZ8","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterialNeed_BatchMatNeed","namekey":"WOM.buttonPropertyshowName.randon1582010802590.flag","funcbody_es5":"function complete(event) {\n\t//获取表格对象\n\tvar table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\");\n\t//获取选择的数据\n\tvar selectedData = table.getSelecteds();\n\tif (selectedData.length == 0) {\n\t\t//提示未选择数据\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n\t\treturn false;\n\t}\n\tfor (var invalidIndex = 0; invalidIndex < selectedData.length; invalidIndex++) {\n        if (!selectedData[invalidIndex].needState || !selectedData[invalidIndex].needState.id) {\n            ReactAPI.showMessage(\"w\", \"当前记录缺少配料需求状态，不能完成\");\n            return false;\n        }\n    }\n    //如果全部已更新无需再操作\n\tvar needIds = \"\";\n\tfor (var i = 0; i < selectedData.length; i++) {\n\t\tif ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/done\") {\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585277863700\", selectedData[i].rowIndex + 1));\n\t\t\treturn;\n\t\t} else if ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/stop\") {\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585283991307\", selectedData[i].rowIndex + 1));\n\t\t\treturn;\n\t\t} else if ((selectedData[i].needState && selectedData[i].needState.id) == \"WOM_batMatState/cancel\") {\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585284032149\", selectedData[i].rowIndex + 1));\n\t\t\treturn;\n\t\t} else {\n\t\t\tneedIds += selectedData[i].id + \",\";\n\t\t}\n\t}\n\t/*\n  * 若设置了区间上下限，判断已配数量是否大于等于区间下限，若小于，弹出提示框确认是否完成。\n  * 若没有设置区间上下限，判断已配数量是否大于等于需配数量，若小于，弹出提示框确认是否完成。\n  */\n\tvar confirmMsg = \"\";\n\tfor (var i = 0; i < selectedData.length; i++) {\n\t\tvar dataItem = selectedData[i];\n\t\tvar rowIndex = dataItem.rowIndex + 1;\n\t\tvar maxQuantity = dataItem.maxQuantity;\n\t\tvar minQuantity = dataItem.minQuantity;\n\t\tvar planNum = dataItem.planNum;\n\t\tvar offerNum = dataItem.offerNum;\n\t\tif (dataItem.needState.id == \"WOM_batMatState/noBatch\") {\n\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289496950\", rowIndex);\n\t\t} else if (dataItem.needState.id == \"WOM_batMatState/batching\") {\n\t\t\t//若设置了区间下限\n\t\t\tif (minQuantity != null && minQuantity !== \"\") {\n\t\t\t\tif (offerNum == null || offerNum === \"\") {\n\t\t\t\t\tofferNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum < minQuantity) {\n\t\t\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289757908\", rowIndex);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\tif (planNum == null || planNum === \"\") {\n\t\t\t\t\tplanNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum == null || offerNum === \"\") {\n\t\t\t\t\tofferNum = 0;\n\t\t\t\t}\n\t\t\t\tif (offerNum < planNum) {\n\t\t\t\t\tconfirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585289822557\", rowIndex);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\tif (confirmMsg != \"\") {\n\t\tReactAPI.openConfirm({\n\t\t\t//title:\"是否确认完成？\",\n\t\t\tmessage: confirmMsg,\n\t\t\tonOk: function onOk() {\n\t\t\t\tReactAPI.closeConfirm();\n\t\t\t\t//调接口更新需求状态\n\t\t\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\t\t\tvar data = { \"needIds\": needIds };\n\t\t\t\t$.ajax({\n\t\t\t\t\ttype: \"post\",\n\t\t\t\t\turl: url,\n\t\t\t\t\tdata: data,\n\t\t\t\t\tbeforeSend: function beforeSend() {\n\t\t\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t\t\t},\n\t\t\t\t\tsuccess: function success(res) {\n\t\t\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\t\t\tif (res.code == 200) {\n\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t\t\t//刷新表格\n\t\t\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\terror: function error(res) {\n\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message + \"！\");\n\t\t\t\t\t},\n\t\t\t\t\tcomplete: function complete() {\n\t\t\t\t\t\tReactAPI.closeLoading();\n\t\t\t\t\t}\n\n\t\t\t\t});\n\t\t\t}\n\t\t});\n\t} else {\n\t\t//调接口更新配料需求状态\n\t\tvar url = \"/msService/WOM/batchMaterialNeed/batchMatNeed/completeNeed\";\n\t\tvar data = { \"needIds\": needIds };\n\t\t$.ajax({\n\t\t\ttype: \"post\",\n\t\t\turl: url,\n\t\t\tdata: data,\n\t\t\tbeforeSend: function beforeSend() {\n\t\t\t\tReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n\t\t\t},\n\t\t\tsuccess: function success(res) {\n\t\t\t\t//根据执行结果显示提示信息\n\t\t\t\tif (res.code == 200) {\n\t\t\t\t\tReactAPI.showMessage(\"s\", res.data);\n\t\t\t\t\t//刷新表格\n\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t}\n\t\t\t},\n\t\t\terror: function error(res) {\n\t\t\t\tReactAPI.showMessage(\"f\", res.message + \"！\");\n\t\t\t},\n\t\t\tcomplete: function complete() {\n\t\t\t\tReactAPI.closeLoading();\n\t\t\t}\n\t\t});\n\t}\n}","id":"complete","operatetype":"CUSTOM","isconfirm":false,"CODE":"batchMaterialNeed_complete_add_WOM_1.0.0_batchMaterialNeed_batchMaterialNeed","NAME":"完成","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"complete(event)","ONCLICK":"complete(event)"}],"importMainXls":"/msService/WOM/batchMaterialNeed/batchMatNeed/importMainXls","mainDisplayName":"id","isTransCondition":false,"renderOver_es5":"if (ReactAPI.getComponentAPI(\"