/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId) // 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (var _i = 0; _i < data.length; _i++) {\n                //遍历\n                if (res.data[_i] != null && res.data[_i] == true) {\n                    //如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_batchMatNeed_sdg\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    });\n}, 1000);","nodeExpanded":false,"layoutmethod":"container","isExportExcel":true,"hasFastQuery":true,"isTreeView":false,"fields":[{"assPropertyName":"id","ass":{"tar":"WOM_1.0.0_produceTask_ProduceTask_id","org":"WOM_1.0.0_batchMaterialNeed_BatchMatNeed_taskId"},"precisionHasChanged":true,"code":"WOM_1.0.0_batchMaterialNeed_batchMaterialNeed_LISTPT_OTHER_WOM_1.0.0_batchMaterialNeed_BatchMatNeed_taskId_WOM_1.0.0_produceTask_ProduceTask_tableNo","isTotal":false,"isOrderBy":false,"seniorSystemcode":false,"displayName":"WOM.propertyshowName.randon1582009845640.flag","showFormatHasChanged":false,"isCount":false,"linkView":{"code":"WOM_1.0.0_produceTask_makeTaskView","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrTGlzdF9zZWxmfA__","iscrosscompany":"false","name":"makeTaskView","title":"WOM.viewtitle.randon1576029227700","url":"/msService/WOM/produceTask/produceTask/makeTaskView","openType":"frame"},"ecEnv":"product","propertyCode":"WOM_1.0.0_batchMaterialNeed_BatchMatNeed_taskId||WOM_1.0.0_produceTask_ProduceTask_tableNo","regio