emCode\").APIs(\"orderState\").removeOption(\"WOM_batMatState/waitAllocat\")\n\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"orderState\").getOptionById(\"WOM_batMatState/waitPut\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"orderState\").removeOption(\"WOM_batMatState/waitPut\")\n}\n//判断物料是否为危化品\n\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\").getDatagridData();\n    if (!data || !data.length) { return; }\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].productId != null && data[i].productId.id != null) {\n            materialId.push({ \"materialId\": data[i].productId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    //if(data[i].materialId!=null&&data[i].materialId.id!=null){//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res && Number(res.code) === 200 && Array.isArray(res.data)) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\")\n                        .setDatagridCellAttr(i, \"productId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","buttons":[{"isSignatureConfig":true,"funcbody":"function add(event) {\n    //获取表格对象\n    var table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    var tableInfoIds = \"\";\n    var ids = \"\";\n    var deploymentIds = \"\";\n    var productId = \"\";\n    ///\n    for(var i = 0;i<selectedData.length;i++){\n        var itemData = selectedData[i];\n        if(selectedData[i].orderState.id==\"WOM_batMatState/done\"){\n            //第{0}行，配料指令已完成，不允许进行操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550355403\", selectedData[i].rowIndex+1));\n            return;\n        }else if(selectedData[i].orderState.id==\"WOM_batMatState/stop\"){\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550452175\", selectedData[i].rowIndex+1));\n            return;\n        }else if(selectedData[i].orderState.id==\"WOM_batMatState/cancel\"){\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550495079\", selectedData[i].rowIndex+1));\n            return;\n        }else{\n            tableInfoIds+=itemData.tableInfoId;\n            productId+=itemData.productId.isBatch.id;\n            ids+=itemData.id;\n            deploymentIds+=itemData.pending.deploymentId;\n            tableInfoIds+=\",\";\n            ids+=\",\";\n            productId+=\",\";\n        }\n    }\n    ///\n    //打开批量配料页面\n    var url = \"/msService/WOM/batchMaterial/batchMateril/batchMaterialEdit?__pc__=VGFza0V2ZW50XzA5MzY3amJ8YmF0Y2hNYXRlcmls&entityCode=WOM_