{\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550495079\", selectedData[i].rowIndex + 1));\n            return;\n        } else {\n            tableInfoIds += itemData.tableInfoId;\n            productId += itemData.productId.isBatch.id;\n            ids += itemData.id;\n            deploymentIds += itemData.pending.deploymentId;\n            tableInfoIds += \",\";\n            ids += \",\";\n            productId += \",\";\n        }\n    }\n    ///\n    //打开批量配料页面\n    var url = \"/msService/WOM/batchMaterial/batchMateril/batchMaterialEdit?__pc__=VGFza0V2ZW50XzA5MzY3amJ8YmF0Y2hNYXRlcmls&entityCode=WOM_1.0.0_batchMaterial&superEdit=true&deploymentId=\" + deploymentIds;\n    url += \"&tableInfoIds=\" + tableInfoIds + \"&ids=\" + ids + \"&customConditionKey=productId&productId=\" + productId;\n    window.open(url);\n}","id":"batchMaterial","operatetype":"CUSTOM","isconfirm":false,"CODE":"batchMaterilList_batchMaterial_add_WOM_1.0.0_batchMaterial_batchMaterilList","NAME":"批量配料","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"add(event)","ONCLICK":"add(event)"},{"isSignatureConfig":true,"funcbody":"function complete(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        var itemData = selectedData[i];\n        var rowIndex = itemData.rowIndex + 1;\n        if (selectedData[i].orderState.id == \"WOM_batMatState/done\") {\n            //第{0}行，配料指令已完成，不允许进行操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550355403\", selectedData[i].rowIndex + 1));\n            return;\n        } else if (selectedData[i].orderState.id == \"WOM_batMatState/stop\") {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550452175\", selectedData[i].rowIndex + 1));\n            return;\n        } else if (selectedData[i].orderState.id == \"WOM_batMatState/cancel\") {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585550495079\", selectedData[i].rowIndex + 1));\n            return;\n        } else {\n            ids += selectedData[i].id + \",\";\n        }\n    }\n    /*\n     * 若设置了区间上下限，判断已配数量是否大于等于区间下限，若小于，弹出提示框确认是否完成。\n     * 若没有设置区间上下限，判断已配数量是否大于等于需配数量，若小于，弹出提示框确认是否完成。\n     */\n    var confirmMsg = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        var dataItem = selectedData[i];\n        var rowIndex = dataItem.rowIndex + 1;\n        var maxQuantity = dataItem.maxQuantity;\n        var minQuantity = dataItem.minQuantity;\n        var needNum = dataItem.needNum;\n        var offerNum = dataItem.offerNum;\n        if (dataItem.orderState.id != \"WOM_batMatState/finish\") {\n            //若设置了区间下限\n            if (minQuantity != null && minQuantity !== \"\" && maxQuantity != null && maxQuantity !== \"\") {\n                if (offerNum == null || offerNum === \"\") {\n                    offerNum = 0;\n                }\n                if (offerNum < minQuantity) {\n                    //\"第\"+rowIndex+\"行，已配数量小于区间下限<br/>\"\n                    confirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585292270192\", rowIndex);\n                }\n            } else {\n                if (needNum == null || needNum === \"\") {\n                    needNum = 0;\n                }\n                if (offerNum == null || offerNum === \"\") {\n                    offerNum = 0;\n                }\n                if (offerNum < needNum) {\n                    confirmMsg += ReactAPI.international.getText(\"WOM.custom.randon1585292464079\", rowIndex);\n                }\n            }\n        }\n    }\n    var url = \"/msService/WOM/batchMaterial/batchMateril/completeTask\";\n    var data = { \"ids\": ids };\n    if (confirmMsg != \"\") {\n        ReactAPI.openConfirm({\n            //title:ReactAPI.international.getText(''WOM.custom.randon1585291473338''),\n            message: confirmMsg,\n            onOk: function () {\n                ReactAPI.closeConfirm();\n                //调借口更新需求状态\n                $.ajax({\n                    type: \"post\",\n                    url: url,\n                    data: data,\n                    beforeSend: function () {\n                        ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing'')); //处理中\n                    },\n                    success: function (res) {\n                        //根据执行结果显示提示信息\n                        if (res.code == 200) {\n                            ReactAPI.showMessage(\"s\", res.data);\n                            //刷新表格\n                            $(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n                        }\n                    },\n                    error: function (res) {\n                        ReactAPI.showMessage(\"f\", res.message);\n                    },\n                    complete: function () {\n                        ReactAPI.closeLoading();\n                    }\n                });\n            }\n        });\n    } else {\n        ReactAPI.openConfirm({\n            message: ReactAPI.international.getText(''WOM.custom.randon1585291473338''),\n            onOk: function () {\n                ReactAPI.closeConfirm();\n                //调借口更新需求状态\n                $.ajax({\n                    type: \"post\",\n                    url: url,\n                    data: data,\n                    beforeSend: function () {\n                        ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing'')); //处理中\n                    },\n                    success: function (res) {\n                        //根据执行结果显示提示信息\n                        if (res.code == 200) {\n                            ReactAPI.showMessage(\"s\", res.data);\n                            //刷新表格\n                            $(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n                            //提交表单\n                            ReactAPI.submitFormData(\"submit\", function (res) { });\n                        }\n                    },\n                    error: function (res) {\n                        ReactAPI.showMessage(\"f\", res.message);\n                    },\n                    complete: function () {\n                        ReactAPI.closeLoading();\n                    }\n                });\n            }\n        });\n    }\n}","funcname":"onclick=''complete(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582090761123_1144","buttonoperationcode":"batchMaterilList_complate_add_WOM_1.0.0_batchMaterial_batchMaterilList","isHide":false,"showname":"完成","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfYmF0Y2hNYXRlcmlsTGlzdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterial_BatchMateril","namekey":"WOM.buttonPropertyshowName.randon1582090783726.flag","funcbody_es5":"function complete(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        var itemData = selectedData[i];\n   