/batchMaterial/batMaterilPart/downloadXls","selectFirstRow":false,"renderOver":"if (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"batRecordState\").getOptionById(\"WOM_batMatState/batching\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"batRecordState\").removeOption(\"WOM_batMatState/batching\")\n}\nif (ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"batRecordState\").getOptionById(\"WOM_batMatState/done\").label != undefined) {\n    ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"batRecordState\").removeOption(\"WOM_batMatState/done\")\n}\n//判断物料是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    //if(data[i].materialId!=null&&data[i].materialId.id!=null){//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n\n}, 1000);","buttons":[{"isSignatureConfig":true,"funcbody":"function print(){\n\t//获取表格对象\n\tvar table= ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\");\n\t//获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n\t\tReactAPI.showMessage(\"w\", \"请至少选择一个配料记录\");\n        return;\n    }\n\tfor(var i = 0;i<selectedData.length;i++){\n\t\tvar itemData = selectedData[i];\n\t\tvar rowIndex = itemData.rowIndex+1;\n\t\t//两种情况无需打印\n\t\t//1.配料模式：管道 RM_batchType/hubBat\n\t\t//2.使用场景：配于容器RM_batchSite/onContainer\n\t\t\n\t\t//配料模式\n\t\tvar batchType = itemData.batchType;\n\t\t//适用场景\n\t\tvar batchSite = itemData.batchSite;\n\t\t\n\t\tif(batchType.id==\"RM_batchType/hubBat\"){\n\t\t\tReactAPI.showMessage(\"w\", \"第\"+rowIndex+\"行，配料模式为管道配，无需打印！\");\n\t\t\treturn;\n\t\t}else if(batchSite.id==\"batchSite/onContainer\"){\n\t\t\tReactAPI.showMessage(\"w\", \"第\"+rowIndex+\"行，适用场景为配于容器，无需打印！\");\n\t\t\treturn;\n\t\t}\n\t}\n}","funcname":"onclick=''print()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1582113656351_5012","buttonoperationcode":"materialRecodList_print_add_WOM_1.0.0_batchMaterial_materialRecodList","isHide":true,"showname":"打印","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfbWF0ZXJpYWxSZWNvZExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterial_BatMaterilPart","namekey":"WOM.buttonPropertyshowName.randon1582113664694.flag","funcbody_es5":"function print() {\n\t//获取表格对象\n\tvar table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterilList_batchMateril_sdg\");\n\t//获取选择的数据\n\tvar selectedData = table.getSelecteds();\n\tif (selectedData.length == 0) {\n\t\t//提示未选择数据\n\t\tReactAPI.showMessage(\"w\", \"请至少选择一个配料记录\");\n\t\treturn;\n\t}\n\tfor (var i = 0; i < selectedData.length; i++) {\n\t\tvar itemData = selectedData[i];\n\t\tvar rowIndex = itemData.rowIndex + 1;\n\t\t//两种情况无需打印\n\t\t//1.配料模式：管道 RM_batchType/hubBat\n\t\t//2.使用场景：配于容器RM_batchSite/onContainer\n\n\t\t//配料模式\n\t\tvar batchType = itemData.batchType;\n\t\t//适用场景\n\t\tvar batchSite = itemData.batchSite;\n\n\t\tif (batchType.id == \"RM_batchType/hubBat\") {\n\t\t\tReactAPI.showMessage(\"w\", \"第\" + rowIndex + \"行，配料模式为管道配，无需打印！\");\n\t\t\treturn;\n\t\t} else if (batchSite.id == \"batchSite/onContainer\") {\n\t\t\tReactAPI.showMessage(\"w\", \"第\" + rowIndex + \"行，适用场景为配于容器，无需打印！\");\n\t\t\treturn;\n\t\t}\n\t}\n}","id":"print","operatetype":"CUSTOM","isconfirm":false,"CODE":"materialRecodList_print_add_WOM_1.0.0_batchMaterial_materialRecodList","NAME":"打印","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"isSignatureConfig":true,"funcbody":"function complete(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        if (selectedData[i].batRecordState.id != \"WOM_batMatState/noBatch\") {\n            //第{0}行，“配料状态”不为未配料或配料中，不能进行完成操作！</br>\n            //WOM.custom.randon1585295294579\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585295294579\", selectedData[i].rowIndex + 1));\n            return false;\n        } else {\n            ids += selectedData[i].id + \",\";\n        }\n    }\n    var url = \"/msService/WOM/batchMaterial/batMaterilPart/changeRecord\";\n    var data = {\n        \"ids\": ids,\n        \"status\": \"complete\"\n    };\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(\"WOM.custom.randon1585295431850\"),\n        onOk: function () {\n            ReactAPI.closeConfirm();\n            //调借口更新需求状态\n            $.ajax({\n                type: \"post\",\n                url: url,\n                data: data,\n                beforeSend: function () {\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                },\n                success: function (res) {\n                    if (res.data.dealSuccessFlag) {\n                        \n                        ReactAPI.showMessage(\"s\", res.message);\n                        //刷新表格\n                        $(\"button[data-id = ''query'']\").click();\n                    } else {\n                        ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                    }\n                    ReactAPI.closeLoading();\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"foundation.viewmanagement.dealsuccess\"));\n                    ReactAPI.closeLoading();\n                    //关闭页面\n                    window.close();\n                },\n                error: function (res) {\n                    ReactAPI.showMessage(\"f\", res.message);\n                    ReactAPI.closeLoading();\n                }\n            });\n        }\n    });\n}","funcname":"onclick=''complete(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582113683213_7343","buttonoperationcode":"materialRecodList_complete_add_WOM_1.0.0_batchMaterial_materialRecodList","isHide":false,"showname":"配料完成","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfbW