            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585295867720\", selectedData[i].rowIndex + 1));\n            return false;\n        }\n    }else if(batchType==''RM_batchType/remoteBat''){\n        if(batRecordState==''WOM_batMatState/finish''){\n            ids+=selectedData[i].id+\",\";\n        }else{\n            //WOM.custom.randon1585295968374\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585295968374\", selectedData[i].rowIndex + 1));\n            return false;   \n        }\n    }else if(batchType==''RM_batchType/hubBat''){\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585296085943\", selectedData[i].rowIndex + 1));\n        return false;   \n    }\n\tif (batchSite == ''RM_batchSite/onContainer''){\n\t\t// 第{0}行，“配于”为【配于容器】，不允许进行操作！\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1589523755953\", selectedData[i].rowIndex + 1));\n\t\treturn false;\n\t}\n}\n\nvar url = \"/msService/WOM/batchMaterial/batMaterilPart/changeRecord\";\nvar data={\n        \"ids\":ids,\n        \"status\":\"recall\"\n    };\nReactAPI.openConfirm({\n    message: ReactAPI.international.getText(\"WOM.custom.randon1585296159284\"),\n    onOk:function(){\n        ReactAPI.closeConfirm();\n        //调借口更新需求状态\n        $.ajax({\n            type:\"post\",\n            url:url,\n            data:data,\n            beforeSend:function(){\n                ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n            },\n            success:function(res){\n                if(res.data.dealSuccessFlag){\n                    ReactAPI.showMessage(\"s\", res.message);\n                    //刷新表格\n                    $(\"button[data-id = ''query'']\").click();\n                }else{\n                    ReactAPI.showMessage(\"f\", res.data.errorMessage);\n\n                }\n                ReactAPI.closeLoading();\n                //关闭页面\n                window.close();\n            },\n            error:function(res){\n                ReactAPI.showMessage(\"f\", res.responseJSON.msg);\n                ReactAPI.closeLoading();\n            }\n        });\n    }\n});\n}","funcname":"onclick=''recallClick(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1584435493425_134","buttonoperationcode":"materialRecodList_recall_add_WOM_1.0.0_batchMaterial_materialRecodList","isHide":false,"showname":"撤回","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfbWF0ZXJpYWxSZWNvZExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterial_BatMaterilPart","namekey":"WOM.buttonPropertyshowName.randon1584435507275.flag","funcbody_es5":"function recallClick(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    //9、现场配，待放可以撤回，现场配待投可以撤回。异地配，已配料时可以撤回。\n    for (var i = 0; i < selectedData.length; i++) {\n        var batchType = selectedData[i].headId.batchType.id; //配料模式\n        var batchSite = selectedData[i].headId.batchSite.id; //配于\n        var batRecordState = selectedData[i].batRecordState.id; //配料记录状态\n        if (batchType == ''RM_batchType/sceneBat'') {\n            if (batRecordState == ''WOM_batMatState/waitAllocat'' || batRecordState == ''WOM_batMatState/waitPut'') {\n                ids += selectedData[i].id + \",\";\n            } else {\n                // 第{0}行，配料模式为现场配，“配料记录状态”不为待放或待投，不能进行撤回操作！\n                ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585295867720\", selectedData[i].rowIndex + 1));\n                return false;\n            }\n        } else if (batchType == ''RM_batchType/remoteBat'') {\n            if (batRecordState == ''WOM_batMatState/finish'') {\n                ids += selectedData[i].id + \",\";\n            } else {\n                //WOM.custom.randon1585295968374\n                ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585295968374\", selectedData[i].rowIndex + 1));\n                return false;\n            }\n        } else if (batchType == ''RM_batchType/hubBat'') {\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585296085943\", selectedData[i].rowIndex + 1));\n            return false;\n        }\n        if (batchSite == ''RM_batchSite/onContainer'') {\n            // 第{0}行，“配于”为【配于容器】，不允许进行操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1589523755953\", selectedData[i].rowIndex + 1));\n            return false;\n        }\n    }\n\n    var url = \"/msService/WOM/batchMaterial/batMaterilPart/changeRecord\";\n    var data = {\n        \"ids\": ids,\n        \"status\": \"recall\"\n    };\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(\"WOM.custom.randon1585296159284\"),\n        onOk: function onOk() {\n            ReactAPI.closeConfirm();\n            //调借口更新需求状态\n            $.ajax({\n                type: \"post\",\n                url: url,\n                data: data,\n                beforeSend: function beforeSend() {\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                },\n                success: function success(res) {\n                    if (res.data.dealSuccessFlag) {\n                        ReactAPI.showMessage(\"s\", res.message);\n                        //刷新表格\n                        $(\"button[data-id = ''query'']\").click();\n                    } else {\n                        ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                    }\n                    ReactAPI.closeLoading();\n                    //关闭页面\n                    window.close();\n                },\n                error: function error(res) {\n                    ReactAPI.showMessage(\"f\", res.responseJSON.msg);\n                    ReactAPI.closeLoading();\n                }\n            });\n        }\n    });\n}","id":"recall","operatetype":"CUSTOM","isconfirm":false,"CODE":"materialRecodList_recall_add_WOM_1.0.0_batchMaterial_materialRecodList","NAME":"撤回","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0","onclick":"recallClick(event)","ONCLICK":"recallClick(event)"},{"isSignatureConfig":true,"funcbody":"function delivery(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        if (selectedData[i].batRecordState.id != \"WOM_batMatState/finish\" || selectedData[i].headId.batchType.id != \"RM_batchType/remoteBat\") {\n            //第{0}行，配料模式不为远程配，“配料记录状态”不为已配料，不能进行派送操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585296457217\", selectedData[i].rowIndex + 1));\n            return false;\n        } else {\n            ids += selectedData[i].id + \",\";\n        }\n    }\n\n    var url = \"/msService/WOM/batchMaterial/batMaterilPart/changeRecord\";\n    var data = {\n        \"ids\": ids,\n        \"status\": \"delivered\"\n    };\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(\"WOM.custom.randon1585296578696\"),\n        onOk: function () {\n            ReactAPI.closeConfirm();\n            //调借口更新需求状态\n            $.ajax({\n                type: \"post\",\n                url: url,\n                data: data,\n                beforeSend: function () {\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                },\n                success: function (res) {\n                    if (res.data.dealSuccessFlag) {\n                        ReactAPI.showMessage(\"s\", res.message);\n                        //刷新表格\n                        $(\"button[data-id = ''query'']\").click();\n                        //ReactAPI.closeLoading();\n                        //parent.ReactAPI.showMessage(\"s\", \"处理成功！\");\n                    } else {\n                        ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                    }\n                    ReactAPI.closeLoading();\n                    //关闭页面\n                    window.close();\n                },\n                error: function (res) {\n                    ReactAPI.showMessage(\"f\", res.message);\n                },\n                complete: function () {\n                    ReactAPI.closeLoading();\n                }\n            });\n        }\n    });\n}","funcname":"onclick=''delivery(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582113713136_2532","buttonoperationcode":"materialRecodList_delivery_add_WOM_1.0.0_batchMaterial_materialRecodList","isHide":false,"showname":"派送","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfbWF0ZXJpYWxSZWNvZExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterial_BatMaterilPart","namekey":"WOM.buttonPropertyshowName.randon1582113744854.flag","funcbody_es5":"function delivery(event) {\n    //获取表格对象\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return false;\n    }\n\n    //如果全部已更新无需再操作\n    var ids = \"\";\n    for (var i = 0; i < selectedData.length; i++) {\n        if (selectedData[i].batRecordState.id != \"WOM_batMatState/finish\" || selectedData[i].headId.batchType.id != \"RM_batchType/remoteBat\") {\n            //第{0}行，配料模式不为远程配，“配料记录状态”不为已配料，不能进行派送操作！\n            ReactAPI.showMessage(\"w\", ReactAPI.international.getText(\"WOM.custom.randon1585296457217\", selectedData[i].rowIndex + 1));\n            return false;\n        } else {\n            ids += selectedData[i].id + \",\";\n        }\n    }\n\n    var url = \"/msService/WOM/batchMaterial/batMaterilPart/changeRecord\";\n    var data = {\n        \"ids\": ids,\n        \"status\": \"delivered\"\n    };\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(\"WOM.custom.randon1585296578696\"),\n        onOk: function onOk() {\n            ReactAPI.closeConfirm();\n            //调借口更新需求状态\n            $.ajax({\n                type: \"post\",\n                url: url,\n                data: data,\n                beforeSend: function beforeSend() {\n                    ReactAPI.openLoading(ReactAPI.international.getText(\"EditView.notice.processing\"));\n                },\n                success: function success(res) {\n                    if (res.data.dealSuccessFlag) {\n                        ReactAPI.showMessage(\"s\", res.message);\n                        //刷新表格\n                        $(\"button[data-id = ''query'']\").click();\n                        //ReactAPI.closeLoading();\n                        //parent.ReactAPI.showMessage(\"s\", \"处理成功！\");\n                    } else {\n      