 url: url,\n        isRef: false, // 是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(\"Button.text.save\"), // 保存\n                type: \"primary\",\n                onClick: event => {\n                    var isSubmit = false;\n                    if (!isSubmit) {\n                        var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materailRecodSingFordg1582115181801\");\n                        //获取表格数据\n                        var tableData = editTable.getDatagridData();\n                        var errorMessage = \"\";\n                    }\n                    //校验 \n                    for (var i = 0; i < tableData.length; i++) {\n                        var reciveStaff = tableData[i].reciveStaff;\n                        var receiveDate = tableData[i].receiveDate;\n                        var reciveNum = tableData[i].reciveNum;\n                        var rejectReason = tableData[i].rejectReason;\n                        var receiveState = tableData[i].receiveState;\n                        if (reciveStaff == null || reciveStaff == undefined) {\n                            // \t“接收人”第{0}行不允许为空！第{0}行</br>\n                            errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585297550082\", tableData[i].rowIndex + 1);\n                            ReactAPI.showMessage(\"f\", errorMessage);\n                            return false;\n                        }\n                        if (receiveDate == null || receiveDate == undefined) {\n                            // 第{0}行，“签收时间”不允许为空！</br>\n                            errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585297456084\", tableData[i].rowIndex + 1);\n                            ReactAPI.showMessage(\"f\", errorMessage);\n                            return false;\n                        }\n                        if (!receiveState || !receiveState.id) {\n   