tText(\"WOM.custom.randon1585297358356\"),\n        size: 6,\n        url: url,\n        isRef: false, // 是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(\"Button.text.save\"), // 保存\n                type: \"primary\",\n                onClick: event => {\n                    var isSubmit = false;\n                    if (!isSubmit) {\n                        var editTable = event.ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materailRecodSingFordg1582115181801\");\n                        //获取表格数据\n                        var tableData = editTable.getDatagridData();\n                        var errorMessage = \"\";\n                    }\n                    //校验 \n                    for (var i = 0; i < tableData.length; i++) {\n                        var reciveStaff = tableData[i].reciveStaff;\n                        var receiveDate = tableData[i].receiveDate;\n                        var reciveNum = tableData[i].reciveNum;\n                        var rejectReason = tableData[i].rejectReason;\n                        var receiveState = tableData[i].receiveState;\n                        if (reciveStaff == null || reciveStaff == undefined) {\n                            // \t“接收人”第{0}行不允许为空！第{0}行</br>\n                            errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585297550082\", tableData[i].rowIndex + 1);\n                            ReactAPI.showMessage(\"f\", errorMessage);\n                            return false;\n                        }\n                        if (receiveDate == null || receiveDate == undefined) {\n                            // 第{0}行，“签收时间”不允许为空！</br>\n                            errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585297456084\", tableData[i].rowIndex + 1);\n                            ReactAPI.showMessage(\"f\", errorMessage);\n                            return false;\n                        }\n                        if (!receiveState || !receiveState.id) {\n                            // \t第{0}行，“接收/拒收”不允许为空！\n                            errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585649485213\", tableData[i].rowIndex + 1);\n                            ReactAPI.showMessage(\"f\", errorMessage);\n                            return false;\n                        } else {\n                            if (tableData[i].receiveState.id == \"WOM_receiveState/receive\") {\n                                if (reciveNum == null || reciveNum == undefined || reciveNum == \"\") {\n                                    // 第{0}行，接收时复称数量不允许为空！</br>\n                                    errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585297602746\", tableData[i].rowIndex + 1);\n                                    ReactAPI.showMessage(\"f\", errorMessage);\n                                    return false;\n                                }\n                            } else if (tableData[i].receiveState.id == \"WOM_receiveState/reject\") {\n                                if (rejectReason == null) {\n                                    // 第{0}行，配料记录已拒收，“拒收原因”不允许为空！</br>\n                                    errorMessage = ReactAPI.international.getText(\"WOM.custom.randon1585648366569\", tableData[i].rowIndex + 1);\n                                    ReactAPI.showMessage(\"f\", errorMessage);\n                                    return false;\n                                }\n                            }\n                        }\n                    }\n                    //调接口配料记录\n                    var url = \"/msService/WOM/batchMaterial/batMaterilPart/signFor\";\n                    var data = {\n                        details: JSON.stringify(tableData),\n                    };\n                    $.ajax({\n                        type: \"post\",\n                        url: url,\n                        data: data,\n                        async: false,\n                        success: function (res) {\n                            var data = res.data;\n                            if (!data.dealSuccessFlag) {\n                                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n                            } else {\n                                ReactAPI.destroyDialog(dialogName);\n                                // 刷新列表\n                                $(\"button[data-id=''query'']\").click();\n                                ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"WOM.custom.randon1595920718044\"));\n                            }\n                        },\n                        error: function (res) {\n                            ReactAPI.showMessage(\"f\", res.message);\n                        }\n                    });\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.close\"), // 关闭\n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''signfor()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":true,"ispermission":false,"cellCode":"cell_1582113825953_2937","buttonoperationcode":"materialRecodList_signfor_add_WOM_1.0.0_batchMaterial_materialRecodList","isHide":false,"showname":"接收","ecEnv":"product","pc":"__pc__=V09NXzEuMC4wX2JhdGNoTWF0ZXJpYWxfbWF0ZXJpYWxSZWNvZExpc3Rfc2VsZnw_","regionType":"BUTTON","iscallback":false,"modelCode":"WOM_1.0.0_batchMaterial_BatMaterilPart","namekey":"WOM.buttonPropertyshowName.randon1582113852798.flag","funcbody_es5":"function signfor() {\n    var table = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_materialRecodList_batMaterilPart_sdg\");\n    //获取选择的数据\n    var selectedData = table.getSelecteds();\n    if (selectedData.length == 0) {\n        //提示未选择数据\n        Re