      var newRowData = {\n            headId: selectData.headId,//配料指令单\n            batchType: selectData.batchType,//配料模式\n            batchSite: selectData.batchSite,//配于\n            materialId: selectData.materialId,//物料\n            batchingNeedId: selectData.batchingNeedId,//配料需求\n            //batRecordState:selectData.batRecordState//状态\n        };\n        //增加一行\n        editTable.addLine();\n        //设置数据\n        editTable.setRowData(editTable.getDatagridData().length - 1, newRowData);\n    }\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_batchMaterial_batchMaterialEditdg1582092735767\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_batchMaterialEditdg1582092735767\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" }, readonly: true });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_batchMaterial_batchMaterialEditdg1582092735767\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { styl