[_i] != null && res.data[_i] == true) {\n                    //如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectEditdg1581993495790\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#B30303\" }, readonly: true });\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectEditdg1581993495790\").setDatagridCellAttr(_i, \"materialId.code\", { style: { color: \"#505050\" }, readonly: true });\n                }\n            }\n        }\n    });\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-1","ratio_h":70,"layoutmethod":"container","ptRealTimeLoad":1,"isreadonly":0,"layno":2,"layoutname":"column-3","islefttopfixed":false,"nums":1}],"tabViewIndex":0,"isborder":0,"isrightbottomfixed":false,"type":"layout","isreadonlyBak":0,"ptRealTimeLoad":1,"layoutmethod":"column","namekey":"ec.view.commoninfo","name":"常规信息","isreadonly":0,"layno":1,"id":null,"tabCode":"tab_0","layoutname":"tabs-1","nums":2,"islefttopfixed":false}],"layoutmethod":"tab","type":"layout"},{"fix_h":95,"components":null,"layoutmethod":"container","type":"workflow"}],"layoutmethod":"column","type":"layout"}],"enableSimpleDealInfo":false,"title":"WOM.viewtitle.randon1581992886841","url":"/msService/WOM/rejectMaterilal/rejectMaterial/batchRejectEdit","dealInfoShow":false,"hasAttachment":true,"pageType":"EDIT","dealInfoGroup":"byTime","refCopy":{"isReference":false},"colNum":6,"layoutType":"classic","selfAdaption":false,"events":[{"function":"var operateType= ReactAPI.getOperateType();\nif(operateType===''submit''){\n    //提交时\n    var dataGrid=ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectEditdg1581993495790\");\n    var data=dataGrid.getDatagridData();\n    if(data.length==0){\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.atLeastOneRecord''));\n        return false;    \n    }\n    for(var i=0;i<data.length;i++){\n        var recordState=data[i].batchingPartId.batRecordState.id;\n        var recordValue=data[i].batchingPartId.batRecordState.value;\n        var offerNum=data[i].batchingPartId.offerNum;\n        var putinNum=data[i].batchingPartId.putinNum;\n        var returnNum=data[i].rejectNum;\n        //出库仓库，货位\n        var outWareId=data[i].outWareId.id;\n        var outStoreId=data[i].outStoreId;\n        //入库仓库，货位状态，货位\n        var wareId=data[i].wareId.id;\n        var storesetState=data[i].wareId.storesetState;\n        var storeId=data[i].storeId;\n\n        if(storesetState && (!storeId ||!storeId.code) ){\n            //第{0}行，入库仓库已启用货位，“入库货位编码”不允许为空！\n           //WOM.custom.randon1602587179965\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602587179965'', data[i].rowIndex + 1));\n            return false;\n        }\n\n        if(recordState!=''WOM_batMatState/puted'' && returnNum>offerNum){\n            //WOM.custom.randon1602587665329\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602587665329'', data[i].rowIndex + 1,recordValue));\n            //ReactAPI.showMessage(\"w\", \"第\"+(i+1)+\"行，配料记录状态为\"+recordValue+\"，退料数量必须不大于配料数量！\");\n            return false; \n        }else if(recordState==''WOM_batMatState/puted'' && returnNum>(offerNum-putinNum)){\n            //WOM.custom.randon1602588046137\n            //第{0}行，配料记录状态为{1}，退料数量必须不大于配料数量-已投数量！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602588046137'', data[i].rowIndex + 1,recordValue));\n            return false; \n        }\n    }\n}","name":"onsave"},{"function":"var operateType = ReactAPI.getOperateType();\nif (operateType === ''submit'') {\n    //提交时\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectEditdg1581993495790\");\n    var data = dataGrid.getDatagridData();\n    if (data.length == 0) {\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''WOM.custom.atLeastOneRecord''));\n        return false;\n    }\n    for (var i = 0; i < data.length; i++) {\n        var recordState = data[i].batchingPartId.batRecordState.id;\n        var recordValue = data[i].batchingPartId.batRecordState.value;\n        var offerNum = data[i].batchingPartId.offerNum;\n        var putinNum = data[i].batchingPartId.putinNum;\n        var returnNum = data[i].rejectNum;\n        //出库仓库，货位\n        var outWareId = data[i].outWareId.id;\n        var outStoreId = data[i].outStoreId;\n        //入库仓库，货位状态，货位\n        var wareId = data[i].wareId.id;\n        var storesetState = data[i].wareId.storesetState;\n        var storeId = data[i].storeId;\n\n        if (storesetState && (!storeId || !storeId.code)) {\n            //第{0}行，入库仓库已启用货位，“入库货位编码”不允许为空！\n            //WOM.custom.randon1602587179965\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602587179965'', data[i].rowIndex + 1));\n            return false;\n        }\n\n        if (recordState != ''WOM_batMatState/puted'' && returnNum > offerNum) {\n            //WOM.custom.randon1602587665329\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602587665329'', data[i].rowIndex + 1, recordValue));\n            //ReactAPI.showMessage(\"w\", \"第\"+(i+1)+\"行，配料记录状态为\"+recordValue+\"，退料数量必须不大于配料数量！\");\n            return false;\n        } else if (recordState == ''WOM_batMatState/puted'' && returnNum > offerNum - putinNum) {\n            //WOM.custom.randon1602588046137\n            //第{0}行，配料记录状态为{1}，退料数量必须不大于配料数量-已投数量！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1602588046137'', data[i].rowIndex + 1, recordValue));\n            return false;\n        }\n    }\n}","name":"onsave_es5"}]}';
DECLARE runtime_extra_view_existing_oid oid;
DECLARE runtime_extra_view_target_oid oid;
BEGIN
    SELECT udt_name = 'oid' INTO runtime_extra_view_json_is_oid
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'runtime_extra_view'
      AND column_name = 'view_json';
    IF COALESCE(runtime_extra_view_json_is_oid, false) THEN
        SELECT view_json INTO runtime_extra_view_existing_oid
        FROM public.runtime_extra_view
        WHERE code = 'WOM_1.0.0_rejectMaterilal_batchRejectEdit';
        IF runtime_extra_view_existing_oid IS NOT NULL THEN
            IF EXISTS (
                SELECT 1
                FROM pg_largeobject_metadata
                WHERE oid = runtime_extra_view_existing_oid
            ) THEN
                IF convert_from(lo_get(runtime_extra_view_existing_oid), 'UTF8') = runtime_extra_view_payload THEN
                    runtime_extra_view_target_oid := runtime_extra_view_existing_oid;
                END IF;
            END IF;
        END IF;
