ype":"SYSTEMCODE","fullPropertyCode":"WOM_1.0.0_rejectMaterilal_RejctMatalPart_headId||WOM_1.0.0_rejectMaterilal_RejectMaterial_rejectType","fill":{"fillType":3,"fillName":"系统编码","fillContent":"WOM_rejectType","listType":"list"},"columnType":"SYSTEMCODE","isrefselect":false,"name":"headId.rejectType","modelcode":"WOM_1.0.0_rejectMaterilal_RejectMaterial","multable":false,"maxLength":4000,"columnName":"REJECT_TYPE"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"renderOver":"setTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectPrtList_rejctMatalPart_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    if (data.length != 0 && materialId.length != 0) {\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n            contentType: \"application/json;charset=UTF-8\",\n            data: JSON.stringify(materialId)// 将json数据转化为字符\n        }, function (res) {\n            if (res.code = 200) {\n                for (let i = 0; i < data.length; i++) {//遍历\n                    if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                            .APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectPrtList_rejctMatalPart_sdg\")\n                            .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                    }\n                    else if (res.data[i] != null && res.data[i] == false) {\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n     