e === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"headId.id\");\n    var rejectType = valueAtPath(row, \"headId.rejectType.id\")\n        || valueAtPath(row, \"headId.rejectType\");\n    var routes = {\n        \"WOM_rejectType/forPrepare\": \"/msService/WOM/rejectMaterilal/rejectMaterial/prePareRejectView\",\n        \"WOM_rejectType/forBatch\": \"/msService/WOM/rejectMaterilal/rejectMaterial/batchRejectView\",\n        \"WOM_rejectType/factoryMateria\": \"/msService/WOM/rejectMaterilal/rejectMaterial/materiaRejectView\"\n    };\n    var detailUrl = routes[rejectType];\n    if (!recordId || !detailUrl) {\n        ReactAPI.showMessage(\"w\", \"当前退料记录缺少可用的来源单据\");\n        return false;\n    }\n    var target = detailUrl + \"?viewCode=WOM_1.0.0_rejectMaterilal_batchRejectPrtList\"\n        + \"&entityCode=WOM_1.0.0_rejectMaterilal\"\n        + \"&iscrosscompany=false\"\n        + \"&openType=frame\"\n        + \"&iscallback=false\"\n        + \"&id=\" + encodeURIComponent(recordId);\n    window.open(target, \"_blank\");\n    return true;\n}","funcbody_es5":"function viewWomBatchRejectPrtList() {\n    var gridFactory = ReactAPI.getComponentAPI(\"SupDataGrid\");\n    var grid = gridFactory && gridFactory.APIs(\"WOM_1.0.0_rejectMaterilal_batchRejectPrtList_rejctMatalPart_sdg\");\n    var selected = grid && grid.getSelecteds ? grid.getSelecteds() : [];\n    if (!selected || !selected.length) {\n        ReactAPI.showMessage(\"w\", \"请选择一条退料记录\");\n        return false;\n    }\n    var row = selected[0];\n    function valueAtPath(source, path) {\n        if (!source) { return null; }\n        if (Object.prototype.hasOwnProperty.call(source, path)) {\n            return source[path];\n        }\n        var value = source;\n        var parts = path.spl