 ReactAPI.getComponentAPI(\"Reference\").APIs(\"rejectMaterial.workAreaId.name\");\n    let workAreaId = workAreaComponent.getValue().length ? workAreaComponent.getValue()[0].id : ''-1'';\n    var url = \"/msService/HierarchicalMod/factoryWare/factoryMateria/materiaRejectRef?customConditionKey=workAreaId&workAreaId=\" + workAreaId;\n    ReactAPI.createDialog(\"newDialog\", {\n        // 车间物料参照\n        title: ReactAPI.international.getText(''WOM.custom.randon1597229392485''),\n        size: 5,\n        url: url,\n        isRef: true,//是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(''Button.text.select''),// 选择\n                type: \"primary\",\n                onClick: function (data, event) {\n                    callback(data, event);\n                }\n            },\n            {\n                text: ReactAPI.international.getText(''Button.text.cancel''), // 取消\n                onClick: event => {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                }\n            }\n        ],\n        callback: (data, event) => {\n            callback(data, event);\n        },\n        onOk: (data, event) => {\n            callback(data, event);\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n        },\n        onCancel: (data, event) => {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n    var callback = (data, event) => {\n        //获取选择的指令，将数据填入表体\n        if (data.length > 0) {\n            var records = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\").getDatagridData().map(record => record.factoryMateriaId.id);\n            var newrecords\n            if (records.length > 0) {\n                newrecords = data.filter(record => records.indexOf(record.id) == -1)\n            } else {\n                newrecords = data;\n            }\n            for (var i = 0; i < newrecords.length; i++) {\n                let data = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590'');\n                data.addLine();\n                var length = data.getDatagridData().length - 1;\n                // 物料\n                data.setRowData(length, { materialId: newrecords[i].productId })\n                // \t出库仓库\n                data.setRowData(length, { outWareId: newrecords[i].factoryId.factoryClass })\n                // 出库货位\n                data.setRowData(length, { outStoreId: newrecords[i].toNeedStore })\n                // data.setCellValueByKey(length,\"outStoreId.code\",newrecords[i].toNeedStore.code)\n                // data.setCellValueByKey(length,\"outStoreId.name\",newrecords[i].toNeedStore.name)\n                // 入库仓库\n                data.setRowData(length, { wareId: newrecords[i].fromWare })\n                // 入库货位\n                data.setRowData(length, { storeId: newrecords[i].fromStore })\n                //备注\n                data.setRowData(length, { remark: newrecords[i].remark })\n                // 车间物料id\n                data.setRowData(length, { factoryMateriaId: newrecords[i] })\n                // 退料数量\n                data.setRowData(length, { rejectNum: newrecords[i].availiQuantity })\n            }\n            // 添加成功\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(''WOM.custom.randon1586564469987''));\n            //判断物料是否为危化品\n            setTimeout(function () {\n                let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\").getDatagridData();\n                let materialId = [];\n                for (let i = 0; i < data.length; i++) {\n                    if (data[i].materialId != null && data[i].materialId.id != null) {\n                        materialId.push({ \"materialId\": data[i].materialId.id });\n                    }\n                    else\n                        materialId.push({ \"materialId\": -1 });\n                }\n                if (data.length != 0 && materialId.length != 0) {\n                    ReactAPI.request({\n                        type: \"post\",\n                        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n                        contentType: \"application/json;charset=UTF-8\",\n                        data: JSON.stringify(materialId)// 将json数据转化为字符\n                    }, function (res) {\n                        if (res.code = 200) {\n                            for (let i = 0; i < data.length; i++) {//遍历\n                                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" }, readonly: true });\n                                }\n                                else if (res.data[i] != null && res.data[i] == false) {\n                                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" }, readonly: true });\n                                }\n                            }\n                        }\n                    }\n                    );\n                }\n\n            }, 10);\n        } else {\n            //报错提示信息\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''WOM.custom.randon1594371176476''));\n        }\n    }\n}","funcname":"onclick=''function refFactoryMateria(event)''","buttonstyle":"add","iscustomf