RpdF9zZWxmfA__","width":100,"textalign":"left","isCustom":false,"multable":false,"columnName":"REMARK"}],"treePaging":false,"isNoCopy":false,"isCheckBox":false,"cannotAddNewRow":true,"acceptRevisions":false,"targetPropertyCode":"WOM_1.0.0_rejectMaterilal_RejctMatalPart_headId","code":"WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681","idPrefix":"RejctMatalPart_dg1581994918681","hideRevision":false,"title":null,"maxTableHeight":0,"getRevisions":false,"ptPageInit":"$(\"#btn-refPrepMatralPart i\").attr(\"class\",\"sup-btn-icon sup-btn-eighteen-dt-op-reference\");","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''taskId.id'',''preparePartId.id'',''batchingPartId.id'',''storeId.id'',''materialId.id'',''headId.id'',''wareId.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function refBatMaterilPart(event) {\n    var url = \"/msService/WOM/prePraOrder/prepMatralReco/recordForReturn\";\n    ReactAPI.createDialog(\"newDialog\", {\n        // 备料记录参照\n        title: ReactAPI.international.getText(\"WOM.viewtitle.randon1593659988967\"),// 备料记录参照\n        size: 5,\n        url: url,\n        isRef: true,//是否开启参照\n        buttons: [\n            {\n                text: ReactAPI.international.getText(\"Button.text.select\"),// 选择\n                type: \"primary\",\n                onClick: function (data, event) {\n                    callback(data, event);\n                    ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\"));// 添加成功！\n                }\n            },\n            {\n                text: ReactAPI.international.getText(\"Button.text.cancel\"),// 取消\n                onClick: event => {\n                    ReactAPI.destroyDialog(\"newDialog\");\n                }\n            }\n        ],\n        callback: (data, event) => {\n            callback(data, event);\n        },\n        onOk: (data, event) => {\n            callback(data, event);\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\"));// 添加成功！\n        },\n        onCancel: (data, event) => {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n\n    var callback = (data, event) => {\n        //获取选择的备料记录，将数据填入备料退料记录\n        if (data.length > 0) {\n            var records = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681\").getDatagridData().map(record => record.prePrePartId.id)\n            var newrecords\n            if (records.length > 0) {\n                newrecords = data.filter(record => records.indexOf(record.id) == -1)\n            } else {\n                newrecords = data;\n            }\n            //插入退料表明细\n            for (var i = 0; i < newrecords.length; i++) {\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').addLine();\n                var length = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').getDatagridData().length - 1;\n                //物料\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { materialId: newrecords[i].materialId })\n                //出库仓库\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { outWareId: newrecords[i].toWareId })\n                //出库货位\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { outStoreId: newrecords[i].toStoreId })\n                //入库仓库-默认退回源仓库\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { wareId: newrecords[i].fromWare })\n                //入库货位\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { storeId: newrecords[i].fromStore })\n                //物料批号\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { materialBatchNum: newrecords[i].materialBatchNum })\n                //备料记录id\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { prePrePartId: newrecords[i] })\n                if (newrecords[i].recordState.id == ''WOM_prePareState/reject'') {\n                    //退料数量\n                    ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectNum: newrecords[i].preNum })\n                } else {\n                    //部分接收 退料数量=备料数量-接收数量\n                    ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectNum: (newrecords[i].preNum - newrecords[i].receiveNum) })\n                }\n                //退料原因\trejectReason\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectReason: newrecords[i].rejectReason })\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { remark: newrecords[i].remark })\n\n            }\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\"));// 添加成功！\n            //判断物料是否为危化品\n            setTimeout(function () {\n                let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\").getDatagridData();\n                let materialId = [];\n                for (let i = 0; i < data.length; i++) {\n                    if (data[i].materialId != null && data[i].materialId.id != null) {\n                        materialId.push({ \"materialId\": data[i].materialId.id });\n                    }\n                    else\n                        materialId.push({ \"materialId\": -1 });\n                }\n                if (data.length != 0 && materialId.length != 0) {\n                    ReactAPI.request({\n                        type: \"post\",\n                        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n                        contentType: \"application/json;charset=UTF-8\",\n                        data: JSON.stringify(materialId)// 将json数据转化为字符\n                    }, function (res) {\n                        if (res.code = 200) {\n                            for (let i = 0; i < data.length; i++) {//遍历\n                                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" }, readonly: true });\n                                }\n                                else if (res.data[i] != null && res.data[i] == false) {\n                                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" }, readonly: true });\n                                }\n                            }\n                        }\n                    }\n                    );\n                }\n            }, 10);\n        } else {\n            //报错提示信息 请至少选中一行\n            ReactAPI.showMessage(''f'', ReactAPI.international.getText(\"WOM.custom.randon1594371176476\"));// 请至少选中一行！\n        }\n    }\n}","funcname":"onclick=''refBatMaterilPart(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1581995482847_3806","isHide":false,"showname":"参照备料记录","pc":"__pc__=V09NXzEuMC4wX3JlamVjdE1hdGVyaWxhbF9wcmVQYXJlUmVqZWN0RWRpdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"namekey":"WOM.buttonPropertyshowName.randon1581995495649.flag","funcbody_es5":"function refBatMaterilPart(event) {\n    var url = \"/msService/WOM/prePraOrder/prepMatralReco/recordForReturn\";\n    ReactAPI.createDialog(\"newDialog\", {\n        // 备料记录参照\n        title: ReactAPI.international.getText(\"WOM.viewtitle.randon1593659988967\"), // 备料记录参照\n        size: 5,\n        url: url,\n        isRef: true, //是否开启参照\n        buttons: [{\n            text: ReactAPI.international.getText(\"Button.text.select\"), // 选择\n            type: \"primary\",\n            onClick: function onClick(data, event) {\n                _callback(data, event);\n                ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\")); // 添加成功！\n            }\n        }, {\n            text: ReactAPI.international.getText(\"Button.text.cancel\"), // 取消\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(\"newDialog\");\n            }\n        }],\n        callback: function callback(data, event) {\n            _callback(data, event);\n        },\n        onOk: function onOk(data, event) {\n            _callback(data, event);\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\")); // 添加成功！\n        },\n        onCancel: function onCancel(data, event) {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n\n    var _callback = function _callback(data, event) {\n        //获取选择的备料记录，将数据填入备料退料记录\n        if (data.length > 0) {\n            var records = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681\").getDatagridData().map(function (record) {\n                return record.prePrePartId.id;\n            });\n            var newrecords;\n            if (records.length > 0) {\n                newrecords = data.filter(function (record) {\n                    return records.indexOf(record.id) == -1;\n                });\n            } else {\n                newrecords = data;\n            }\n            //插入退料表明细\n            for (var i = 0; i < newrecords.length; i++) {\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').addLine();\n                var length = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').getDatagridData().length - 1;\n                //物料\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { materialId: newrecords[i].materialId });\n                //出库仓库\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { outWareId: newrecords[i].toWareId });\n                //出库货位\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { outStoreId: newrecords[i].toStoreId });\n                //入库仓库-默认退回源仓库\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { wareId: newrecords[i].fromWare });\n                //入库货位\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { storeId: newrecords[i].fromStore });\n                //物料批号\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { materialBatchNum: newrecords[i].materialBatchNum });\n                //备料记录id\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { prePrePartId: newrecords[i] });\n                if (newrecords[i].recordState.id == ''WOM_prePareState/reject'') {\n                    //退料数量\n                    ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectNum: newrecords[i].preNum });\n                } else {\n                    //部分接收 退料数量=备料数量-接收数量\n                    ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectNum: newrecords[i].preNum - newrecords[i].receiveNum });\n                }\n                //退料原因\trejectReason\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { rejectReason: newrecords[i].rejectReason });\n                ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_rejectMaterilal_prePareRejectEditdg1581994918681'').setRowData(length, { remark: newrecords[i].remark });\n            }\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"WOM.custom.randon1586564469987\")); // 添加成功！\n            //判断物料是否为危化品\n            setTimeout(function () {\n                var data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\").getDatagridData();\n     