为危化品\nsetTimeout(function () {\n    var data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\").getDatagridData();\n    var materialId = [];\n    for (var i = 0; i < data.length; i++) {\n        if (data[i].prodctId != null && data[i].prodctId.id != null) {\n            materialId.push({ \"materialId\": data[i].prodctId.id });\n        } else materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId) // 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (var _i = 0; _i < data.length; _i++) {\n                //遍历\n                if (res.data[_i] != null && res.data[_i] == true) {\n                    //如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\").setDatagridCellAttr(_i, \"prodctId.code\", { style: { color: \"#B30303\" } });\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\").setDatagridCellAttr(_i, \"prodctId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    });\n}, 1000);","name":"onload_es5"},{"function":"//判断产品编码是否为危化品\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].prodctId != null && data[i].prodctId.id != null) {\n            materialId.push({ \"materialId\": data[i].prodctId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputViewdg1575884011030\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","name":"onload"}]}';
DECLARE runtime_extra_view_existing_oid oid;
DECLARE runtime_extra_view_target_oid oid;
BEGIN
    SELECT udt_name = 'oid' INTO runtime_extra_view_json_is_oid
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'runtime_extra_view'
      AND column_name = 'view_json';
    IF COALESCE(runtime_extra_view_json_is_oid, false) THEN
        SELECT view_json INTO runtime_extra_view_existing_oid
        FROM public.runtime_extra_view
        WHERE code = 'WOM_1.0.0_outputMaterial_outputView';
        IF runtime_extra_view_existing_oid IS NOT NULL THEN
            IF EXISTS (
                SELECT 1
                FROM pg_largeobject_metadata
                WHERE oid = runtime_extra_view_existing_oid
            ) THEN
                IF convert_from(lo_get(runtime_extra_view_existing_oid), 'UTF8') = runtime_extra_view_payload THEN
                    runtime_extra_view_target_oid := runtime_extra_view_existing_oid;
                END IF;
            END IF;
        END IF;
        IF runtime_extra_view_target_oid IS NULL THEN
            runtime_extra_view_target_oid := lo_from_bytea(0, convert_to(runtime_extra_view_payload, 'UTF8'));
        END IF;
        INSERT INTO public.runtime_extra_view (code, ec_env, version, view_code, view_json, proj_flag)
        VALUES ('WOM_1.0.0_outputMaterial_outputView', 'product', 0, 'WOM_1.0.0_outputMaterial_outputView', runtime_extra_view_target_oid, false)
        ON CONFLICT (code) DO UPDATE SET
            ec_env = COALESCE(EXCLUDED.ec_env, public.runtime_extra_view.ec_env),
            version = GREATEST(COALESCE(public.runtime_extra_view.version, 0), EXCLUDED.version),
            view_code = EXCLUDED.view_code,
            view_json = EXCLUDED.view_json,
            proj_flag = COALESCE(public.runtime_extra_view.proj_flag, EXCLUDED.proj_flag);
