lse,"mnecode":false,"selfType":"SYSTEMCODE","fullPropertyCode":"WOM_1.0.0_outputMaterial_OutMateDetail_outputType","fill":{"fillType":3,"fillName":"系统编码","fillContent":"WOM_reportType","listType":"list"},"columnType":"SYSTEMCODE","isrefselect":false,"name":"outputType","modelcode":"WOM_1.0.0_outputMaterial_OutMateDetail","multable":false,"maxLength":4000,"columnName":"OUTPUT_TYPE"}}],"expandType":"all","isExpandAll":true,"type":"layoutSearchWidget","layoutName":"layoutSearchWidget"},{"isSuperTable":false,"idPrefix":"ec_WOM_outputMaterial_outMateDetail_outputDetailList","isFirstLoad":false,"type":"layoutDatagrid","ratio_h":100,"dbcustomtextarea":"function outputDetailListDB(event, row) {\n    if (!row) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产报工明细\");\n        return false;\n    }\n    function valueAtPath(source, path) {\n        if (!source) { return null; }\n        if (Object.prototype.hasOwnProperty.call(source, path)) {\n            return source[path];\n        }\n        var value = source;\n        var parts = path.split(\".\");\n        for (var index = 0; index < parts.length; index += 1) {\n            if (value === null || value === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"headId.id\");\n    if (!recordId) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产报工明细\");\n        return false;\n    }\n    var target = \"/msService/WOM/outputMaterial/outputMaterial/outputView\"\n        + \"?viewCode=WOM_1.0.0_outputMaterial_outputDetailList\"\n        + \"&entityCode=WOM_1.0.0_outputMaterial\"\n        + \"&iscrosscompany=false\"\n        + \"&openType=frame\"\n        + \"&iscallback=false\"\n        + \"&id=\" + encodeURIComponent(recordId);\n    window.open(target, \"_blank\");\n    return true;\n}","isdbcustom":true,"modelCode":"WOM_1.0.0_outputMaterial_OutMateDetail","downloadXls":"/msService/WOM/outputMaterial/outMateDetail/downloadXls","selectFirstRow":false,"renderOver":"//生产报工明细列表\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].prodctId != null && data[i].prodctId.id != null) {\n            materialId.push({ \"materialId\": data[i].prodctId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","buttons":[{"id":"viewDetail","showname":"查看报工单","name":"查看报工单","namekey":"查看报工单","i18nKey":"查看报工单","buttonstyle":"view","operatetype":"CUSTOM","operateType":"CUSTOM","isHide":false,"ispermission":false,"isPublished":true,"iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"regionType":"BUTTON","cellCode":"cell_adp_WOM_1_0_0_outputMaterial_outputDetailList_viewDetail_view","buttonoperationcode":"WOM_1.0.0_outputMaterial_outputDetailList_viewDetail_view","CODE":"WOM_1.0.0_outputMaterial_outputDetailList_viewDetail_view","NAME":"查看报工单","ICONCLS":"cui-btn-view","USEINMORE":false,"SEPARATENUM":"0","ecEnv":"product","modelCode":"WOM_1.0.0_outputMaterial_OutMateDetail","viewselect":{"title":"WOM.viewtitle.randon1575884168869","code":"WOM_1.0.0_outputMaterial_outputView","name":"outputView","openType":"frame","url":"/msService/WOM/outputMaterial/outputMaterial/outputView","iscrosscompany":"false","mneType":"other"},"funcname":"onclick=''viewWomOutputDetailList()''","onclick":"viewWomOutputDetailList()","ONCLICK":"viewWomOutputDetailList()","funcbody":"function viewWomOutputDetailList() {\n    var gridFactory = ReactAPI.getComponentAPI(\"SupDataGrid\");\n    var grid = gridFactory && gridFactory.APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\");\n    var selected = grid && grid.getSelecteds ? grid.getSelecteds() : [];\n    if (!selected || !selected.length) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产报工明细\");\n        return false;\n    }\n    var row = selected[0];\n    function valueAtPath(source, path) {\n        if (!source) { return null; }\n        if (Object.prototype.hasOwnProperty.call(source, path)) {\n            return source[path];\n        }\n        var value = source;\n        var parts = path.split(\".\");\n        for (var index = 0; index < parts.length; index += 1) {\n            if (value === null || value === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"headId.id\");\n    if (!recordId) {\n    