 0) {\n\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''ec.common.checkselected''));\n\t\t\treturn false;\n\t}\n\t// 选中行\n\tlet selRow = selRows[0];\n\tvar bomId = selRow.id;\n\tvar productId = selRow.productId.id;\n\tvar bomCode = selRow.bomCode;\n\tvar bomEdition = selRow.bomEdtion;\n\n\tvar url = \"/msService/RM/formulaBOM/formulaBomMain/formulaBomCopyEdit?productId.id=\" + productId + \"&bomCode=\" + bomCode + \"&bomEdition=\" + bomEdition;\n\tReactAPI.createDialog(\"newDialog\", {\n\t\t\ttitle: ReactAPI.international.getText(''RM.viewtitle.randon1573904133909''),\n\t\t\tsize: 2,\n\t\t\turl: url,\n\t\t\tisRef: false,//是否开启参照\n\t\t\tbuttons: [\n\t\t\t\t\t{\n\t\t\t\t\t\t\ttext: ReactAPI.international.getText(''Button.text.save''),\n\t\t\t\t\t\t\ttype: \"primary\",\n\t\t\t\t\t\t\t// style: { color: \"#fff\", background: \"#ff0000\" },\n\t\t\t\t\t\t\tonClick: function (event) {\n\t\t\t\t\t\t\t\t\tvar bomCode = event.ReactAPI.getComponentAPI(\"Input\").APIs(\"formulaBomMain.bomCode\").getValue();\n\t\t\t\t\t\t\t\t\tvar bomEdition = event.ReactAPI.getComponentAPI(\"Input\").APIs(\"formulaBomMain.bomEdtion\").getValue();\n\t\t\t\t\t\t\t\t\t//复制BOM Ajax\n\t\t\t\t\t\t\t\t\t$.ajax({\n\t\t\t\t\t\t\t\t\t\t\turl: \"/msService/RM/formulaBOM/formulaBomMain/copyBom\",\n\t\t\t\t\t\t\t\t\t\t\ttype: ''post'',\n\t\t\t\t\t\t\t\t\t\t\tasync: false,\n\t\t\t\t\t\t\t\t\t\t\tdata: { bomId: bomId, bomCode: bomCode, bomEdition: bomEdition },\n\t\t\t\t\t\t\t\t\t\t\tsuccess: function (res) {\n\t\t\t\t\t\t\t\t\t\t\t\t\tconsole.log(res);\n\t\t\t\t\t\t\t\t\t\t\t\t\tif (res.code==200) {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tif (res.data.dealSuccessFlag) {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tReactAPI.destroyDialog(\"newDialog\");\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t$(\"button[data-id = ''query'']\").click(); //查询刷新PT；\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t//报错提示信息\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.data.message);\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.msg);\n\t\t\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t});\n\n\t\t\t\t\t\t\t}\n\t\t\t\t\t},\n\t\t\t\t\t{\n\t\t\t\t\t\t\ttext: ReactAPI.international.getText(''Button.text.cancel''),\n\t\t\t\t\t\t\tonClick: event => {\n\t\t\t\t\t\t\t\t\tReactAPI.destroyDialog(\"newDialog\");\n\t\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t]\n\t});\n}","funcname":"onclick=''bomCopy()''","buttonstyle":"modify","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1573461132230_1527","buttonoperationcode":"formulaBomList_copy_modify_RM_1.0.0_formulaBOM_formulaBomList","isHide":false,"showname":"复制","ecEnv":"product","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYUJPTV9mb3JtdWxhQm9tTGlzdF9zZWxmfA__","regionType":"BUTTON","iscallback":false,"modelCode":"RM_1.0.0_formulaBOM_FormulaBomMain","namekey":"RM.buttonPropertyshowName.randon1573461141923.flag","funcbody_es5":"function bomCopy() {\n\t\tvar dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomList_formulaBomMain_sdg\");\n\t\tvar selRows = dataGrid.getSelecteds();\n\t\tif (selRows.length == 0) {\n\t\t\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''ec.common.checkselected''));\n\t\t\t\treturn false;\n\t\t}\n\t\t// 选中行\n\t\tvar selRow = selRows[0];\n\t\tvar bomId = selRow.id;\n\t\tvar productId = selRow.productId.id;\n\t\tvar bomCode = selRow.bomCode;\n\t\tvar bomEdition = selRow.bomEdtion;\n\n\t\tvar url = \"/msService/RM/formulaBOM/formulaBomMain/formulaBomCopyEdit?productId.id=\" + productId + \"&bomCode=\" + bomCode + \"&bomEdition=\" + bomEdition;\n\t\tReactAPI.createDialog(\"newDialog\", {\n\t\t\t\ttitle: ReactAPI.international.getText(''RM.viewtitle.randon1573904133909''),\n\t\t\t\tsize: 2,\n\t\t\t\turl: url,\n\t\t\t\tisRef: false, //是否开启参照\n\t\t\t\tbuttons: [{\n\t\t\t\t\t\ttext: ReactAPI.international.getText(