log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                } else if (res.data[_i] != null && res.data[_i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\").setDatagridCellAttr(_i, \"material.code\", { style: { color: \"#505050\" } });\n                    // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n                }\n            }\n        }\n    });\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-1","ratio_h":75,"layoutmethod":"container","ptRealTimeLoad":1,"isreadonly":0,"layno":2,"layoutname":"column-3","islefttopfixed":false,"nums":1}],"tabViewIndex":0,"isborder":0,"isrightbottomfixed":false,"type":"layout","isreadonlyBak":0,"ptRealTimeLoad":1,"layoutmethod":"column","namekey":"ec.view.commoninfo","name":"常规信息","isreadonly":0,"layno":1,"id":null,"tabCode":"tab_0","layoutname":"tabs-1","nums":2,"islefttopfixed":false}],"layoutmethod":"tab","type":"layout"}],"layoutmethod":"column","type":"layout"}],"enableSimpleDealInfo":false,"title":"RM.viewtitle.randon1573460181835","url":"/msService/RM/formulaBOM/formulaBomMain/formulaBomEdit","dealInfoShow":false,"hasAttachment":true,"pageType":"EDIT","dealInfoGroup":"byTime","refCopy":{"isReference":false},"colNum":4,"layoutType":"classic","selfAdaption":false,"events":[{"function":"//批控地址\nlet batchServerId = ReactAPI.getComponentAPI(\"Reference\").APIs(''formulaBomMain.batchServerId.code'');\n\n//表体\nlet dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\");\nlet data = dataGrid.getDatagridData();\nif (!data.length) {\n    ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"RM.custom.randon1577173722465\"));\n    return false;\n}\nlet errorMessage = '''';\nlet set = new Set();\nfor (let item of data) {\n    let material = item.material;\n    if (!material) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1578034607122\", item.rowIndex + 1) + ''<br>'';\n        continue;\n    }\n    let materialCode = item.material.code;\n    let putOrder = item.putSort;\n    let key = putOrder ? materialCode + putOrder : materialCode;\n    if (set.has(key)) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587964682895\", item.rowIndex + 1);\n    } else {\n        set.add(key);\n    }\n\n    //如果批控地址有值，表体标识字段不能为空\n    if (batchServerId.getValue().length > 0 && (item.putSort == '''' || item.putSort == null)) {\n        errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587966610059\", item.rowIndex + 1);\n        //       ReactAPI.international.getText(\"EditView.notice.processing\")\n    }\n}\n\nif (errorMessage) {\n    ReactAPI.showMessage(\"f\", errorMessage);\n    return false;\n}","name":"onsave"},{"function":"// 当前表单的id存在且 [批控地址] 不为空时将 [批控地址] 置为只读\nvar formulaBomId = ReactAPI.getFormData().id;\nvar batchServerIds = ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').getValue();\nif (formulaBomId && batchServerIds.length) {\n    ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').setReadonly(true);\n}\n//判断表头的产品编码是否为危化品\nvar data = ReactAPI.getComponentAPI(\"Reference\").APIs(\"formulaBomMain.productId.code\").getValue();\n//let datarows = data.getSelecteds();\n// let materialCode=data[0].id;\nvar materialCode = void 0;\nif (data[0] != null && data[0].id != null) {\n    //有数据\n    materialCode = data[0].id;\n    ReactAPI.request({\n        type: \"get\",\n        ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttribute?materialCode=\" + materialCode,\n        contentType: \"application/json;charset=UTF-8\"\n    }, function (res) {\n        if (res.code == 200) {\n            if (res.data.materialAttr == true) {\n                //如果是危化品则为红色\n                document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#B30303\";\n            } else {\n                document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#505050\";\n            }\n        }\n    });\n}","name":"onload_es5"},{"function":"// 当前表单的id存在且 [批控地址] 不为空时将 [批控地址] 置为只读\nlet formulaBomId = ReactAPI.getFormData().id;\nlet batchServerIds = ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').getValue();\nif (formulaBomId && batchServerIds.length) {\n    ReactAPI.getComponentAPI(''Reference'').APIs(''formulaBomMain.batchServerId.code'').setReadonly(true);\n}\n//判断表头的产品编码是否为危化品\nlet data = ReactAPI.getComponentAPI(\"Reference\").APIs(\"formulaBomMain.productId.code\").getValue();\n//let datarows = data.getSelecteds();\n// let materialCode=data[0].id;\nlet materialCode;\nif (data[0] != null && data[0].id != null) {//有数据\n    materialCode = data[0].id;\n    ReactAPI.request({\n        type: \"get\",\n        ///RM/formulaBOM/formulaBomMain/GetMaterialAttribute\n        url: \"/msService/RM/formulaBOM/formulaBomMain/GetMaterialAttribute?materialCode=\" + materialCode,\n        contentType: \"application/json;charset=UTF-8\",\n    }, function (res) {\n        if (res.code==200) {\n            if (res.data.materialAttr == true) {//如果是危化品则为红色\n                document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#B30303\";\n            }\n            else {\n                document.getElementsByClassName(\"ant-input ant-select-search__field\")[0].style.color = \"#505050\";\n            }\n        }\n    }\n    );\n}","name":"onload"},{"function":"//批控地址\nvar batchServerId = ReactAPI.getComponentAPI(\"Reference\").APIs(''formulaBomMain.batchServerId.code'');\n\n//表体\nvar dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formulaBOM_formulaBomEditdg1573460506416\");\nvar data = dataGrid.getDatagridData();\nif (!data.length) {\n    ReactAPI.showMessage(\"f\", ReactAPI.international.getText(\"RM.custom.randon1577173722465\"));\n    return false;\n}\nvar errorMessage = '''';\nvar set = new Set();\nvar _iteratorNormalCompletion = true;\nvar _didIteratorError = false;\nvar _iteratorError = undefined;\n\ntry {\n    for (var _iterator = data[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n        var item = _step.value;\n\n        var material = item.material;\n        if (!material) {\n            errorMessage += ReactAPI.international.getText(\"RM.custom.randon1578034607122\", item.rowIndex + 1) + ''<br>'';\n            continue;\n        }\n        var materialCode = item.material.code;\n        var putOrder = item.putSort;\n        var key = putOrder ? materialCode + putOrder : materialCode;\n        if (set.has(key)) {\n            errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587964682895\", item.rowIndex + 1);\n        } else {\n            set.add(key);\n        }\n\n        //如果批控地址有值，表体标识字段不能为空\n        if (batchServerId.getValue().length > 0 && (item.putSort == '''' || item.putSort == null)) {\n            errorMessage += ReactAPI.international.getText(\"RM.custom.randon1587966610059\", item.rowIndex + 1);\n            //       ReactAPI.international.getText(\"EditView.notice.processing\")\n        }\n    }\n} catch (err) {\n    _didIteratorError = true;\n    _iteratorError = err;\n} finally {\n    try {\n        if (!_iteratorNormalCompletion && _iterator.return) {\n            _iterator.return();\n        }\n    } finally {\n        if (_didIteratorError) {\n            throw _iteratorError;\n        }\n    }\n}\n\nif (errorMessage) {\n    ReactAPI.showMessage(\"f\", errorMessage);\n    return false;\n}","name":"onsave_es5"}]}';
DECLARE runtime_extra_view_existing_oid oid;
DECLARE runtime_extra_view_target_oid oid;
BEGIN
    SELECT udt_name = 'oid' INTO runtime_extra_view_json_is_oid
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'runtime_extra_view'
      AND column_name = 'view_json';
    IF COALESCE(runtime_extra_view_json_is_oid, false) THEN
        SELECT view_json INTO runtime_extra_view_existing_oid
        FROM public.runtime_extra_view
        WHERE code = 'RM_1.0.0_formulaBOM_formulaBomEdit';
        IF runtime_extra_view_existing_oid IS NOT NULL THEN
            IF EXISTS (
                SELECT 1
                FROM pg_largeobject_metadata
                WHERE oid = runtime_extra_view_existing_oid
            ) THEN
                IF convert_from(lo_get(runtime_extra_view_existing_oid), 'UTF8') = runtime_extra_view_payload THEN
                    runtime_extra_view_target_oid := runtime_extra_view_existing_oid;
                END IF;
            END IF;
        END IF;
        IF runtime_extra_view_target_oid IS NULL THEN
            runtime_extra_view_target_oid := lo_from_bytea(0, convert_to(runtime_extra_view_payload, 'UTF8'));
        END IF;
        INSERT INTO public.runtime_extra_view (code, ec_env, version, view_code, view_json, proj_flag)
        VALUES ('RM_1.0.0_formulaBOM_formulaBomEdit', 'product', 0, 'RM_1.0.0_formulaBOM_formulaBomEdit', runtime_extra_view_target_oid, false)
        ON CONFLICT (code) DO UPDATE SET
            ec_env = COALESCE(EXCLUDED.ec_env, public.runtime_extra_view.ec_env),
            version = GREATEST(COALESCE(public.runtime_extra_view.version, 0), EXCLUDED.version),
            view_code = EXCLUDED.view_code,
            view_json = EXCLUDED.view_json,
            proj_flag = COALESCE(public.runtime_extra_view.proj_flag, EXCLUDED.proj_flag);
    ELSE
        INSERT INTO public.runtime_extra_view (code, ec_env, version, view_code, view_json, proj_flag)
        VALUES ('RM_1.0.0_formulaBOM_formulaBomEdit', 'product', 0, 'RM_1.0.0_formulaBOM_formulaBomEdit', runtime_extra_view_payload, false)
        ON CONFLICT (code) DO UPDATE SET
            ec_env = COALESCE(EXCLUDED.ec_env, public.runtime_extra_view.ec_env),
            version = GREATEST(COALESCE(public.runtime_extra_view.version, 0), EXCLUDED.version),
            view_code = EXCLUDED.view_code,
            view_json = EXCLUDED.view_json,
            proj_flag = COALESCE(public.runtime_extra_view.proj_flag, EXCLUDED.proj_flag);
    END IF;
END $$;
