eds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行\n    let formula = selecteds[0];\n    if (formula.state.id !== \"RM_state/enabled\") {\n        // 如果配方不是启用状态\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.random1643017683156''));\n        return;\n    }\n    if (formula.status == 99) {\n        // 设置配方为默认配方\n        ReactAPI.request(\n            {\n                type: \"post\",\n                url: \"/msService/RM/formula/formula/setFormulaDefault/\" + formula.id + \"?isDefault=\" + !formula.isDafault,\n            },\n            res => {\n                if (res.code == 200) {\n                    let data = res.data;\n                    if (data.dealSuccessFlag) {\n                        // 处理成功！\n                        ReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n                        // 刷新列表\n                        let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n                        let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n                        let url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n                        ReactAPI.getComponentAPI(\"SupDataGrid\")\n                            .APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\")\n                            .refreshDataByRequst({\n                                type: \"POST\",\n                                url: url,\n                                param: {\n                                    classifyCodes: \",\",\n                                    customCondition: {},\n                                    pageNo: currentPage,\n                                    paging: true,\n                                    pageSize: pageSize,\n                                },\n                            });\n                    } else {\n                        ReactAPI.showMessage(\"f\", data.errorMessage);\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", res.message);\n                }\n            }\n        );\n    } else {\n        //配方生效后才可以设置默认\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1577945423614''));\n        return;\n    }\n\n}","funcbody_es5":"function defaultEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_craftFormulaList_formula_sdg'');\n    var selecteds = dataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return;\n    }\n    if (selecteds.length > 1) {\n        // 如果选中了多个节点，则报“只允许对一行进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n        return;\n    }\n    // 选中行\n    var formula = selecteds[0];\n    if (formula.state.id !== \"RM_state/enabled\") {\n        // 如果配方不是启用状态\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.random1643017683156''));\n        return;\n    }\n    if (formula.status == 99) {\n        // 设置配方为默认配方\n        ReactAPI.request({\n            type: \"post\",\n            url: \"/msService/RM/formula/formula/setFormulaDefault/\" + formula.id + \"?isDefault=\" + !formula.isDafault\n        }, function (res) {\n            if (res.code == 200) {\n                var data = res.data;\n              