VALUES ('RM_1.0.0_formula_craftFormulaList', 'product', 0, 'RM_1.0.0_formula_craftFormulaList', '{"pageType":"LIST","title":"RM.viewtitle.randon1628126892947","url":"/msService/RM/formula/formula/craftFormulaList","isMain":true,"hasAttachment":false,"onlyForQuery":false,"components":[{"type":"layout","layoutmethod":"column","components":[{"type":"layoutSearchWidget","code":"query","layoutName":"layoutSearchWidget","layoutmethod":"container","fix_h":150,"fastProperty":[],"advProperty":[]},{"type":"layoutDatagrid","layoutmethod":"container","ratio_h":100,"DataGridCode":"RM_1.0.0_formula_craftFormulaList","modelCode":"RM_1.0.0_formula_Formula","hasFastQuery":true,"mainDisplayName":"tableNo","idPrefix":"compat_RM_1.0.0_formula_craftFormulaList","listPT":false,"buttons":[{"id":"copy","showname":"复制","namekey":"复制","buttonstyle":"add","operatetype":"CUSTOM","isHide":false,"ispermission":false,"isPublished":false,"buttonoperationcode":"craftFormulaList_copy_add_RM_1.0.0_formula_craftFormulaList","funcname":"onclick=''copyEvent(event)''","funcbody":"function copyEvent(event) {\n\tlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_craftFormulaList_formula_sdg'');\n\tlet selecteds = dataGrid.getSelecteds();\n\tif (!selecteds.length) {\n\t\t// 如果没有选节点，则报“请选择一条记录进行操作”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n\t\treturn;\n\t}\n\tif (selecteds.length > 1) {\n\t\t// 如果选中了多个节点，则报“只允许对一行进行操作！”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n\t\treturn;\n\t}\n\t// 选中行配方\n\tlet formula = selecteds[0];\n\t// 对话框名称\n\tlet dialogName = ''copyFormula'';\n\t// 打开工序编辑对话框\n\tReactAPI.createDialog(dialogName, {\n\t\ttitle: ReactAPI.international.getText(''RM.viewtitle.randon1574822696971''),\n\t\turl: \"/msService/RM/formula/formula/copyFormulaEdit?id=\" + formula.id,\n\t\tsize: 1,\n\t\tisRef: false, // 是否开启参照\n\t\tbuttons: [{\n\t\t\ttext: ReactAPI.international.getText(''Button.text.save''),\n\t\t\ttype: \"primary\",\n\t\t\tonClick: event => {\n\t\t\t\t//保存按钮禁用\n\t\t\t\tsetBtnStyle(''buttons_0'',false);\n\t\t\t\tdebugger;\n\t\t\t\t\tconsole.log(1);\n\t\t\t\tlet inputComponent = event.ReactAPI.getComponentAPI(''Input'');\n\t\t\t\t// 配方编码输入框\n\t\t\t\tlet formulaCodeComponent = inputComponent.APIs(''formula.formualCode'');\n\t\t\t\t// 配方标识输入框\n\t\t\t\tlet formulaNameComponent = inputComponent.APIs(''formula.formulaName'');\n\t\t\t\t// 配方版本输入框\n\t\t\t\tlet formulaEdtionComponent = inputComponent.APIs(''formula.formulaEdtion'');\n\t\t\t\t// 清除上一次校验\n\t\t\t\tformulaNameComponent.setValidateStyle(''success'');\n\t\t\t\tformulaEdtionComponent.setValidateStyle(''success'');\n\t\t\t\t// 数据校验\n\t\t\t\tlet isError = false;\n\t\t\t\tif (!formulaNameComponent.getValue()) {\n\t\t\t\t\tformulaNameComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaNameNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t}\n\t\t\t\tif (!formulaEdtionComponent.getValue()) {\n\t\t\t\t\tformulaEdtionComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaEdtionNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t}\n\t\t\t\tif (!isError) {\n\t\t\t\t\tconsole.log(1);\n\t\t\t\t\t// 开启遮罩\n\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n\t\t\t\t\tconsole.log(2);\n\t\t\t\t\t// 如果配方编码为空，通过“配方标识_配方版本”回填\n\t\t\t\t\tif (!formulaCodeComponent.getValue()) {\n\t\t\t\t\t\tformulaCodeComponent.setValue(formulaNameComponent.getValue() + \"_\" + formulaEdtionComponent.getValue());\n\t\t\t\t\t}\n\t\t\t\t\t// 请求参数\n\t\t\t\t\tlet data = {\n\t\t\t\t\t\tid: event.ReactAPI.getFormData().id,\n\t\t\t\t\t\tformualCode: formulaCodeComponent.getValue(),\n\t\t\t\t\t\tformulaName: formulaNameComponent.getValue(),\n\t\t\t\t\t\tformulaEdtion: formulaEdtionComponent.getValue()\n\t\t\t\t\t};\n\t\t\t\t\t// 调用复制配方接口\n\t\t\t\t\tReactAPI.request({\n\t\t\t\t\t\ttype: \"post\",\n\t\t\t\t\t\turl: \"/msService/RM/formula/formula/copyFormula\",\n\t\t\t\t\t\tdata: data\n\t\t\t\t\t},\n\t\t\t\t\tres => {\n\t\t\t\t\t\t// 关闭遮罩\n\t\t\t\t\t\tevent.ReactAPI.closeLoading();\n\t\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\t\tsetBtnStyle(''buttons_0'',true);\n\t\t\t\t\t\tif (res.code==200) {\n\t\t\t\t\t\t\tlet data = res.data;\n\t\t\t\t\t\t\tif (data.dealSuccessFlag) {\n\t\t\t\t\t\t\t\t// 关闭窗口\n\t\t\t\t\t\t\t\tReactAPI.destroyDialog(dialogName);\n\t\t\t\t\t\t\t\t// 刷新列表\n\t\t\t\t\t\t\t\tlet currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n\t\t\t\t\t\t\t\tlet pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n\t\t\t\t\t\t\t\tlet url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n\t\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").refreshDataByRequst({\n\t\t\t\t\t\t\t\t\ttype: \"POST\",\n\t\t\t\t\t\t\t\t\turl: url,\n\t\t\t\t\t\t\t\t\tparam: {\n\t\t\t\t\t\t\t\t\t\tclassifyCodes: \",\",\n\t\t\t\t\t\t\t\t\t\tcustomCondition: {},\n\t\t\t\t\t\t\t\t\t\tpageNo: currentPage,\n\t\t\t\t\t\t\t\t\t\tpaging: true,\n\t\t\t\t\t\t\t\t\t\tpageSize: pageSize,\n\t\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\t});\n\t\t\t\t\t\t\t\t// 处理成功！\n\t\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", data.errorMessage);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message);\n\t\t\t\t\t\t}\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t}\n\t\t},\n\t\t{\n\t\t\ttext: ReactAPI.international.getText(''Button.text.cancel''),\n\t\t\tonClick: event => {\n\t\t\t\tReactAPI.destroyDialog(dialogName);\n\t\t\t}\n\t\t}]\n\t});\n}","funcbody_es5":"function copyEvent(event) {\n\tvar dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_craftFormulaList_formula_sdg'');\n\tvar selecteds = dataGrid.getSelecteds();\n\tif (!selecteds.length) {\n\t\t// 如果没有选节点，则报“请选择一条记录进行操作”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n\t\treturn;\n\t}\n\tif (selecteds.length > 1) {\n\t\t// 如果选中了多个节点，则报“只允许对一行进行操作！”\n\t\tReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.onceOnlyOneRow''));\n\t\treturn;\n\t}\n\t// 选中行配方\n\tvar formula = selecteds[0];\n\t// 对话框名称\n\tvar dialogName = ''copyFormula'';\n\t// 打开工序编辑对话框\n\tReactAPI.createDialog(dialogName, {\n\t\ttitle: ReactAPI.international.getText(''RM.viewtitle.randon1574822696971''),\n\t\turl: \"/msService/RM/formula/formula/copyFormulaEdit?id=\" + formula.id,\n\t\tsize: 1,\n\t\tisRef: false, // 是否开启参照\n\t\tbuttons: [{\n\t\t\ttext: ReactAPI.international.getText(''Button.text.save''),\n\t\t\ttype: \"primary\",\n\t\t\tonClick: function onClick(event) {\n\t\t\t\t//保存按钮禁用\n\t\t\t\tsetBtnStyle(''buttons_0'', false);\n\t\t\t\tdebugger;\n\t\t\t\tconsole.log(1);\n\t\t\t\tvar inputComponent = event.ReactAPI.getComponentAPI(''Input'');\n\t\t\t\t// 配方编码输入框\n\t\t\t\tvar formulaCodeComponent = inputComponent.APIs(''formula.formualCode'');\n\t\t\t\t// 配方标识输入框\n\t\t\t\tvar formulaNameComponent = inputComponent.APIs(''formula.formulaName'');\n\t\t\t\t// 配方版本输入框\n\t\t\t\tvar formulaEdtionComponent = inputComponent.APIs(''formula.formulaEdtion'');\n\t\t\t\t// 清除上一次校验\n\t\t\t\tformulaNameComponent.setValidateStyle(''success'');\n\t\t\t\tformulaEdtionComponent.setValidateStyle(''success'');\n\t\t\t\t// 数据校验\n\t\t\t\tvar isError = false;\n\t\t\t\tif (!formulaNameComponent.getValue()) {\n\t\t\t\t\tformulaNameComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaNameNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'', true);\n\t\t\t\t}\n\t\t\t\tif (!formulaEdtionComponent.getValue()) {\n\t\t\t\t\tformulaEdtionComponent.setValidateStyle(''error'', event.ReactAPI.international.getText(''RM.custom.formulaEdtionNotNull''));\n\t\t\t\t\tisError = true;\n\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\tsetBtnStyle(''buttons_0'', true);\n\t\t\t\t}\n\t\t\t\tif (!isError) {\n\t\t\t\t\tconsole.log(1);\n\t\t\t\t\t// 开启遮罩\n\t\t\t\t\tevent.ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n\t\t\t\t\tconsole.log(2);\n\t\t\t\t\t// 如果配方编码为空，通过“配方标识_配方版本”回填\n\t\t\t\t\tif (!formulaCodeComponent.getValue()) {\n\t\t\t\t\t\tformulaCodeComponent.setValue(formulaNameComponent.getValue() + \"_\" + formulaEdtionComponent.getValue());\n\t\t\t\t\t}\n\t\t\t\t\t// 请求参数\n\t\t\t\t\tvar data = {\n\t\t\t\t\t\tid: event.ReactAPI.getFormData().id,\n\t\t\t\t\t\tformualCode: formulaCodeComponent.getValue(),\n\t\t\t\t\t\tformulaName: formulaNameComponent.getValue(),\n\t\t\t\t\t\tformulaEdtion: formulaEdtionComponent.getValue()\n\t\t\t\t\t};\n\t\t\t\t\t// 调用复制配方接口\n\t\t\t\t\tReactAPI.request({\n\t\t\t\t\t\ttype: \"post\",\n\t\t\t\t\t\turl: \"/msService/RM/formula/formula/copyFormula\",\n\t\t\t\t\t\tdata: data\n\t\t\t\t\t}, function (res) {\n\t\t\t\t\t\t// 关闭遮罩\n\t\t\t\t\t\tevent.ReactAPI.closeLoading();\n\t\t\t\t\t\t// 保存按钮可用\n\t\t\t\t\t\tsetBtnStyle(''buttons_0'', true);\n\t\t\t\t\t\tif (res.code == 200) {\n\t\t\t\t\t\t\tvar _data = res.data;\n\t\t\t\t\t\t\tif (_data.dealSuccessFlag) {\n\t\t\t\t\t\t\t\t// 关闭窗口\n\t\t\t\t\t\t\t\tReactAPI.destroyDialog(dialogName);\n\t\t\t\t\t\t\t\t// 刷新列表\n\t\t\t\t\t\t\t\tvar currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n\t\t\t\t\t\t\t\tvar pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n\t\t\t\t\t\t\t\tvar url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n\t\t\t\t\t\t\t\tReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").refreshDataByRequst({\n\t\t\t\t\t\t\t\t\ttype: \"POST\",\n\t\t\t\t\t\t\t\t\turl: url,\n\t\t\t\t\t\t\t\t\tparam: {\n\t\t\t\t\t\t\t\t\t\tclassifyCodes: \",\",\n\t\t\t\t\t\t\t\t\t\tcustomCondition: {},\n\t\t\t\t\t\t\t\t\t\tpageNo: currentPage,\n\t\t\t\t\t\t\t\t\t\tpaging: true,\n\t\t\t\t\t\t\t\t\t\tpageSize: pageSize\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t});\n\t\t\t\t\t\t\t\t// 处理成功！\n\t\t\t\t\t\t\t\tReactAPI.showMessage(\"s\", ReactAPI.international.getText(''RM.custom.dealSuccess''));\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", _data.errorMessage);\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\tReactAPI.showMessage(\"f\", res.message);\n\t\t\t\t\t\t}\n\t\t\t\t\t});\n\t\t\t\t}\n\t\t\t}\n\t\t}, {\n\t\t\ttext: ReactAPI.international.getText(''Button.text.cancel''),\n\t\t\tonClick: function onClick(event) {\n\t\t\t\tReactAPI.destroyDialog(dialogName);\n\t\t\t}\n\t\t}]\n\t});\n}","iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"cellCode":"cell_1628127233860_1","ecEnv":"product","regionType":"BUTTON","i18nKey":"RM.buttonPropertyshowName.randon1573641135490.flag","name":"复制","operateType":"CUSTOM","onclick":"copyEvent(event)","ONCLICK":"copyEvent(event)","CODE":"craftFormulaList_copy_add_RM_1.0.0_formula_craftFormulaList","NAME":"复制","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"id":"start","showname":"启用","namekey":"启用","buttonstyle":"add","operatetype":"CUSTOM","isHide":false,"ispermission":false,"isPublished":false,"buttonoperationcode":"craftFormulaList_start_add_RM_1.0.0_formula_craftFormulaList","funcname":"onclick=''startEvent(event)''","funcbody":"function startEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\");\n    var selecteds = dataGrid.getSelecteds();\n    if (selecteds.length == 0) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return false;\n    }\n    var ids = '''';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getSelecteds()[i];\n        var status = row.status\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574755044078''));\n            return false;\n        } else if (row.state && row.state.id == ''RM_state/enabled'') {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759597334''));\n            return false;\n        } else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: {\n            state: \"RM_state/enabled\",\n            ids: ids\n        },\n        success: function (res) {\n            //启用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.enable.success\"));\n\n            // 查询刷新PT\n            let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n            let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n            let url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\")\n                .refreshDataByRequst({\n                    type: \"POST\",\n                    url: url,\n                    param: {\n                        classifyCodes: \",\",\n                        customCondition: {},\n                        pageNo: currentPage,\n                        paging: true,\n                        pageSize: pageSize,\n                    },\n                });\n            return;\n        }\n    });\n}","funcbody_es5":"function startEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\");\n    var selecteds = dataGrid.getSelecteds();\n    if (selecteds.length == 0) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return false;\n    }\n    var ids = '''';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getSelecteds()[i];\n        var status = row.status;\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574755044078''));\n            return false;\n        } else if (row.state && row.state.id == ''RM_state/enabled'') {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759597334''));\n            return false;\n        } else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: {\n            state: \"RM_state/enabled\",\n            ids: ids\n        },\n        success: function success(res) {\n            //启用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.enable.success\"));\n\n            // 查询刷新PT\n            var currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n            var pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n            var url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").refreshDataByRequst({\n                type: \"POST\",\n                url: url,\n                param: {\n                    classifyCodes: \",\",\n                    customCondition: {},\n                    pageNo: currentPage,\n                    paging: true,\n                    pageSize: pageSize\n                }\n            });\n            return;\n        }\n    });\n}","iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"cellCode":"cell_1628127233860_2","ecEnv":"product","regionType":"BUTTON","i18nKey":"RM.buttonPropertyshowName.randon1573641222060.flag","name":"启用","operateType":"CUSTOM","onclick":"startEvent(event)","ONCLICK":"startEvent(event)","CODE":"craftFormulaList_start_add_RM_1.0.0_formula_craftFormulaList","NAME":"启用","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"id":"end","showname":"停用","namekey":"停用","buttonstyle":"add","operatetype":"CUSTOM","isHide":false,"ispermission":false,"isPublished":false,"buttonoperationcode":"craftFormulaList_end_add_RM_1.0.0_formula_craftFormulaList","funcname":"onclick=''endEvent(event)''","funcbody":"function endEvent(event) {\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\");\n    var selecteds = dataGrid.getSelecteds();\n    if (selecteds.length == 0) {\n        // 如果没有选节点，则报“请选择一条记录进行操作”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''RM.custom.randon1573717880503''));\n        return false;\n    }\n\n    var ids = '''';\n    for (var i = 0; i < selecteds.length; i++) {\n        var row = dataGrid.getSelecteds()[i];\n        var status = row.status\n        if (status == 88) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624507911528''));\n            return false;\n        } else if (row.state == null ||　(row.state != null && row.state.id == ''RM_state/notEnabled'') ) {\n\t\t\t//配方未启用，不能停用！\n\t\t\tReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1624932897664''));\n            return false; \n\t\t} else if (!row.state || row.state.id == ''RM_state/disabled'') {\n\t\t\t//存在单据已停用，不能重复停用！\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''RM.custom.randon1574759822999''));\n            return false;\n        }else {\n            ids += '','' + row.id;\n        }\n    }\n    if (ids != '''') {\n        ids = ids.substr(1);\n    }\n    $.ajax({\n        url: \"/msService/RM/formula/formula/updateFomulaState\",\n        type: ''post'',\n        async: false,\n        data: {\n            state: \"RM_state/disabled\",\n            ids: ids\n        },\n        success: function (res) {\n            //停用成功\n            ReactAPI.showMessage(\"s\", ReactAPI.international.getText(\"foundation.language.disable.success\"));\n\n            // 查询刷新PT\n            let currentPage = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().currentPage;\n            let pageSize = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\").getTablePagination().pageSize;\n            let url = \"/msService/RM/formula/formula/craftFormulaList-query\";\n            ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"RM_1.0.0_formula_craftFormulaList_formula_sdg\")\n                .refreshDataByRequst({\n                    type: \"POST\",\