 _iterator.next()).done); _iteratorNormalCompletion = true) {\n                        var eachData = _step.value;\n\n                        if (eachData.lineId.id == data[0].id) {\n                            ReactAPI.showMessage(\"w\", \"此生产线已添加，请勿重复添加!\");\n                            return;\n                        }\n                    }\n                } catch (err) {\n                    _didIteratorError = true;\n                    _iteratorError = err;\n                } finally {\n                    try {\n                        if (!_iteratorNormalCompletion && _iterator.return) {\n                            _iterator.return();\n                        }\n                    } finally {\n                        if (_didIteratorError) {\n                            throw _iteratorError;\n                        }\n                    }\n                }\n            }\n            // 已在产线列表产线id\n            var nodes = dataGrid.getDatagridData().map(function (node) {\n                return node.lineId.id;\n            });\n            // 从选择结果中去除已存在的产线\n            var newNodes = data.filter(function (node) {\n                return nodes.indexOf(node.id) == -1;\n            });\n            // 配方的报工模式\n            var formulaReportType = ReactAPI.getComponentAPI(''SystemCode'').APIs(''formula.reportType'').getValue();\n            var reportType = formulaReportType ? {\n                id: formulaReportType.value,\n                value: formulaReportType.label\n            } : {\n                id: null,\n                value: null\n            };\n            // 将新选择的结果插入产线表中\n            var _iteratorNormalCompletion2 = true;\n            var _didIteratorError2 = false;\n            var _iteratorError2 = undefined;\n\n            try {\n                for (var _iterator2 = newNodes[Symbol.iterator](), _step2; !(_iteratorNormalCompletion2 = (_step2 = _iterator2.next()).done); _iteratorNormalCompletion2 = true) {\n                    var node = _step2.value;\n\n                    // 增行\n                    var newLine = dataGrid.addLine();\n                    // 工序单元多选初始值\n                    var processUnitCache = sessionStorage.getItem(''formula_'' + ReactAPI.getFormData().id + ''_processUnitCache'');\n                    // 设置节点\n                    dataGrid.setRowData(newLine.rowIndex, {\n                        lineId: node,\n                        processUnitCache: processUnitCache,\n                        // 适用产线带出配方的报工模式\n                        reportType: reportType\n                    });\n                }\n            } catch (err) {\n                _didIteratorError2 = true;\n                _iteratorError2 = err;\n            } finally {\n                try {\n                    if (!_iteratorNormalCompletion2 && _iterator2.return) {\n                        _iterator2.return();\n                    }\n                } finally {\n                    if (_didIteratorError2) {\n                        throw _iteratorError2;\n                    }\n                }\n            }\n\n            ReactAPI.showMessage(\"s\", \"添加成功！\");\n        } else {\n            //报错提示信息\n            ReactAPI.showMessage(\"f\", ''请至少选中一行'');\n        }\n    };\n}","id":"add","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"funcbody":"function deleteRowEvent(event) {\n    // 产线表\n    let lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n    // 工序工作单元多选表\n    let unitDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1575015376705'');\n    let selecteds = lineDataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return;\n    }\n    // 弹出确认框\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(''SupDatagrid.button.delete''),\n        onOk: () => {\n            let rowIndex = selecteds[0].rowIndex;\n            // 删除选中行\n            lineDataGrid.deleteLine(rowIndex.toString());\n            // 删除当前选中行缓存\n            let lastLineRowKey = ''formula_'' + ReactAPI.getFormData().id + ''_lastLineRow'';\n            sessionStorage.setItem(lastLineRowKey, '''');\n            // 清空工作单元表\n            unitDataGrid.deleteLine();\n            ReactAPI.closeConfirm();\n        }\n    });\n}","funcname":"onclick=''deleteRowEvent(event)''","buttonstyle":"del","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1574995249930_9562","isHide":false,"showname":"删行","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9hcnJTdWl0bGluZUVkaXRfc2VsZnw_","regionType":"BUTTON","iscallback":false,"namekey":"RM.buttonPropertyshowName.randon1574995258625.flag","funcbody_es5":"function deleteRowEvent(event) {\n    // 产线表\n    var lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n    // 工序工作单元多选表\n    var unitDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1575015376705'');\n    var selecteds = lineDataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return;\n    }\n    // 弹出确认框\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(''SupDatagrid.button.delete''),\n        onOk: function onOk() {\n            var rowIndex = selecteds[0].rowIndex;\n            // 删除选中行\n            lineDataGrid.deleteLine(rowIndex.toString());\n            // 删除当前选中行缓存\n            var lastLineRowKey = ''formula_'' + ReactAPI.getFormData().id + ''_lastLineRow'';\n            sessionStorage.setItem(lastLineRowKey, '''');\n            // 清空工作单元表\n            unitDataGrid.deleteLine();\n            ReactAPI.closeConfirm();\n        }\n    });\n}","id":"delete","operatetype":"CUSTOM","isconfirm":false}],"autoresize":false,"DataGridCode":"RM_1.0.0_formula_arrSuitlineEditdg1573709269826","listPT":false,"renderOver_es5":"console.log(''test2'');\n// 获取配方\nvar formula = ReactAPI.getFormData();\n// 产线表\nvar lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n// 获取工序单元初始化缓存数据\nvar processUnitCacheKey = ''formula_'' + formula.id + ''_processUnitCache'';\n// 创建缓存工作单元中初始化对应json\n// 获取配方工序\nReactAPI.request({\n    type: \"post\",\n    url: \"/msService/RM/formula/formula/data-dg1574325474841?datagridCode=RM_1.0.0_formula_commonFormulaViewdg1574325474841&id=\" + formula.id,\n    data: {\n        pageSize: 65535\n    },\n    async: false\n}, function (res) {\n    debugger;\n    var processes = res.data.result;\n    var processUnits = [];\n    var _iteratorNormalCompletion = true;\n    var _didIteratorError = false;\n    var _iteratorError = undefined;\n\n    try {\n        for (var _iterator = processes[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n            var process = _step.value;\n\n            var processUnit = {\n                processId: process\n            };\n            // 拼接缓存工作单元\n            processUnits.push(processUnit);\n        }\n    } catch (err) {\n        _didIteratorError = true;\n        _iteratorError = err;\n    } finally {\n        try {\n            if (!_iteratorNormalCompletion && _iterator.return) {\n                _iterator.return();\n            }\n        } finally {\n            if (_didIteratorError) {\n                throw _iteratorError;\n            }\n        }\n    }\n\n    var processUnitCache = JSON.stringify(processUnits);\n    // 将json存入缓存中\n    sessionStorage.setItem(processUnitCacheKey, processUnitCache);\n});\n\n// 在缓存中设置当前选中行\nvar lastLineRowKey = ''formula_'' + formula.id + ''_lastLineRow'';\nsessionStorage.setItem(lastLineRowKey, '''');\n\n// 添加产线表点击点击事件\nlineDataGrid.setClickEvt(function (event, selectData) {\n    debugger;\n    console.log(''test'');\n    // 产线表\n    var lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n    // 工序工作单元多选表\n    var unitDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1575015376705'');\n    // 获取上一次选择行\n    var lastLineRow = sessionStorage.getItem(lastLineRowKey);\n    if (lastLineRow) {\n        // 如果上一次选择行和这次选择行相同，则跳出方法\n        if (Number(lastLineRow) === selectData.rowIndex) {\n            return;\n        }\n        var units = unitDataGrid.getDatagridData();\n        // 将数据转换成json，存入产线表对应行中\n        lineDataGrid.setRowData(Number(lastLineRow), {\n            processUnitCache: JSON.stringify(units)\n        });\n    }\n    // 设置当前选中行\n    sessionStorage.setItem(lastLineRowKey, selectData.rowIndex);\n    // 显示工序-单元多表\n    // 获取缓存工作单元\n    var processUnitCache = lineDataGrid.getRows(selectData.rowIndex.toString())[0].processUnitCache;\n    var processUnits = null;\n    if (processUnitCache) {\n        // 如果有缓存\n        processUnits = JSON.parse(processUnitCache);\n    } else {\n        // 如果没缓存，设置工序单元多选初始值\n        processUnits = JSON.parse(sessionStorage.getItem(''formula_'' + ReactAPI.getFormData().id + ''_processUnitCache''));\n    }\n    // 清空表格原本数据\n    unitDataGrid.deleteLine();\n    var _iteratorNormalCompletion2 = true;\n    var _didIteratorError2 = false;\n    var _iteratorError2 = undefined;\n\n    try {\n        for (var _iterator2 = processUnits[Symbol.iterator](), _step2; !(_iteratorNormalCompletion2 = (_step2 = _iterator2.next()).done); _iteratorNormalCompletion2 = true) {\n            var processUnit = _step2.value;\n\n            // 新增行\n            var newLine = unitDataGrid.addLine();\n            // 将数据进行填入\n            unitDataGrid.setRowData(newLine.rowIndex, processUnit);\n        }\