e","readonly":false,"elalign":"left","convertPdfOnLine":true,"modelCode":"RM_1.0.0_formula_Formula","complex":false,"showType":"SELECTCOMP","isgroup":false,"isCreateNew":false,"officeNotNull":false,"mneenable":false,"fill":{"fillType":3,"fillName":"系统编码","fillContent":"RM_reportType","listType":"list"},"isOfficeSign":false,"columnType":"SYSTEMCODE","isTitle":true,"isrefselect":false,"name":"formula.reportType","isNoCopy":false,"maxLength":4000,"precisionHasChanged":true,"acceptRevisions":false,"code":"RM_1.0.0_formula_arrSuitlineEdit_EDIT_OTHER_RM_1.0.0_formula_Formula_reportType","multallowview":false,"hideRevision":false,"getRevisions":false,"allowview":false,"showRevision":false,"namekey":"RM.propertydisplayName.randon1573608591551","isreadonly":false,"officePrint":false,"key":"formula.reportType","downloadDoc":true,"showFormat":"SELECTCOMP","autoresize":false,"saveTemplate":false,"isCustom":false,"openEmptyDoc":true,"multable":false,"columnName":"REPORT_TYPE"}},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577265311471_812","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577265311471_4778","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577265311471_902","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577265311471_9585","type":"layoutCell"}],"regionType":"EDIT","colwidth":"13,20,13,20,13,20","cssstyle":"display:none;","customSection":null,"colNum":6,"name":null,"sectionCode":"section_1576738340628_5437","refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"section","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"column-4","ratio_h":15,"layoutmethod":"container","ptRealTimeLoad":1,"isreadonly":0,"layno":2,"layoutname":"tabs-1","islefttopfixed":false,"nums":1},{"isborder":0,"tabViewIndex":0,"components":[{"isborder":0,"components":[{"canInsertRow":false,"isSuperTable":false,"iscontrol":false,"nullable":false,"isTransverseShow":false,"isOfficeHandSign":false,"isRevision":false,"isFirstLoad":false,"type":"layoutDatagrid","isEditable":true,"readonly":0,"ptPageInit_es5":"// 如果是批控配方，隐藏产线操作按钮\nif (ReactAPI.getFormData().batchContral) {\n    $(''#btn-add'').hide();\n    $(''#btn-delete'').hide();\n}","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"RM_1.0.0_formula_LineFormula","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"console.log(''test2'')\n// 获取配方\nlet formula = ReactAPI.getFormData();\n// 产线表\nlet lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n// 获取工序单元初始化缓存数据\nlet processUnitCacheKey = ''formula_'' + formula.id + ''_processUnitCache'';\n// 创建缓存工作单元中初始化对应json\n// 获取配方工序\nReactAPI.request({\n    type: \"post\",\n    url: \"/msService/RM/formula/formula/data-dg1574325474841?datagridCode=RM_1.0.0_formula_commonFormulaViewdg1574325474841&id=\" + formula.id,\n    data: {\n        pageSize: 65535\n    },\n    async: false\n},\n    res => {\n        debugger;\n    let processes = res.data.result;\n    let processUnits = [];\n    for (let process of processes) {\n        let processUnit = {\n            processId: process\n        };\n        // 拼接缓存工作单元\n        processUnits.push(processUnit);\n    }\n    const processUnitCache = JSON.stringify(processUnits);\n    // 将json存入缓存中\n    sessionStorage.setItem(processUnitCacheKey, processUnitCache);\n});\n\n// 在缓存中设置当前选中行\nlet lastLineRowKey = ''formula_'' + formula.id + ''_lastLineRow'';\nsessionStorage.setItem(lastLineRowKey, '''');\n\n// 添加产线表点击点击事件\nlineDataGrid.setClickEvt((event, selectData) => {\n    debugger;\n    console.log(''test'')\n    // 产线表\n    let lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1573709269826'');\n    // 工序工作单元多选表\n    let unitDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_arrSuitlineEditdg1575015376705'');\n    // 获取上一次选择行\n    const lastLineRow = sessionStorage.getItem(lastLineRowKey);\n    if (lastLineRow) {\n        // 如果上一次选择行和这次选择行相同，则跳出方法\n        if (Number(lastLineRow) === selectData.rowIndex) {\n            return;\n        }\n        let units = unitDataGrid.getDatagridData();\n        // 将数据转换成json，存入产线表对应行中\n        lineDataGrid.setRowData(Number(lastLineRow), {\n            processUnitCache: JSON.stringify(units)\n        });\n    }\n    // 设置当前选中行\n    sessionStorage.setItem(lastLineRowKey, selectData.rowIndex);\n    // 显示工序-单元多表\n    // 获取缓存工作单元\n    let processUnitCache = lineDataGrid.getRows(selectData.rowIndex.toString())[0].processUnitCache;\n    let processUnits = null;\n    if (processUnitCache) {\n        // 如果有缓存\n        processUnits = JSON.parse(processUnitCache);\n    } else {\n        // 如果没缓存，设置工序单元多选初始值\n        processUnits = JSON.parse(sessionStorage.getItem(''formula_'' + ReactAPI.getFormData().id + ''_processUnitCache''));\n    }\n    // 清空表格原本数据\n    unitDataGrid.deleteLine();\n    for (let processUnit of processUnits) {\n        // 新增行\n        let newLine = unitDataGrid.addLine();\n        // 将数据进行填入\n        unitDataGrid.setRowData(newLine.rowIndex, processUnit);\n    }\n\n    /*\n\t * 获取产线下的工作单元组,工作单元id及产线\n\t * 上属工作区域下的直接工作单元组,工作单元id\n\t * by-hdj\n\t */\n\tlet productLineId = lineDataGrid.getSelecteds()[0].lineId.id;\n\t// 拼接缓存的key\n\twindow.key = \"_supcon::\" + productLineId;\n\tlet s = Symbol.for(window.key);\n\tif (!window[s]) {\n\t\tReactAPI.request({\n\t\t\ttype: \"get\",\n\t\t\tasync: false,\n\t\t\tdata: {},\n\t\t\turl: \"/msService/RM/formula/formula/unitGroupAndUnit/\" + productLineId\n\t\t}, function (res) {\n\t\t\tif (res.code==200) {\n\t\t\t\tlet r = res.data;\n\t\t\t\tif (r.success) {\n\t\t\t\t\twindow[s] = r.result.length ? r.result.join('','') : ''-1'';\n\t\t\t\t} else {\n\t\t\t\t\twindow[s] = \"-1\";\n\t\t\t\t\tReactAPI.showMessage(''f'', r.errMsg);\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\twindow[s] = \"-1\";\n\t\t\t\tReactAPI.showMessage(''f'', res.msg);\n\t\t\t}\n\t\t});\n\t}\n});","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1573709334068_4018","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1573709269826","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"RM_1.0.0_formula_arrSuitlineEditdg1573709269826_DATAGRID_OTHER_RM_1.0.0_formula_LineFormula_lineId_HierarchicalMod_1.0.0_factoryModel_FactoryModel_name","nullable":true,"isTotal":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","referenceview":{"code":"HierarchicalMod_1.0.0_factoryModel_factoryLineRef","iscrosscompany":"false","name":"factoryLineRef","title":"HierarchicalMod.viewtitle.randon1574995903161","mneType":"other","url":"/msService/HierarchicalMod/factoryModel/factoryModel/factoryLineRef","openType":"frame"},"propertyCode":"RM_1.0.0_formula_LineFormula_lineId||HierarchicalMod_1.0.0_factoryModel_FactoryModel_name","regionType":"DATAGRID","layRec":"HM_FACTORY_MODELS,ID,RM_LINE_FORMULAS,LINE_ID-name","modelCode":"HierarchicalMod_1.0.0_factoryModel_FactoryModel","namekey":"RM.202007231118001","isreadonly":true,"showType":"SELECTCOMP","isgroup":false,"key":"lineId.name","popView":false,"showFormat":"SELECTCOMP","cellCode":"cell_1573709360878_800","mneenable":false,"label":"节点名称","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc"