exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''formulaId.id'',''lineId.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function addEvent(event) {\n    // 产线表\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_easyArrSuitlineEditdg1575265759720'');\n    let dialogName = ''factoryLineRef'';\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(\"HierarchicalMod.viewdisplayName.randon1592376359794\"),\n        url: ''/msService/HierarchicalMod/factoryModel/factoryModel/factoryLineRef'',\n        isRef: true, // 是否开启参照\n        width: ''820px'',\n        height: ''550px'',\n        buttons: [\n            {\n                text: \"选择\",\n                type: \"primary\",\n                onClick: function (data, event) {\n                    callback(data, event);\n                    //ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"RM.custom.randon1584687807971\"));\n                }\n            },\n            {\n                text: \"关闭\",\n                type: \"cancel\",\n                onClick: function (event) {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ],\n        callback: (data, event) => {\n            callback(data, event);\n        },\n        onOk: (data, event) => {\n            callback(data, event);\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"RM.custom.randon1584687807971\"));\n        },\n        onCancel: (data, event) => {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n\n    var callback = (data, event) => {\n        if (!data.length) {\n            // 如果什么都没选，则不做任何处理\n            ReactAPI.showMessage(\"f\", \"请至少选中一行\");\n        }else{\n        // 已在产线列表产线id\n        let nodes = dataGrid.getDatagridData().map(node => node.lineId.id);\n        // 从选择结果中去除已存在的产线\n        let newNodes = data.filter(node => nodes.indexOf(node.id) == -1);\n        // 配方的报工模式\n        let formulaReportType = ReactAPI.getComponentAPI(''SystemCode'').APIs(''formula.reportType'').getValue();\n        let reportType = formulaReportType ? { id: formulaReportType.value, value: formulaReportType.label } : { id: null, value: null };\n        // 将新选择的结果插入产线表中\n        for (let node of newNodes) {\n            // 增行\n            let newLine = dataGrid.addLine();\n            // 设置节点\n            dataGrid.setRowData(newLine.rowIndex, {\n                lineId: node,\n                // 适用产线带出配方的报工模式\n                reportType: reportType\n            });\n        }\n\t\tReactAPI.showMessage(\"s\", \"添加成功！\");\n\t\t}\n    }\n}","funcname":"onclick=''addEvent(event)''","buttonstyle":"eighteen-dt-op-reference","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1575265759734_1","isHide":false,"showname":"参照生产线","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9lYXN5QXJyU3VpdGxpbmVFZGl0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"RM.buttonPropertyshowName.randon1575006997324.flag","funcbody_es5":"function addEvent(event) {\n    // 产线表\n    var dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_easyArrSuitlineEditdg1575265759720'');\n    var dialogName = ''factoryLineRef'';\n    ReactAPI.createDialog(dialogName, {\n        title: ReactAPI.international.getText(\"HierarchicalMod.viewdisplayName.randon1592376359794\"),\n        url: ''/msService/HierarchicalMod/factoryModel/factoryModel/factoryLineRef'',\n        isRef: true, // 是否开启参照\n        width: ''820px'',\n        height: ''550px'',\n        buttons: [{\n            text: \"选择\",\n            type: \"primary\",\n            onClick: function onClick(data, event) {\n                _callback(data, event);\n                //ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"RM.custom.randon1584687807971\"));\n            }\n        }, {\n            text: \"关闭\",\n            type: \"cancel\",\n            onClick: function onClick(event) {\n                ReactAPI.destroyDialog(dialogName);\n            }\n        }],\n        callback: function callback(data, event) {\n            _callback(data, event);\n        },\n        onOk: function onOk(data, event) {\n            _callback(data, event);\n            ReactAPI.showMessage(''s'', ReactAPI.international.getText(\"RM.custom.randon1584687807971\"));\n        },\n        onCancel: function onCancel(data, event) {\n            ReactAPI.destroyDialog(dialogName);\n        }\n    });\n\n    var _callback = function _callback(data, event) {\n        if (!data.length) {\n            // 如果什么都没选，则不做任何处理\n            ReactAPI.showMessage(\"f\", \"请至少选中一行\");\n        } else {\n            // 已在产线列表产线id\n            var nodes = dataGrid.getDatagridData().map(function (node) {\n                return node.lineId.id;\n            });\n            // 从选择结果中去除已存在的产线\n            var newNodes = data.filter(function (node) {\n                return nodes.indexOf(node.id) == -1;\n            });\n            // 配方的报工模式\n            var formulaReportType = ReactAPI.getComponentAPI(''SystemCode'').APIs(''formula.reportType'').getValue();\n            var reportType = formulaReportType ? { id: formulaReportType.value, value: formulaReportType.label } : { id: null, value: null };\n            // 将新选择的结果插入产线表中\n            var _iteratorNormalCompletion = true;\n            var _didIteratorError = false;\n            var _iteratorError = undefined;\n\n            try {\n                for (var _iterator = newNodes[Symbol.iterator](), _step; !(_iteratorNormalCompletion = (_step = _iterator.next()).done); _iteratorNormalCompletion = true) {\n                    var node = _step.value;\n\n                    // 增行\n                    var newLine = dataGrid.addLine();\n                    // 设置节点\n                    dataGrid.setRowData(newLine.rowIndex, {\n                        lineId: node,\n                        // 适用产线带出配方的报工模式\n                        reportType: reportType\n                    });\n                }\n            } catch (err) {\n                _didIteratorError = true;\n                _iteratorError = err;\n            } finally {\n                try {\n                    if (!_iteratorNormalCompletion && _iterator.return) {\n                        _iterator.return();\n                    }\n                } finally {\n                    if (_didIteratorError) {\n                        throw _iteratorError;\n                    }\n                }\n            }\n\n            ReactAPI.showMessage(\"s\", \"添加成功！\");\n        }\n    };\n}","id":"add","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"funcbody":"function deleteRowEvent(event) {\n    // 产线表\n    let lineDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''RM_1.0.0_formula_easyArrSuitlineEditdg1575265759720'');\n    let selecteds = lineDataGrid.getSelecteds();\n    if (!selecteds.length) {\n        // 如果没有选节点，则报“请选择一条记录进行操作！”\n        ReactAPI.showMessage(\"w\", ReactAPI.international.getText(''SupDatagrid.button.error''));\n        return;\n    }\n    // 弹出确认框\n    ReactAPI.openConfirm({\n        message: ReactAPI.international.getText(''SupDatagrid.button.delete''),\n        onOk: () => {\n            let rowIndex = selecteds[0].rowIndex;\n            // 删除选中行\n            lineDataGrid.deleteLine(rowIndex.toString());\n            ReactAPI.closeConfirm();\n        }\n    });\n}","funcname":"onclick=''deleteRowEvent(event)''","buttonstyle":"del","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1575265759734_2","isHide":false,"showname":"删行","pc":"__pc__=Uk1fMS4wLjBfZm9ybXVsYV9lYXN5QXJyU3VpdGxpbmVFZGl0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"namekey":"RM.buttonPropertyshowName.randon1574995258625.flag","