ice/print/customViewSelect?viewCode='' + viewCode,\n        async: false\n    }, function (res) {\n\n        if (res.code!=200 || !res.data.result || res.data.result.length == 0) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''com.supcon.orchid.container.exceptions.NO_PRINTSERVICECONFIG''));\n            console.log(\"模板未配置!!com.supcon.orchid.container.exceptions.NO_PRINTSERVICECONFIG\");\n        } else {\n            var printCode = res.data.result[0].code;\n            ReactAPI.request({\n                url: ''/msService/EAM/baseInfo/baseInfo/printOnServer?viewCode='' + viewCode + ''&templateCode='' + printCode + ''&id='' + id,\n                type: ''get'', async: false\n            }, function (res2) {\n                window.open(\"/bap/public/print/\" + res2.data.pdfFileName + ''.pdf'');\n            });\n        }\n    });\n}","id":"qrCodePrint","operatetype":"CUSTOM","isconfirm":false,"CODE":"baseInfoPart_qrCodePrint_add_EAM_1.0.0_baseInfo_baseInfoPart","NAME":"打印设备标识","ICONCLS":"cui-btn-add","USEINMORE":false,"SEPARATENUM":"0"},{"confirmcontent":null,"isusemore":false,"buttonstyle":"dy","iscustomfunc":false,"deletestaffid":null,"buttonoperationcode":"baseInfoPart_batchPrint_dy_EAM_1.0.0_baseInfo_baseInfoPart","regionType":null,"cellcode":null,"id":"batchPrint","events":[],"viewselect":null,"buttonalign":null,"deletestaff":null,"version":2,"projflag":false,"name":"batchPrint","operatetype":"BATCH_PRINT","signaturetype":null,"isconfirm":false,"isSignatureConfig":true,"code":"EAM_1.0.0_baseInfo_baseInfoPart_print_batchPrint","deletetime":null,"modifytime":null,"roleid":null,"ispermission":false,"createstaff":null,"powertype":null,"valid":true,"ecEnv":"product","signerid":null,"positionid":null,"operateurl":null,"configmap":null,"namekey":"ec.print.batchPrint","datagrid":null,"modifystaffid":null,"ishide":false,"scriptcode":null,"createtime":1614917029842,"signatureenabled":false,"isPublished":false,"modifystaff":null,"createstaff