idKey).getSelecteds();\n    if (selectList.length == 0) {\n        //BaseSet.certificateLevel.chooseOneRecord  请选择一条记录!\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''BaseSet.certificateLevel.chooseOneRecord''));\n        return;\n    }\n\n    if (selectList.length > 1) {\n        //foundation.common.currency.onlyonedatacanbeselectedforoperation  只能选择一条数据进行操作！\n        ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''foundation.common.currency.onlyonedatacanbeselectedforoperation''));\n        return;\n    }\n\n    var id = selectList[0].id;\n    var viewCode = ''EAM_1.0.0_baseInfo_baseInfoPart'';\n    ReactAPI.request({\n        url: ''/msService/baseService/print/customViewSelect?viewCode='' + viewCode,\n        async: false\n    }, function (res) {\n\n        if (res.code!=200 || !res.data.result || res.data.result.length == 0) {\n            ReactAPI.showMessage(\"f\", ReactAPI.international.getText(''com.supcon.orchid.container.exceptions.NO_PRINTSERVICECONFIG''));\n            console.log(\"模板未配置!!com.supcon.orchid.container.exceptions.NO_PRINTSERVICECONFIG\")\n        } else {\n            var printCode = res.data.result[0].code;\n            ReactAPI.request({\n                url: ''/msService/EAM/baseInfo/baseInfo/printOnServer?viewCode='' + viewCode + ''&templateCode='' + printCode + ''&id='' + id,\n                type: ''get'', async: false\n            }, function (res2) {\n                window.open(\"/bap/public/print/\" + res2.data.pdfFileName + ''.pdf'')\n            });\n        }\n    });\n\n}","funcname":"onclick=''printQRCode()''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1589789774797_3921","buttonoperationcode":"baseInfoPart_qrCodePrint_add_EAM_1.0.0_baseInfo_baseInfoPart","isHide":true,"showname":"打印设备标识","ecEnv":"product","pc":"__pc__=RUFNXzEuMC4wX2Jhc2VJbmZvX2Jhc2VJbmZvTGF5b3V0X3NlbGZ8","regionType":"BUTTON","iscallback":false,"mo